files.src/adapters/ascii_renderer.rs:
 1: use crate::domain::entities::grid::Grid;
 2: 
 3: /// Interface for rendering the grid.
 4: pub trait GridRenderer {
 5:     fn render(&self, grid: &Grid) -> String;
 6: }
 7: 
 8: /// A concrete adapter that renders the Grid as an ASCII string.
 9: /// This fulfills the Clean Architecture requirement of decoupling the domain logic
10: /// from the presentation layer.
11: pub struct AsciiRenderer;
12: 
13: impl GridRenderer for AsciiRenderer {
14:     fn render(&self, grid: &Grid) -> String {
15:         let mut output = String::new();
16: 
17:         for y in 0..grid.depth() {
18:             // Top walls for this row
19:             for x in 0..grid.width() {
20:                 let cell = grid.get(x, y).unwrap();
21:                 output.push('+');
22:                 if cell.walls[0] {
23:                     // North
24:                     output.push_str("---");
25:                 } else {
26:                     output.push_str("   ");
27:                 }
28:             }
29:             output.push_str("+\n");
30: 
31:             // Side walls for this row
32:             for x in 0..grid.width() {
33:                 let cell = grid.get(x, y).unwrap();
34:                 if cell.walls[3] {
35:                     // West
36:                     output.push('|');
37:                 } else {
38:                     output.push(' ');
39:                 }
40:                 output.push_str("   "); // Inside of the room
41:             }
42:             // East wall of the last cell in the row
43:             let last_cell = grid.get(grid.width() - 1, y).unwrap();
44:             if last_cell.walls[1] {
45:                 // East
46:                 output.push('|');
47:             } else {
48:                 output.push(' ');
49:             }
50:             output.push('\n');
51:         }
52: 
53:         // Bottom walls for the last row
54:         for x in 0..grid.width() {
55:             let cell = grid.get(x, grid.depth() - 1).unwrap();
56:             output.push('+');
57:             if cell.walls[2] {
58:                 // South
59:                 output.push_str("---");
60:             } else {
61:                 output.push_str("   ");
62:             }
63:         }
64:         output.push_str("+\n");
65: 
66:         output
67:     }
68: }
69: 
70: #[cfg(test)]
71: mod tests {
72:     use super::*;
73:     use crate::domain::entities::grid::Grid;
74: 
75:     #[test]
76:     fn test_ascii_renderer() {
77:         let mut grid = Grid::new(2, 2);
78:         // Modify some walls to test rendering
79:         if let Some(cell) = grid.get_mut(0, 0) {
80:             cell.walls[1] = false; // Remove East wall of (0,0)
81:         }
82:         if let Some(cell) = grid.get_mut(1, 0) {
83:             cell.walls[3] = false; // Remove West wall of (1,0)
84:         }
85: 
86:         let renderer = AsciiRenderer;
87:         let output = renderer.render(&grid);
88: 
89:         // Very basic validation, actual visual check is better in integration tests
90:         assert!(output.contains("+---+---+"));
91:     }
92: }

files.src/adapters/json_presenter.rs:
 1: use crate::adapters::voxel_mapper::{FaceDirection, MergedQuad, VoxelType};
 2: 
 3: /// Interface Adapter to convert MergedQuads to JSON format for the web presentation layer.
 4: pub struct JsonPresenter;
 5: 
 6: impl JsonPresenter {
 7:     pub fn render_voxels(quads: &[MergedQuad]) -> String {
 8:         let mut json = String::with_capacity(quads.len() * 100);
 9:         json.push('[');
10: 
11:         for (i, quad) in quads.iter().enumerate() {
12:             let dir_str = match quad.dir {
13:                 FaceDirection::Up => "\"up\"",
14:                 FaceDirection::Down => "\"down\"",
15:                 FaceDirection::North => "\"north\"",
16:                 FaceDirection::South => "\"south\"",
17:                 FaceDirection::East => "\"east\"",
18:                 FaceDirection::West => "\"west\"",
19:             };
20: 
21:             let type_str = match quad.v_type {
22:                 VoxelType::Wall => "\"wall\"",
23:                 VoxelType::Floor => "\"floor\"",
24:                 VoxelType::Ceiling => "\"ceiling\"",
25:                 VoxelType::Light => "\"light\"",
26:                 VoxelType::RedWall => "\"redwall\"",
27:             };
28: 
29:             let obj = format!(
30:                 "{{\"x\":{},\"y\":{},\"z\":{},\"w\":{},\"h\":{},\"dir\":{},\"type\":{},\"color\":{}}}",
31:                 quad.x, quad.y, quad.z, quad.w, quad.h, dir_str, type_str, quad.color
32:             );
33: 
34:             json.push_str(&obj);
35:             if i < quads.len() - 1 {
36:                 json.push(',');
37:             }
38:         }
39: 
40:         json.push(']');
41:         json
42:     }
43: }
44: 
45: #[cfg(test)]
46: mod tests {
47:     use super::*;
48: 
49:     #[test]
50:     fn test_json_rendering() {
51:         let quads = vec![MergedQuad {
52:             x: 0.0,
53:             y: 1.0,
54:             z: 2.0,
55:             w: 4.0,
56:             h: 1.0,
57:             dir: FaceDirection::Up,
58:             v_type: VoxelType::Wall,
59:             color: 1441813,
60:         }];
61: 
62:         let json = JsonPresenter::render_voxels(&quads);
63:         assert_eq!(
64:             json,
65:             r#"[{"x":0,"y":1,"z":2,"w":4,"h":1,"dir":"up","type":"wall","color":1441813}]"#
66:         );
67:     }
68: }

