files.src/adapters/octree_gpu_serializer.rs:
  1: use crate::domain::entities::sparse_voxel_octree::{SparseVoxelOctree, SvoNode};
  2: 
  3: /// Represents SVO flattened data formatted for direct WebGL2 texture upload.
  4: #[derive(Debug, Clone)]
  5: pub struct OctreeGpuData {
  6:     pub texture_width: u32,
  7:     pub texture_height: u32,
  8:     pub texel_data: Vec<u32>,
  9: }
 10: 
 11: /// GPU Adapter to flatten the Sparse Voxel Octree into a GPU-compatible texture format.
 12: ///
 13: /// DOCUMENTED ENCODING SCHEME (RGBA32UI texture format):
 14: /// Each SVO node occupies exactly one texel (4 x 32-bit unsigned integers: R, G, B, A).
 15: ///
 16: /// CHANNEL LAYOUT:
 17: /// - **R (x):** Node Type Flag
 18: ///   * `0` = Internal Parent Node
 19: ///   * `1` = Leaf Voxel Node
 20: ///
 21: /// - **G (y):** Payload 1
 22: ///   * If Internal Node (`R == 0`): `child_base_index` (uint32) - Index in the texture
 23: ///     of the first child. The remaining 7 children are stored contiguously at indices
 24: ///     `child_base_index + 1` through `child_base_index + 7`.
 25: ///   * If Leaf Node (`R == 1`): `voxel_type` (uint32) - Voxel type ID (e.g., WALL, FLOOR, etc.).
 26: ///
 27: /// - **B (z):** Payload 2
 28: ///   * If Internal Node (`R == 0`): `child_mask` (uint32) - 8-bit active children mask.
 29: ///     Bit `i` is `1` if child `i` is non-empty, and `0` if child `i` is empty air.
 30: ///   * If Leaf Node (`R == 1`): `color` (uint32) - 24-bit packed RGB color (`0xRRGGBB`).
 31: ///
 32: /// - **A (w):** Payload 3
 33: ///   * If Internal Node (`R == 0`): `0` (Padding).
 34: ///   * If Leaf Node (`R == 1`): `light_level` (uint32) - BFS-propagated light level (`0` to `15`).
 35: pub struct OctreeGpuSerializer;
 36: 
 37: impl OctreeGpuSerializer {
 38:     /// Serializes SVO nodes into texture-ready data, padding the last row to maintain grid alignment.
 39:     pub fn serialize_to_gpu_data(octree: &SparseVoxelOctree) -> OctreeGpuData {
 40:         let num_nodes = octree.nodes.len();
 41:         let texture_width = 1024; // Standard GPU texture row size
 42:         let total_texels = ((num_nodes + texture_width - 1) / texture_width) * texture_width;
 43: 
 44:         let mut texel_data = Vec::with_capacity(total_texels * 4);
 45: 
 46:         for node in &octree.nodes {
 47:             match *node {
 48:                 SvoNode::Leaf {
 49:                     voxel_type,
 50:                     color,
 51:                     light_level,
 52:                     face_occlusion,
 53:                 } => {
 54:                     texel_data.push(1); // R
 55:                     texel_data.push(voxel_type as u32); // G
 56:                     texel_data.push(color); // B
 57:                     texel_data.push((face_occlusion as u32) << 8 | (light_level as u32)); // A
 58:                 }
 59:                 SvoNode::Internal {
 60:                     child_base_index,
 61:                     child_mask,
 62:                 } => {
 63:                     texel_data.push(0); // R
 64:                     texel_data.push(child_base_index); // G
 65:                     texel_data.push(child_mask as u32); // B
 66:                     texel_data.push(0); // A
 67:                 }
 68:             }
 69:         }
 70: 
 71:         // Pad the last row with empty leaves to prevent out-of-bound shader fetches
 72:         let padded_nodes_count = total_texels - num_nodes;
 73:         for _ in 0..padded_nodes_count {
 74:             texel_data.push(1); // Leaf
 75:             texel_data.push(0); // Air
 76:             texel_data.push(0); // Color
 77:             texel_data.push(0); // Light Level
 78:         }
 79: 
 80:         let texture_height = (total_texels / texture_width) as u32;
 81: 
 82:         OctreeGpuData {
 83:             texture_width: texture_width as u32,
 84:             texture_height,
 85:             texel_data,
 86:         }
 87:     }
 88: }
 89: 
 90: #[cfg(test)]
 91: mod tests {
 92:     use super::*;
 93: 
 94:     #[test]
 95:     fn test_gpu_serialization_padding() {
 96:         let mut octree = SparseVoxelOctree::new(2, 4.0);
 97:         octree.set(0, 0, 0, 1, 0xFF00FF, 15, 0);
 98: 
 99:         let gpu_data = OctreeGpuSerializer::serialize_to_gpu_data(&octree);
100: 
101:         // Verification tests
102:         assert_eq!(gpu_data.texture_width, 1024);
103:         assert_eq!(
104:             gpu_data.texel_data.len(),
105:             (gpu_data.texture_width * gpu_data.texture_height * 4) as usize
106:         );
107: 
108:         // Index 0 maps to texel (0, 0)
109:         let index = 0;
110:         let tx = index % 1024;
111:         let ty = index / 1024;
112:         assert_eq!(tx, 0);
113:         assert_eq!(ty, 0);
114: 
115:         // Ensure child_base_index values stay within texture range
116:         for node in &octree.nodes {
117:             if let SvoNode::Internal {
118:                 child_base_index, ..
119:             } = *node
120:             {
121:                 let max_index = child_base_index + 7;
122:                 assert!(max_index < (gpu_data.texture_width * gpu_data.texture_height));
123:             }
124:         }
125:     }
126: }

files.src/adapters/voxel_mapper.rs:
  1: use crate::domain::entities::voxel_grid::{
  2:     VOXEL_AIR, VOXEL_CEILING, VOXEL_FLOOR, VOXEL_LIGHT, VOXEL_RED_WALL, VOXEL_WALL, VOXEL_RED_LIGHT, VoxelGrid,
  3: };
  4: 
  5: #[derive(Debug, Clone, PartialEq, Eq)]
  6: pub enum VoxelType {
  7:     Wall,
  8:     Floor,
  9:     Ceiling,
 10:     Light,
 11:     RedWall,
 12: }
 13: 
 14: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
 15: pub enum FaceDirection {
 16:     Up,
 17:     Down,
 18:     North,
 19:     South,
 20:     East,
 21:     West,
 22: }
 23: 
 24: #[derive(Debug, Clone, PartialEq)]
 25: pub struct MergedQuad {
 26:     pub x: f32,
 27:     pub y: f32,
 28:     pub z: f32,
 29:     pub w: f32,
 30:     pub h: f32,
 31:     pub dir: FaceDirection,
 32:     pub v_type: VoxelType,
 33:     pub color: u32,
 34: }
 35: 
 36: pub struct VoxelMapper {
 37:     pub voxel_scale: f32,
 38: }
 39: 
 40: impl VoxelMapper {
 41:     pub fn new(voxel_scale: f32) -> Self {
 42:         Self { voxel_scale }
 43:     }
 44: 
 45:     /// Maps the 3D VoxelGrid into a list of merged quads using Greedy Meshing.
 46:     pub fn map_voxel_grid(&self, grid: &VoxelGrid) -> Vec<MergedQuad> {
 47:         let mut quads = Vec::new();
 48:         let scale = self.voxel_scale;
 49: 
 50:         let apply_light = |base_color: u32, light_level: u8| -> u32 {
 51:             let normalized = light_level as f32 / 15.0;
 52:             let mult = 0.25 + (normalized * normalized) * 0.75;
 53:             let r = ((base_color >> 16) & 0xFF) as f32 * mult;
 54:             let g = ((base_color >> 8) & 0xFF) as f32 * mult;
 55:             let b = (base_color & 0xFF) as f32 * mult;
 56:             ((r as u32) << 16) | ((g as u32) << 8) | (b as u32)
 57:         };
 58: 
 59:         let get_voxel_type = |v_id: u8| -> VoxelType {
 60:             match v_id {
 61:                 VOXEL_WALL => VoxelType::Wall,
 62:                 VOXEL_FLOOR => VoxelType::Floor,
 63:                 VOXEL_CEILING => VoxelType::Ceiling,
 64:                 VOXEL_LIGHT | VOXEL_RED_LIGHT => VoxelType::Light,
 65:                 VOXEL_RED_WALL => VoxelType::RedWall,
 66:                 _ => VoxelType::Wall,
 67:             }
 68:         };
 69: 
 70:         let get_voxel_color = |x: usize, y: usize, z: usize| -> u32 {
 71:             let v_id = grid.get(x, y, z);
 72:             let ll = grid.get_light(x, y, z);
 73:             let base_color = match v_id {
 74:                 VOXEL_WALL => 0xddcc66,
 75:                 VOXEL_FLOOR => 0x998811,
 76:                 VOXEL_CEILING => 0xcccccc,
 77:                 VOXEL_LIGHT => 0xffffff,
 78:                 VOXEL_RED_LIGHT => 0xff4444,
 79:                 VOXEL_RED_WALL => 0x880000,
 80:                 _ => 0x000000,
 81:             };
 82: 
 83:             if v_id == VOXEL_LIGHT || v_id == VOXEL_RED_LIGHT {
 84:                 base_color
 85:             } else {
 86:                 apply_light(base_color, ll)
 87:             }
 88:         };
 89: 
 90:         let w_dim = grid.width();
 91:         let h_dim = grid.height();
 92:         let d_dim = grid.depth();
 93: 
 94:         // 1. UP FACES (+Y)
 95:         for y in 0..h_dim {
 96:             let get_face = |x: usize, z: usize| -> Option<(VoxelType, u32)> {
 97:                 let v = grid.get(x, y, z);
 98:                 if v != VOXEL_AIR && (y == h_dim - 1 || grid.get(x, y + 1, z) == VOXEL_AIR) {
 99:                     Some((get_voxel_type(v), get_voxel_color(x, y, z)))
100:                 } else {
101:                     None
102:                 }
103:             };
104:             let merged = self.greedy_mesh_2d(w_dim, d_dim, &get_face);
105:             for (u, v, qw, qh, vt, col) in merged {
106:                 quads.push(MergedQuad {
107:                     x: u as f32 * scale,
108:                     y: y as f32 * scale,
109:                     z: v as f32 * scale,
110:                     w: qw as f32 * scale,
111:                     h: qh as f32 * scale,
112:                     dir: FaceDirection::Up,
113:                     v_type: vt,
114:                     color: col,
115:                 });
116:             }
117:         }
118: 
119:         // 2. DOWN FACES (-Y)
120:         for y in 0..h_dim {
121:             let get_face = |x: usize, z: usize| -> Option<(VoxelType, u32)> {
122:                 let v = grid.get(x, y, z);
123:                 if v != VOXEL_AIR && (y == 0 || grid.get(x, y - 1, z) == VOXEL_AIR) {
124:                     Some((get_voxel_type(v), get_voxel_color(x, y, z)))
125:                 } else {
126:                     None
127:                 }
128:             };
129:             let merged = self.greedy_mesh_2d(w_dim, d_dim, &get_face);
130:             for (u, v, qw, qh, vt, col) in merged {
131:                 quads.push(MergedQuad {
132:                     x: u as f32 * scale,
133:                     y: y as f32 * scale,
134:                     z: v as f32 * scale,
135:                     w: qw as f32 * scale,
136:                     h: qh as f32 * scale,
137:                     dir: FaceDirection::Down,
138:                     v_type: vt,
139:                     color: col,
140:                 });
141:             }
142:         }
143: 
144:         // 3. NORTH FACES (-Z)
145:         for z in 0..d_dim {
146:             let get_face = |x: usize, y: usize| -> Option<(VoxelType, u32)> {
147:                 let v = grid.get(x, y, z);
148:                 if v != VOXEL_AIR && (z == 0 || grid.get(x, y, z - 1) == VOXEL_AIR) {
149:                     Some((get_voxel_type(v), get_voxel_color(x, y, z)))
150:                 } else {
151:                     None
152:                 }
153:             };
154:             let merged = self.greedy_mesh_2d(w_dim, h_dim, &get_face);
155:             for (u, v, qw, qh, vt, col) in merged {
156:                 quads.push(MergedQuad {
157:                     x: u as f32 * scale,
158:                     y: v as f32 * scale,
159:                     z: z as f32 * scale,
160:                     w: qw as f32 * scale,
161:                     h: qh as f32 * scale,
162:                     dir: FaceDirection::North,
163:                     v_type: vt,
164:                     color: col,
165:                 });
166:             }
167:         }
168: 
169:         // 4. SOUTH FACES (+Z)
170:         for z in 0..d_dim {
171:             let get_face = |x: usize, y: usize| -> Option<(VoxelType, u32)> {
172:                 let v = grid.get(x, y, z);
173:                 if v != VOXEL_AIR && (z == d_dim - 1 || grid.get(x, y, z + 1) == VOXEL_AIR) {
174:                     Some((get_voxel_type(v), get_voxel_color(x, y, z)))
175:                 } else {
176:                     None
177:                 }
178:             };
179:             let merged = self.greedy_mesh_2d(w_dim, h_dim, &get_face);
180:             for (u, v, qw, qh, vt, col) in merged {
181:                 quads.push(MergedQuad {
182:                     x: u as f32 * scale,
183:                     y: v as f32 * scale,
184:                     z: z as f32 * scale,
185:                     w: qw as f32 * scale,
186:                     h: qh as f32 * scale,
187:                     dir: FaceDirection::South,
188:                     v_type: vt,
189:                     color: col,
190:                 });
191:             }
192:         }
193: 
194:         // 5. EAST FACES (+X)
195:         for x in 0..w_dim {
196:             let get_face = |z: usize, y: usize| -> Option<(VoxelType, u32)> {
197:                 let v = grid.get(x, y, z);
198:                 if v != VOXEL_AIR && (x == w_dim - 1 || grid.get(x + 1, y, z) == VOXEL_AIR) {
199:                     Some((get_voxel_type(v), get_voxel_color(x, y, z)))
200:                 } else {
201:                     None
202:                 }
203:             };
204:             let merged = self.greedy_mesh_2d(d_dim, h_dim, &get_face);
205:             for (u, v, qw, qh, vt, col) in merged {
206:                 quads.push(MergedQuad {
207:                     x: x as f32 * scale,
208:                     y: v as f32 * scale,
209:                     z: u as f32 * scale,
210:                     w: qw as f32 * scale,
211:                     h: qh as f32 * scale,
212:                     dir: FaceDirection::East,
213:                     v_type: vt,
214:                     color: col,
215:                 });
216:             }
217:         }
218: 
219:         // 6. WEST FACES (-X)
220:         for x in 0..w_dim {
221:             let get_face = |z: usize, y: usize| -> Option<(VoxelType, u32)> {
222:                 let v = grid.get(x, y, z);
223:                 if v != VOXEL_AIR && (x == 0 || grid.get(x - 1, y, z) == VOXEL_AIR) {
224:                     Some((get_voxel_type(v), get_voxel_color(x, y, z)))
225:                 } else {
226:                     None
227:                 }
228:             };
229:             let merged = self.greedy_mesh_2d(d_dim, h_dim, &get_face);
230:             for (u, v, qw, qh, vt, col) in merged {
231:                 quads.push(MergedQuad {
232:                     x: x as f32 * scale,
233:                     y: v as f32 * scale,
234:                     z: u as f32 * scale,
235:                     w: qw as f32 * scale,
236:                     h: qh as f32 * scale,
237:                     dir: FaceDirection::West,
238:                     v_type: vt,
239:                     color: col,
240:                 });
241:             }
242:         }
243: 
244:         quads
245:     }
246: 
247:     /// Helper that performs 2D greedy meshing on a slice.
248:     fn greedy_mesh_2d(
249:         &self,
250:         w_slice: usize,
251:         h_slice: usize,
252:         get_face: &dyn Fn(usize, usize) -> Option<(VoxelType, u32)>,
253:     ) -> Vec<(usize, usize, usize, usize, VoxelType, u32)> {
254:         let mut visited = vec![vec![false; h_slice]; w_slice];
255:         let mut quads = Vec::new();
256: 
257:         for v in 0..h_slice {
258:             for u in 0..w_slice {
259:                 if visited[u][v] {
260:                     continue;
261:                 }
262: 
263:                 if let Some((v_type, color)) = get_face(u, v) {
264:                     // Find max width along u
265:                     let mut quad_w = 1;
266:                     while u + quad_w < w_slice {
267:                         if visited[u + quad_w][v] {
268:                             break;
269:                         }
270:                         if let Some((next_type, next_color)) = get_face(u + quad_w, v) {
271:                             if next_type == v_type && next_color == color {
272:                                 quad_w += 1;
273:                                 continue;
274:                             }
275:                         }
276:                         break;
277:                     }
278: 
279:                     // Find max height along v
280:                     let mut quad_h = 1;
281:                     'expand_h: while v + quad_h < h_slice {
282:                         for du in 0..quad_w {
283:                             if visited[u + du][v + quad_h] {
284:                                 break 'expand_h;
285:                             }
286:                             if let Some((next_type, next_color)) = get_face(u + du, v + quad_h) {
287:                                 if next_type != v_type || next_color != color {
288:                                     break 'expand_h;
289:                                 }
290:                             } else {
291:                                 break 'expand_h;
292:                             }
293:                         }
294:                         quad_h += 1;
295:                     }
296: 
297:                     // Mark matched area as visited
298:                     for dv in 0..quad_h {
299:                         for du in 0..quad_w {
300:                             visited[u + du][v + dv] = true;
301:                         }
302:                     }
303: 
304:                     quads.push((u, v, quad_w, quad_h, v_type, color));
305:                 }
306:             }
307:         }
308:         quads
309:     }
310: }
