321:         let mapper = VoxelMapper::new(1.0);
322:         let quads = mapper.map_voxel_grid(&grid);
323: 
324:         // Single isolated wall block should have 6 faces merged as 6 quads of size 1x1
325:         assert_eq!(quads.len(), 6);
