  1: /// Represents a node inside the Sparse Voxel Octree (SVO).
  2: /// Implements a linearized, GPU-friendly design stored in a flat arena array.
  3: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
  4: pub enum SvoNode {
  5:     /// Leaf node storing actual voxel attributes
  6:     Leaf {
  7:         voxel_type: u8,
  8:         color: u32,
  9:         light_level: u8,
 10:         face_occlusion: u8,
 11:     },
 12:     /// Internal parent node directing traversal to 8 children
 13:     Internal {
 14:         /// Base index in the arena vector where the 8 children nodes are stored contiguously.
 15:         child_base_index: u32,
 16:         /// Bitmask where bit `i` represents if child `i` is non-empty (1) or empty air (0).
 17:         child_mask: u8,
 18:     },
 19: }
 20: 
 21: /// The Sparse Voxel Octree aggregate root entity.
 22: #[derive(Debug, Clone, PartialEq)]
 23: pub struct SparseVoxelOctree {
 24:     pub root: usize,
 25:     pub nodes: Vec<SvoNode>,
 26:     pub depth: u32,
 27:     pub world_size: f32,
 28: }
 29: 
 30: impl SparseVoxelOctree {
 31:     /// Creates a new empty Sparse Voxel Octree.
 32:     pub fn new(depth: u32, world_size: f32) -> Self {
 33:         let root_node = SvoNode::Leaf {
 34:             voxel_type: 0,
 35:             color: 0,
 36:             light_level: 0,
 37:             face_occlusion: 0,
 38:         };
 39:         Self {
 40:             root: 0,
 41:             nodes: vec![root_node],
 42:             depth,
 43:             world_size,
 44:         }
 45:     }
 46: 
 47:     /// Checks if the SVO is entirely empty (air).
 48:     pub fn is_empty(&self) -> bool {
 49:         match self.nodes[self.root] {
 50:             SvoNode::Leaf { voxel_type, .. } => voxel_type == 0,
 51:             SvoNode::Internal { child_mask, .. } => child_mask == 0,
 52:         }
 53:     }
 54: 
 55:     /// Queries the SVO for voxel attributes at integer coordinates `(x, y, z)`.
 56:     pub fn get(&self, x: u32, y: u32, z: u32) -> Option<(u8, u32, u8, u8)> {
 57:         let max_coord = 1 << self.depth;
 58:         if x >= max_coord || y >= max_coord || z >= max_coord {
 59:             return None;
 60:         }
 61:         self.get_recursive(self.root, x, y, z, self.depth)
 62:     }
 63: 
 64:     fn get_recursive(
 65:         &self,
 66:         node_idx: usize,
 67:         x: u32,
 68:         y: u32,
 69:         z: u32,
 70:         depth: u32,
 71:     ) -> Option<(u8, u32, u8, u8)> {
 72:         if node_idx >= self.nodes.len() {
 73:             return None;
 74:         }
 75: 
 76:         match self.nodes[node_idx] {
 77:             SvoNode::Leaf {
 78:                 voxel_type,
 79:                 color,
 80:                 light_level,
 81:                 face_occlusion,
 82:             } => Some((voxel_type, color, light_level, face_occlusion)),
 83:             SvoNode::Internal {
 84:                 child_base_index,
 85:                 child_mask,
 86:             } => {
 87:                 if depth == 0 {
 88:                     return None;
 89:                 }
 90: 
 91:                 let bit = depth - 1;
 92:                 let octant_x = (x >> bit) & 1;
 93:                 let octant_y = (y >> bit) & 1;
 94:                 let octant_z = (z >> bit) & 1;
 95:                 let octant_idx = (octant_z << 2) | (octant_y << 1) | octant_x;
 96: 
 97:                 // Check if the octant is active in the child mask
 98:                 if (child_mask & (1 << octant_idx)) == 0 {
 99:                     return Some((0, 0, 0, 0)); // Empty air
100:                 }
101: 
102:                 let child_node_idx = child_base_index as usize + octant_idx as usize;
103:                 let mask = (1 << bit) - 1;
104:                 self.get_recursive(child_node_idx, x & mask, y & mask, z & mask, depth - 1)
105:             }
106:         }
107:     }
108: 
109:     /// Sets voxel attributes at coordinate `(x, y, z)`. Splits nodes and collapses uniform subtrees recursively.
110:     pub fn set(
111:         &mut self,
112:         x: u32,
113:         y: u32,
114:         z: u32,
115:         voxel_type: u8,
116:         color: u32,
117:         light_level: u8,
118:         face_occlusion: u8,
119:     ) {
120:         let max_coord = 1 << self.depth;
121:         if x >= max_coord || y >= max_coord || z >= max_coord {
122:             return;
123:         }
124:         self.set_recursive(
125:             self.root,
126:             x,
127:             y,
128:             z,
129:             self.depth,
130:             voxel_type,
131:             color,
132:             light_level,
133:             face_occlusion,
134:         );
135:     }
136: 
137:     fn set_recursive(
138:         &mut self,
139:         node_idx: usize,
140:         x: u32,
141:         y: u32,
142:         z: u32,
143:         depth: u32,
144:         v_type: u8,
145:         col: u32,
146:         ll: u8,
147:         fo: u8,
148:     ) {
149:         match self.nodes[node_idx] {
150:             SvoNode::Leaf {
151:                 voxel_type,
152:                 color,
153:                 light_level,
154:                 face_occlusion,
155:             } => {
156:                 if voxel_type == v_type && color == col && light_level == ll && face_occlusion == fo
157:                 {
158:                     return;
159:                 }
160: 
161:                 if depth == 0 {
162:                     self.nodes[node_idx] = SvoNode::Leaf {
163:                         voxel_type: v_type,
164:                         color: col,
165:                         light_level: ll,
166:                         face_occlusion: fo,
167:                     };
168:                     return;
169:                 }
170: 
171:                 // Split leaf node
172:                 let child_base_index = self.nodes.len() as u32;
173:                 let child_mask = if voxel_type == 0 { 0 } else { 0xFF };
174: 
175:                 for _ in 0..8 {
176:                     self.nodes.push(SvoNode::Leaf {
177:                         voxel_type,
178:                         color,
179:                         light_level,
180:                         face_occlusion,
181:                     });
182:                 }
183: 
184:                 self.nodes[node_idx] = SvoNode::Internal {
185:                     child_base_index,
186:                     child_mask,
187:                 };
188: 
189:                 self.set_recursive(node_idx, x, y, z, depth, v_type, col, ll, fo);
190:             }
191:             SvoNode::Internal {
192:                 child_base_index,
193:                 mut child_mask,
194:             } => {
195:                 let bit = depth - 1;
196:                 let octant_x = (x >> bit) & 1;
197:                 let octant_y = (y >> bit) & 1;
198:                 let octant_z = (z >> bit) & 1;
199:                 let octant_idx = (octant_z << 2) | (octant_y << 1) | octant_x;
200: 
201:                 let child_node_idx = child_base_index as usize + octant_idx as usize;
202: 
203:                 if v_type != 0 {
204:                     child_mask |= 1 << octant_idx;
205:                 }
206: 
207:                 self.nodes[node_idx] = SvoNode::Internal {
208:                     child_base_index,
209:                     child_mask,
210:                 };
211: 
212:                 let mask = (1 << bit) - 1;
213:                 self.set_recursive(
214:                     child_node_idx,
215:                     x & mask,
216:                     y & mask,
217:                     z & mask,
218:                     depth - 1,
219:                     v_type,
220:                     col,
221:                     ll,
222:                     fo,
223:                 );
224: 
225:                 // Try to collapse
226:                 self.collapse_if_uniform(node_idx);
227:             }
228:         }
229:     }
230: 
231:     fn collapse_if_uniform(&mut self, node_idx: usize) {
232:         if let SvoNode::Internal {
233:             child_base_index, ..
234:         } = self.nodes[node_idx]
235:         {
236:             let first_child_idx = child_base_index as usize;
237:             let mut uniform = true;
238:             let mut first_val = None;
239: 
240:             for i in 0..8 {
241:                 match self.nodes[first_child_idx + i] {
242:                     SvoNode::Internal { .. } => {
243:                         uniform = false;
244:                         break;
245:                     }
246:                     SvoNode::Leaf {
247:                         voxel_type,
248:                         color,
249:                         light_level,
250:                         face_occlusion,
251:                     } => {
252:                         if let Some((vt, col, ll, fo)) = first_val {
253:                             if vt != voxel_type
254:                                 || col != color
255:                                 || ll != light_level
256:                                 || fo != face_occlusion
257:                             {
258:                                 uniform = false;
259:                                 break;
260:                             }
261:                         } else {
262:                             first_val = Some((voxel_type, color, light_level, face_occlusion));
263:                         }
264:                     }
265:                 }
266:             }
267: 
268:             if uniform {
269:                 if let Some((vt, col, ll, fo)) = first_val {
270:                     self.nodes[node_idx] = SvoNode::Leaf {
271:                         voxel_type: vt,
272:                         color: col,
273:                         light_level: ll,
274:                         face_occlusion: fo,
275:                     };
276:                 }
277:             }
278:         }
279:     }
280: }

  1: use crate::domain::entities::voxel_grid::{VOXEL_AIR, VOXEL_LIGHT, VoxelGrid};
  2: use std::collections::VecDeque;
  3: 
  4: /// Calculates 3D voxel lighting across the dense VoxelGrid using a BFS flood-fill algorithm.
  5: /// Time Complexity: O(n) where n is the number of voxels.
  6: /// Achieves pure voxel cast lighting.
  7: pub fn calculate_voxel_lighting(grid: &mut VoxelGrid) {
  8:     let w = grid.width();
  9:     let h = grid.height();
 10:     let d = grid.depth();
 11: 
 12:     let max_light: u8 = 15;
 13:     let falloff: u8 = 1;
 14: 
 15:     let mut queue: VecDeque<(usize, usize, usize, bool)> = VecDeque::new();
 16: 
 17:     // Pass 1: Find all light sources
 18:     for z in 0..d {
 19:         for y in 0..h {
 20:             for x in 0..w {
 21:                 let v = grid.get(x, y, z);
 22:                 if v == VOXEL_LIGHT || v == crate::domain::entities::voxel_grid::VOXEL_RED_LIGHT {
 23:                     grid.set_light(x, y, z, max_light);
 24:                     let is_red = v == crate::domain::entities::voxel_grid::VOXEL_RED_LIGHT;
 25:                     if is_red {
 26:                         let fo = grid.get_face_occlusion(x, y, z);
 27:                         grid.set_face_occlusion(x, y, z, fo | 0b0100_0000);
 28:                     }
 29:                     queue.push_back((x, y, z, is_red));
 30:                 }
 31:             }
 32:         }
 33:     }
 34: 
 35:     // Pass 2: BFS flood-fill 3D
 36:     while let Some((cx, cy, cz, is_red)) = queue.pop_front() {
 37:         let current_light = grid.get_light(cx, cy, cz);
 38:         if current_light <= falloff {
 39:             continue;
 40:         }
 41: 
 42:         // Check 6 directions
 43:         let neighbors: [(isize, isize, isize); 6] = [
 44:             (cx as isize + 1, cy as isize, cz as isize),
 45:             (cx as isize - 1, cy as isize, cz as isize),
 46:             (cx as isize, cy as isize + 1, cz as isize),
 47:             (cx as isize, cy as isize - 1, cz as isize),
 48:             (cx as isize, cy as isize, cz as isize + 1),
 49:             (cx as isize, cy as isize, cz as isize - 1),
 50:         ];
 51: 
 52:         for &(nx, ny, nz) in &neighbors {
 53:             if nx >= 0
 54:                 && nx < w as isize
 55:                 && ny >= 0
 56:                 && ny < h as isize
 57:                 && nz >= 0
 58:                 && nz < d as isize
 59:             {
 60:                 let (nx, ny, nz) = (nx as usize, ny as usize, nz as usize);
 61: 
 62:                 // Downward propagation has 0 falloff, creating vertical light columns
 63:                 let is_downward = ny < cy;
 64:                 let actual_falloff = if is_downward { 0 } else { falloff };
 65:                 let next_light = if current_light > actual_falloff {
 66:                     current_light - actual_falloff
 67:                 } else {
 68:                     0
 69:                 };
 70: 
 71:                 if next_light == 0 {
 72:                     continue;
 73:                 }
 74: 
 75:                 let n_type = grid.get(nx, ny, nz);
 76:                 let n_light = grid.get_light(nx, ny, nz);
 77: 
 78:                 if n_light < next_light {
 79:                     grid.set_light(nx, ny, nz, next_light);
 80:                     
 81:                     let mut fo = grid.get_face_occlusion(nx, ny, nz);
 82:                     if is_red {
 83:                         fo |= 0b0100_0000;
 84:                     } else {
 85:                         fo &= !0b0100_0000;
 86:                     }
 87:                     grid.set_face_occlusion(nx, ny, nz, fo);
 88:                     
 89:                     // Only continue propagating if it's air
 90:                     if n_type == VOXEL_AIR {
 91:                         queue.push_back((nx, ny, nz, is_red));
 92:                     }
 93:                 }
 94:             }
 95:         }
 96:     }
 97: }
 98: 
 99: #[cfg(test)]
100: mod tests {
101:     use super::*;
102: 
103:     #[test]
104:     fn test_light_propagation() {
105:         let mut grid = VoxelGrid::new(3, 3, 3);
106: 
107:         // Setup:
108:         // A single light in the middle
109:         grid.set(1, 1, 1, VOXEL_LIGHT);
110:         // A wall blocking light
111:         grid.set(2, 1, 1, crate::domain::entities::voxel_grid::VOXEL_WALL);
112: 
113:         calculate_voxel_lighting(&mut grid);
114: 
115:         assert_eq!(grid.get_light(1, 1, 1), 15);
116:         assert_eq!(grid.get_light(1, 2, 1), 14); // Above
117:         assert_eq!(grid.get_light(2, 1, 1), 14); // Wall itself lights up
118:         assert_eq!(grid.get_light(3, 1, 1), 0); // Behind the wall is out of bounds, so it returns 0 anyway
119:     }
120: }

