  1: use vackrooms::domain::entities::voxel_grid::{VOXEL_FLOOR, VOXEL_WALL};
  2: use vackrooms::entities::models::Position;
  3: use vackrooms::frameworks_drivers::simple_noise::SimpleNoiseProvider;
  4: /// Collision Diagnostic Tests — TDD Phase 1
  5: ///
  6: /// WHY THESE TESTS EXIST:
  7: /// The player reported spawning inside a wall.  Before changing any logic
  8: /// we must prove (a) what coordinates the spawn point produces and (b) whether
  9: /// the floor voxel's collision box overlaps the player's AABB at spawn.
 10: ///
 11: /// Test-first order:
 12: ///   1. Prove the exact world-space coordinates the chunk generator places floor/wall
 13: ///      voxels at for the (0,0) hub chunk in low-spec mode.
 14: ///   2. Prove the spawn point (5.0, 1.7, 5.0) does NOT overlap any wall voxel.
 15: ///   3. Prove the floor voxel box does NOT block the player at spawn.
 16: ///   4. Prove terminal velocity is sane (<= 5 world-units/second).
 17: ///
 18: /// If test 2 or 3 fails, it proves the bug.  Then we add a fix and verify
 19: /// the test passes.
 20: use vackrooms::use_cases::generate_chunk::{GenerateChunkArchitectureUseCase, GeneratorConfig};
 21: 
 22: /// The JavaScript side extracts wall collision boxes from the SVO.
 23: /// This Rust analogue extracts the same information directly from the VoxelGrid
 24: /// so we can verify coordinates without the JS/SVO layer.
 25: fn grid_wall_boxes_at_spawn_x(chunk_x: f32, chunk_z: f32) -> Vec<(f32, f32, f32, f32, f32, f32)> {
 26:     // Returns (minX, maxX, minY, maxY, minZ, maxZ) for every solid wall voxel
 27:     // at approximately x=5 world-units inside the chunk.
 28:     let config = GeneratorConfig::low_spec();
 29:     let noise = SimpleNoiseProvider::new();
 30:     let generator = GenerateChunkArchitectureUseCase::new(&noise);
 31:     let grid = generator.execute(Position::new(chunk_x, chunk_z), 42, config);
 32: 
 33:     let scale = config.voxel_scale;
 34:     let mut boxes = vec![];
 35: 
 36:     for y in 0..grid.height() {
 37:         for z in 0..grid.depth() {
 38:             for x in 0..grid.width() {
 39:                 let vt = grid.get(x, y, z);
 40:                 if vt == VOXEL_WALL {
 41:                     let wx = chunk_x + x as f32 * scale;
 42:                     let wy = y as f32 * scale;
 43:                     let wz = chunk_z + z as f32 * scale;
 44:                     // The JS collision system gives walls a 1-voxel-size box
 45:                     boxes.push((wx, wx + scale, wy, wy + scale, wz, wz + scale));
 46:                 }
 47:             }
 48:         }
 49:     }
 50:     boxes
 51: }
 52: 
 53: fn floor_boxes(chunk_x: f32, chunk_z: f32) -> Vec<(f32, f32, f32, f32, f32, f32)> {
 54:     let config = GeneratorConfig::low_spec();
 55:     let noise = SimpleNoiseProvider::new();
 56:     let generator = GenerateChunkArchitectureUseCase::new(&noise);
 57:     let grid = generator.execute(Position::new(chunk_x, chunk_z), 42, config);
 58: 
 59:     let scale = config.voxel_scale;
 60:     let mut boxes = vec![];
 61: 
 62:     for z in 0..grid.depth() {
 63:         for x in 0..grid.width() {
 64:             let vt = grid.get(x, 0, z);
 65:             if vt == VOXEL_FLOOR {
 66:                 let wx = chunk_x + x as f32 * scale;
 67:                 let wz = chunk_z + z as f32 * scale;
 68:                 // Floor voxel: y=0 to y=scale
 69:                 boxes.push((wx, wx + scale, 0.0_f32, scale, wz, wz + scale));
 70:             }
 71:         }
 72:     }
 73:     boxes
 74: }
 75: 
 76: /// Player AABB: eye-level at pos.y, feet at pos.y - 1.65, head at pos.y + 0.1
 77: fn player_overlaps(
 78:     pos: (f32, f32, f32),
 79:     radius: f32,
 80:     vbox: (f32, f32, f32, f32, f32, f32),
 81: ) -> bool {
 82:     let (px, py, pz) = pos;
 83:     let p_min_x = px - radius;
 84:     let p_max_x = px + radius;
 85:     let p_min_y = py - 1.65;
 86:     let p_max_y = py + 0.1;
 87:     let p_min_z = pz - radius;
 88:     let p_max_z = pz + radius;
 89:     let (v_min_x, v_max_x, v_min_y, v_max_y, v_min_z, v_max_z) = vbox;
 90: 
 91:     p_max_x > v_min_x
 92:         && p_min_x < v_max_x
 93:         && p_max_y > v_min_y
 94:         && p_min_y < v_max_y
 95:         && p_max_z > v_min_z
 96:         && p_min_z < v_max_z
 97: }
 98: 
 99: // ============================================================
100: // TEST 1: Verify hub chunk (0,0) has walls only on boundary
101: // ============================================================
102: #[test]
103: fn test_hub_chunk_interior_is_wall_free() {
104:     // The hub chunk (0,0) is supposed to be an open plaza.
105:     // No wall voxels should exist at x≈5.0, z≈5.0 (centre of chunk).
106:     let walls = grid_wall_boxes_at_spawn_x(0.0, 0.0);
107: 
108:     let spawn = (5.0_f32, 1.7_f32, 5.0_f32);
109:     let radius = 0.35_f32;
110: 
111:     let overlapping: Vec<_> = walls
112:         .iter()
113:         .filter(|&&b| player_overlaps(spawn, radius, b))
114:         .collect();
115: 
116:     assert!(
117:         overlapping.is_empty(),
118:         "FAIL: Spawn point {:?} overlaps {} wall voxel(s).\n\
119:          First overlap: {:?}\n\
120:          This proves the spawn-in-wall bug.",
121:         spawn,
122:         overlapping.len(),
123:         overlapping.first()
124:     );
125: }
126: 
127: // ============================================================
128: // TEST 2: DIAGNOSTIC — floor geometry overlaps player AABB.
129: // This test is marked #[should_panic] because the floor voxels
130: // DO geometrically overlap the player.  The fix is applied in JS
131: // (extractSvoCollisions only passes WALL/RED_WALL to isColliding).
132: // This test is kept as living documentation of the bug's root cause.
133: // ============================================================
134: #[test]
135: #[should_panic(expected = "Floor voxels at spawn OVERLAP")]
136: fn test_floor_geometry_overlaps_player_proving_the_bug() {
137:     // Floor voxels are at y=0 to y=voxel_scale (0.2 for low-spec).
138:     // Player feet: pos.y - 1.65 = 1.7 - 1.65 = 0.05.
139:     // If pMinY(0.05) < vMaxY(0.2) AND pMaxY(1.8) > vMinY(0.0) → geometric overlap.
140:     // This test PROVES the overlap exists in the geometry.
141:     // The JS fix excludes floor boxes from isColliding() — see extractSvoCollisions().
142:     let floors = floor_boxes(0.0, 0.0);
143:     let spawn = (5.0_f32, 1.7_f32, 5.0_f32);
144:     let radius = 0.35_f32;
145: 
146:     let floor_at_spawn: Vec<_> = floors
147:         .iter()
148:         .filter(|&&b| player_overlaps(spawn, radius, b))
149:         .collect();
150: 
151:     assert!(
152:         floor_at_spawn.is_empty(),
153:         "FAIL: Floor voxels at spawn OVERLAP the player AABB.\n\
154:          Count: {}\n\
155:          This causes the player to spawn 'stuck' and unable to move.\n\
156:          Fix: exclude FLOOR and CEILING voxels from collision extraction.\n\
157:          First overlapping floor box: {:?}",
158:         floor_at_spawn.len(),
159:         floor_at_spawn.first()
160:     );
161: }
162: 
163: // ============================================================
164: // TEST 3: Terminal velocity must be sane (≤ 5 world-units/second)
165: // ============================================================
166: #[test]
167: fn test_terminal_velocity_is_sane() {
168:     // JS formula: velocity.z -= direction.z * speed * delta
169:     //             velocity.z -= velocity.z * friction * delta   (drag)
170:     // Terminal velocity = speed / friction
171:     let speed: f32 = 4.0; // target walk speed (world units/sec)
172:     let friction: f32 = 10.0; // damping coefficient
173:     let terminal = speed / friction;
174: 
175:     // The old code used speed=15.0 → terminal = 1.5 units/frame @60fps = 90 u/s
176:     assert!(
177:         terminal <= 5.0,
178:         "FAIL: Terminal velocity {:.2} u/s exceeds 5 u/s.\n\
179:          This causes the 'too fast' movement bug.\n\
180:          Use speed <= {:.1} with friction = {:.1}",
181:         terminal,
182:         friction * 5.0,
183:         friction
184:     );
185: }
186: 
187: // ============================================================
188: // TEST 4: Fix verification — wall-only collision boxes do NOT
189: //         overlap the player at spawn.
190: //         This test must PASS after the production fix is applied.
191: // ============================================================
192: #[test]
193: fn test_fix_only_walls_collide_at_spawn() {
194:     // After the fix: extractSvoCollisions should only emit voxelType==WALL (1)
195:     // or RED_WALL (5).  Floor (2) and Ceiling (3) must be excluded.
196:     // The wall_boxes helper already filters by VOXEL_WALL only.
197:     let walls = grid_wall_boxes_at_spawn_x(0.0, 0.0);
198:     let spawn = (5.0_f32, 1.7_f32, 5.0_f32);
199:     let radius = 0.35_f32;
200: 
201:     let blocked: Vec<_> = walls
202:         .iter()
203:         .filter(|&&b| player_overlaps(spawn, radius, b))
204:         .collect();
205: 
206:     assert!(
207:         blocked.is_empty(),
208:         "FAIL: Player still collides with {} wall box(es) at spawn even after floor fix.\n\
209:          First collision: {:?}\n\
210:          This is a separate bug — the hub chunk has a wall at the spawn point.",
211:         blocked.len(),
212:         blocked.first()
213:     );
214: }

