  1: //! Input adapter: accumulates raw browser events (key codes, mouse deltas,
  2: //! pointer-lock state) and translates them into one [`InputFrame`] per tick.
  3: //!
  4: //! The driver layer feeds this from DOM event listeners; the frame loop
  5: //! drains it with [`InputCollector::take_frame`]. Keeping the mapping here —
  6: //! not in the driver — means "which key means forward" is a testable rule,
  7: //! not something buried in an event closure.
  8: 
  9: use crate::application::engine::InputFrame;
 10: use crate::application::player::MoveIntent;
 11: 
 12: #[derive(Debug, Default)]
 13: pub struct InputCollector {
 14:     intent: MoveIntent,
 15:     pending_dx: f32,
 16:     pending_dy: f32,
 17:     locked: bool,
 18:     flashlight: bool,
 19: }
 20: 
 21: impl InputCollector {
 22:     pub fn new() -> Self {
 23:         Self::default()
 24:     }
 25: 
 26:     /// Handles a keydown/keyup pair by `KeyboardEvent.code` value.
 27:     /// Unknown codes are ignored. Both WASD and arrow keys are mapped.
 28:     pub fn key_event(&mut self, code: &str, pressed: bool) {
 29:         #[cfg(target_arch = "wasm32")]
 30:         let doom = crate::DOOM_CONTROLS.load(std::sync::atomic::Ordering::Relaxed);
 31:         
 32:         #[cfg(not(target_arch = "wasm32"))]
 33:         let doom = false;
 34: 
 35:         if pressed && code == "KeyF" {
 36:             self.flashlight = !self.flashlight;
 37:         }
 38: 
 39:         if doom {
 40:             match code {
 41:                 "KeyW" | "ArrowUp" => self.intent.forward = pressed,
 42:                 "KeyS" | "ArrowDown" => self.intent.backward = pressed,
 43:                 "KeyQ" => self.intent.left = pressed,
 44:                 "KeyE" => self.intent.right = pressed,
 45:                 "KeyA" | "ArrowLeft" => self.intent.turn_left = pressed,
 46:                 "KeyD" | "ArrowRight" => self.intent.turn_right = pressed,
 47:                 _ => {}
 48:             }
 49:         } else {
 50:             match code {
 51:                 "KeyW" | "ArrowUp" => self.intent.forward = pressed,
 52:                 "KeyS" | "ArrowDown" => self.intent.backward = pressed,
 53:                 "KeyA" | "ArrowLeft" => self.intent.left = pressed,
 54:                 "KeyD" | "ArrowRight" => self.intent.right = pressed,
 55:                 "KeyQ" => self.intent.turn_left = pressed,
 56:                 "KeyE" => self.intent.turn_right = pressed,
 57:                 _ => {}
 58:             }
 59:         }
 60:     }
 61: 
 62:     /// Accumulates a mouse movement (only meaningful while pointer-locked).
 63:     pub fn mouse_delta(&mut self, dx: f32, dy: f32) {
 64:         if self.locked {
 65:             self.pending_dx += dx;
 66:             self.pending_dy += dy;
 67:         }
 68:     }
 69: 
 70:     /// Pointer lock engaged/released. Releasing clears held keys so the
 71:     /// player doesn't keep walking while the overlay is up.
 72:     pub fn set_locked(&mut self, locked: bool) {
 73:         self.locked = locked;
 74:         if !locked {
 75:             self.intent = MoveIntent::default();
 76:             self.pending_dx = 0.0;
 77:             self.pending_dy = 0.0;
 78:         }
 79:     }
 80: 
 81:     pub fn is_locked(&self) -> bool {
 82:         self.locked
 83:     }
 84: 
 85:     /// Drains accumulated input into a frame snapshot. Mouse deltas reset;
 86:     /// key intent persists until the matching keyup.
 87:     pub fn take_frame(&mut self) -> InputFrame {
 88:         let frame = InputFrame {
 89:             intent: self.intent,
 90:             look_dx: self.pending_dx,
 91:             look_dy: self.pending_dy,
 92:             locked: self.locked,
 93:             flashlight: self.flashlight,
 94:         };
 95:         self.pending_dx = 0.0;
 96:         self.pending_dy = 0.0;
 97:         frame
 98:     }
 99: }
100: 
101: #[cfg(test)]
102: mod tests {
103:     use super::*;
104: 
105:     #[test]
106:     fn wasd_maps_to_intent_and_persists_across_frames() {
107:         let mut input = InputCollector::new();
108:         input.set_locked(true);
109:         input.key_event("KeyW", true);
110:         input.key_event("KeyD", true);
111:         let f1 = input.take_frame();
112:         assert!(f1.intent.forward && f1.intent.right);
113:         let f2 = input.take_frame();
114:         assert!(f2.intent.forward, "held keys persist");
115:         input.key_event("KeyW", false);
116:         assert!(!input.take_frame().intent.forward);
117:     }
118: 
119:     #[test]
120:     fn mouse_deltas_accumulate_then_drain() {
121:         let mut input = InputCollector::new();
122:         input.set_locked(true);
123:         input.mouse_delta(3.0, -1.0);
124:         input.mouse_delta(2.0, 1.0);
125:         let f = input.take_frame();
126:         assert_eq!((f.look_dx, f.look_dy), (5.0, 0.0));
127:         let f2 = input.take_frame();
128:         assert_eq!((f2.look_dx, f2.look_dy), (0.0, 0.0));
129:     }
130: 
131:     #[test]
132:     fn unlock_clears_held_keys_and_ignores_mouse() {
133:         let mut input = InputCollector::new();
134:         input.set_locked(true);
135:         input.key_event("KeyW", true);
136:         input.set_locked(false);
137:         input.mouse_delta(10.0, 10.0);
138:         let f = input.take_frame();
139:         assert!(!f.intent.forward);
140:         assert_eq!(f.look_dx, 0.0);
141:         assert!(!f.locked);
142:     }
143: }

  1: //! URL query → generation settings. Lets players share worlds by URL:
  2: //!
  3: //! `?seed=1234&pillars=0.5&walls=1.2&atria=2&lights=0.8`
  4: //!
  5: //! * `seed`    — world seed (u32; any text is hashed so words work too).
  6: //! * `pillars` — structural column density multiplier (0 = none).
  7: //! * `walls`   — office wall density multiplier (0 = open plan).
  8: //! * `atria`   — how much of the world vaults into tall atria.
  9: //! * `lights`  — ceiling light panel density.
 10: //!
 11: //! All multipliers default to 1.0 and are clamped to 0..=4. Kept free of
 12: //! web-sys so it is natively unit-tested; the browser driver only hands in
 13: //! `window.location.search`.
 14: 
 15: use vackrooms::use_cases::generate_chunk::LevelTuning;
 16: 
 17: #[derive(Debug, Clone, Copy, PartialEq)]
 18: pub struct GenerationParams {
 19:     pub seed: u32,
 20:     pub tuning: LevelTuning,
 21: }
 22: 
 23: /// Parses `window.location.search` (with or without the leading `?`).
 24: /// Unknown keys are ignored; malformed values fall back to defaults.
 25: pub fn parse_generation_params(query: &str, default_seed: u32) -> GenerationParams {
 26:     let mut params = GenerationParams {
 27:         seed: default_seed,
 28:         tuning: LevelTuning::default(),
 29:     };
 30: 
 31:     for pair in query.trim_start_matches('?').split('&') {
 32:         let Some((key, value)) = pair.split_once('=') else {
 33:             continue;
 34:         };
 35:         let knob = |t: &mut f32| {
 36:             if let Ok(v) = value.parse::<f32>() {
 37:                 if v.is_finite() {
 38:                     *t = v.clamp(0.0, 4.0);
 39:                 }
 40:             }
 41:         };
 42:         match key {
 43:             "seed" => {
 44:                 params.seed = value.parse::<u32>().unwrap_or_else(|_| hash_seed(value));
 45:             }
 46:             "pillars" => knob(&mut params.tuning.pillars),
 47:             "walls" => knob(&mut params.tuning.walls),
 48:             "atria" => knob(&mut params.tuning.atria),
 49:             "lights" => knob(&mut params.tuning.lights),
 50:             _ => {}
 51:         }
 52:     }
 53:     params
 54: }
 55: 
 56: /// Non-numeric seeds ("?seed=kitten") hash to a stable u32 (FNV-1a).
 57: fn hash_seed(text: &str) -> u32 {
 58:     let mut h: u32 = 0x811C_9DC5;
 59:     for b in text.bytes() {
 60:         h ^= b as u32;
 61:         h = h.wrapping_mul(0x0100_0193);
 62:     }
 63:     h
 64: }
 65: 
 66: #[cfg(test)]
 67: mod tests {
 68:     use super::*;
 69: 
 70:     #[test]
 71:     fn defaults_when_query_is_empty() {
 72:         let p = parse_generation_params("", 42);
 73:         assert_eq!(p.seed, 42);
 74:         assert_eq!(p.tuning, LevelTuning::default());
 75:     }
 76: 
 77:     #[test]
 78:     fn parses_seed_and_knobs() {
 79:         let p = parse_generation_params("?seed=7&pillars=0.5&walls=2&atria=0&lights=1.5", 42);
 80:         assert_eq!(p.seed, 7);
 81:         assert_eq!(p.tuning.pillars, 0.5);
 82:         assert_eq!(p.tuning.walls, 2.0);
 83:         assert_eq!(p.tuning.atria, 0.0);
 84:         assert_eq!(p.tuning.lights, 1.5);
 85:     }
 86: 
 87:     #[test]
 88:     fn text_seeds_hash_deterministically() {
 89:         let a = parse_generation_params("seed=kitten", 42);
 90:         let b = parse_generation_params("seed=kitten", 42);
 91:         assert_eq!(a.seed, b.seed);
 92:         assert_ne!(a.seed, 42);
 93:     }
 94: 
 95:     #[test]
 96:     fn junk_values_are_ignored_and_clamped() {
 97:         let p = parse_generation_params("?pillars=banana&walls=99&renderer=cpu&spec=high", 42);
 98:         assert_eq!(p.tuning.pillars, 1.0);
 99:         assert_eq!(p.tuning.walls, 4.0);
100:     }
101: }

  1: //! Axis-aligned collision primitives and the sliding-collision world.
  2: //!
  3: //! Collision geometry is *derived from the SVO itself* (solid leaf nodes of
  4: //! type WALL / RED_WALL become world-space boxes), so the physical world and
  5: //! the rendered world can never drift apart.
  6: 
  7: /// Axis-aligned bounding box in world space.
  8: #[derive(Debug, Clone, Copy, PartialEq)]
  9: pub struct Aabb {
 10:     pub min: [f32; 3],
 11:     pub max: [f32; 3],
 12: }
 13: 
 14: impl Aabb {
 15:     pub fn new(min: [f32; 3], max: [f32; 3]) -> Self {
 16:         Self { min, max }
 17:     }
 18: 
 19:     pub fn intersects(&self, other: &Aabb) -> bool {
 20:         self.max[0] > other.min[0]
 21:             && self.min[0] < other.max[0]
 22:             && self.max[1] > other.min[1]
 23:             && self.min[1] < other.max[1]
 24:             && self.max[2] > other.min[2]
 25:             && self.min[2] < other.max[2]
 26:     }
 27: }
 28: 
 29: /// Player capsule approximated as an AABB, matching the original client:
 30: /// radius 0.35 around the eye, extending 1.65 below and 0.1 above eye level.
 31: pub const PLAYER_RADIUS: f32 = 0.35;
 32: pub const PLAYER_EYE_TO_FEET: f32 = 1.65;
 33: pub const PLAYER_EYE_TO_HEAD: f32 = 0.1;
 34: 
 35: /// Builds the player's AABB from an eye-level position.
 36: pub fn player_aabb(eye_pos: [f32; 3]) -> Aabb {
 37:     Aabb::new(
 38:         [
 39:             eye_pos[0] - PLAYER_RADIUS,
 40:             eye_pos[1] - PLAYER_EYE_TO_FEET,
 41:             eye_pos[2] - PLAYER_RADIUS,
 42:         ],
 43:         [
 44:             eye_pos[0] + PLAYER_RADIUS,
 45:             eye_pos[1] + PLAYER_EYE_TO_HEAD,
 46:             eye_pos[2] + PLAYER_RADIUS,
 47:         ],
 48:     )
 49: }
 50: 
 51: /// The set of solid boxes the player can collide with.
 52: /// Rebuilt whenever the chunk set changes.
 53: #[derive(Debug, Default)]
 54: pub struct CollisionWorld {
 55:     boxes: Vec<Aabb>,
 56: }
 57: 
 58: impl CollisionWorld {
 59:     pub fn new() -> Self {
 60:         Self { boxes: Vec::new() }
 61:     }
 62: 
 63:     pub fn rebuild<'a, I: IntoIterator<Item = &'a Aabb>>(&mut self, boxes: I) {
 64:         self.boxes.clear();
 65:         self.boxes.extend(boxes.into_iter().copied());
 66:     }
 67: 
 68:     pub fn len(&self) -> usize {
 69:         self.boxes.len()
 70:     }
 71: 
 72:     pub fn is_empty(&self) -> bool {
 73:         self.boxes.is_empty()
 74:     }
 75: 
 76:     pub fn boxes(&self) -> &[Aabb] {
 77:         &self.boxes
 78:     }
 79: 
 80:     /// True if a player standing at `eye_pos` overlaps any solid box.
 81:     pub fn collides(&self, eye_pos: [f32; 3]) -> bool {
 82:         let p = player_aabb(eye_pos);
 83:         self.boxes.iter().any(|b| p.intersects(b))
 84:     }
 85: }
 86: 
 87: #[cfg(test)]
 88: mod tests {
 89:     use super::*;
 90: 
 91:     #[test]
 92:     fn aabb_intersection_is_exclusive_on_touching_faces() {
 93:         let a = Aabb::new([0.0, 0.0, 0.0], [1.0, 1.0, 1.0]);
 94:         let touching = Aabb::new([1.0, 0.0, 0.0], [2.0, 1.0, 1.0]);
 95:         let overlapping = Aabb::new([0.9, 0.0, 0.0], [2.0, 1.0, 1.0]);
 96:         assert!(!a.intersects(&touching));
 97:         assert!(a.intersects(&overlapping));
 98:     }
 99: 
100:     #[test]
101:     fn player_collides_with_wall_at_waist_height() {
102:         let mut world = CollisionWorld::new();
103:         world.rebuild(&[Aabb::new([1.0, 0.0, 0.0], [1.2, 3.0, 5.0])]);
104:         // Eye at 1.7 — wall spans full height, player is 0.35 wide.
105:         assert!(world.collides([1.0, 1.7, 2.0]));
106:         assert!(!world.collides([0.0, 1.7, 2.0]));
107:     }
108: 
109:     #[test]
110:     fn player_does_not_collide_with_floor_slab_below_feet() {
111:         let mut world = CollisionWorld::new();
112:         // Floor slab 0.0..0.05 — feet bottom is at 1.7 - 1.65 = 0.05 exactly:
113:         // touching, not overlapping.
114:         world.rebuild(&[Aabb::new([-10.0, 0.0, -10.0], [10.0, 0.05, 10.0])]);
115:         assert!(!world.collides([0.0, 1.7, 0.0]));
116:     }
117: }

