 1: //! Application (use-case) layer of the browser client.
 2: //!
 3: //! Everything in this module is pure Rust with no browser dependencies:
 4: //! it can be exercised by native unit tests. Outer layers communicate with
 5: //! it exclusively through the ports declared in [`ports`].
 6: 
 7: pub mod atlas;
 8: pub mod collision;
 9: pub mod engine;
10: pub mod player;
11: pub mod ports;
12: pub mod streaming;

  1: //! Chunk streaming policy and the in-memory chunk store.
  2: //!
  3: //! The world is an infinite plane of square chunks. Each frame the policy
  4: //! computes the set of chunk origins that should be resident around the
  5: //! player; the engine loads missing ones (budgeted, to avoid frame hitches —
  6: //! wasm has no threads, so time-slicing replaces the background meshing
  7: //! thread a native engine would use) and evicts the rest.
  8: 
  9: use std::collections::HashMap;
 10: 
 11: use crate::application::collision::Aabb;
 12: use crate::application::ports::ChunkPayload;
 13: 
 14: /// Integer key for a chunk, quantized from its world origin.
 15: /// Origins are always integer multiples of `chunk_size`, so rounding to
 16: /// millimetres gives a stable, hashable key.
 17: pub type ChunkKey = (i64, i64);
 18: 
 19: pub fn chunk_key(origin_x: f32, origin_z: f32) -> ChunkKey {
 20:     (
 21:         (origin_x * 1000.0).round() as i64,
 22:         (origin_z * 1000.0).round() as i64,
 23:     )
 24: }
 25: 
 26: /// Decides which chunks should be resident for a given player position.
 27: #[derive(Debug, Clone, Copy)]
 28: pub struct StreamingPolicy {
 29:     /// World-space side length of a chunk.
 30:     pub chunk_size: f32,
 31:     /// Chebyshev radius in chunks: 1 -> 3x3 resident set, 2 -> 5x5.
 32:     pub radius: i32,
 33: }
 34: 
 35: impl StreamingPolicy {
 36:     /// Returns the desired chunk origins, sorted nearest-first so the load
 37:     /// budget is always spent on the most urgent chunk.
 38:     pub fn desired_origins(&self, player_x: f32, player_z: f32) -> Vec<(f32, f32)> {
 39:         let px = if player_x.is_finite() { player_x } else { 0.0 };
 40:         let pz = if player_z.is_finite() { player_z } else { 0.0 };
 41:         let base_x = (px / self.chunk_size).floor() * self.chunk_size;
 42:         let base_z = (pz / self.chunk_size).floor() * self.chunk_size;
 43: 
 44:         let mut origins = Vec::with_capacity(((2 * self.radius + 1).pow(2)) as usize);
 45:         for dz in -self.radius..=self.radius {
 46:             for dx in -self.radius..=self.radius {
 47:                 origins.push((
 48:                     base_x + dx as f32 * self.chunk_size,
 49:                     base_z + dz as f32 * self.chunk_size,
 50:                 ));
 51:             }
 52:         }
 53:         origins.sort_by(|a, b| {
 54:             let da = (a.0 + self.chunk_size * 0.5 - px).powi(2)
 55:                 + (a.1 + self.chunk_size * 0.5 - pz).powi(2);
 56:             let db = (b.0 + self.chunk_size * 0.5 - px).powi(2)
 57:                 + (b.1 + self.chunk_size * 0.5 - pz).powi(2);
 58:             da.total_cmp(&db)
 59:         });
 60:         origins
 61:     }
 62: }
 63: 
 64: /// A resident chunk: payload plus its world origin.
 65: #[derive(Debug, Clone)]
 66: pub struct LoadedChunk {
 67:     pub origin: (f32, f32),
 68:     pub payload: ChunkPayload,
 69: }
 70: 
 71: /// Keyed store of resident chunks. Iteration order is the insertion order of
 72: /// keys (tracked separately) so atlas offsets stay deterministic.
 73: #[derive(Debug, Default)]
 74: pub struct ChunkStore {
 75:     chunks: HashMap<ChunkKey, LoadedChunk>,
 76:     order: Vec<ChunkKey>,
 77: }
 78: 
 79: impl ChunkStore {
 80:     pub fn new() -> Self {
 81:         Self {
 82:             chunks: HashMap::new(),
 83:             order: Vec::new(),
 84:         }
 85:     }
 86: 
 87:     pub fn len(&self) -> usize {
 88:         self.order.len()
 89:     }
 90: 
 91:     pub fn is_empty(&self) -> bool {
 92:         self.order.is_empty()
 93:     }
 94: 
 95:     pub fn contains(&self, key: ChunkKey) -> bool {
 96:         self.chunks.contains_key(&key)
 97:     }
 98: 
 99:     pub fn insert(&mut self, key: ChunkKey, chunk: LoadedChunk) {
100:         if self.chunks.insert(key, chunk).is_none() {
101:             self.order.push(key);
102:         }
103:     }
104: 
105:     /// Removes every chunk whose key is not in `keep`, returning whether
106:     /// anything changed.
107:     pub fn retain_keys(&mut self, keep: &[ChunkKey]) -> bool {
108:         let before = self.order.len();
109:         self.order.retain(|k| keep.contains(k));
110:         self.chunks.retain(|k, _| keep.contains(k));
111:         before != self.order.len()
112:     }
113: 
114:     /// Chunks in deterministic (insertion) order.
115:     pub fn iter_ordered(&self) -> impl Iterator<Item = &LoadedChunk> {
116:         self.order.iter().filter_map(|k| self.chunks.get(k))
117:     }
118: 
119:     /// All collision boxes of all resident chunks.
120:     pub fn all_collision_boxes(&self) -> impl Iterator<Item = &Aabb> {
121:         self.iter_ordered().flat_map(|c| c.payload.collision.iter())
122:     }
123: }
124: 
125: #[cfg(test)]
126: mod tests {
127:     use super::*;
128: 
129:     #[test]
130:     fn desired_origins_covers_square_around_player() {
131:         let policy = StreamingPolicy {
132:             chunk_size: 10.0,
133:             radius: 1,
134:         };
135:         let origins = policy.desired_origins(5.0, 5.0);
136:         assert_eq!(origins.len(), 9);
137:         // Nearest-first: the chunk containing the player comes first.
138:         assert_eq!(origins[0], (0.0, 0.0));
139:         assert!(origins.contains(&(-10.0, -10.0)));
140:         assert!(origins.contains(&(10.0, 10.0)));
141:     }
142: 
143:     #[test]
144:     fn desired_origins_handles_negative_coordinates() {
145:         let policy = StreamingPolicy {
146:             chunk_size: 10.0,
147:             radius: 1,
148:         };
149:         let origins = policy.desired_origins(-0.1, -0.1);
150:         assert_eq!(origins[0], (-10.0, -10.0));
151:     }
152: 
153:     #[test]
154:     fn store_eviction_reports_change() {
155:         let mut store = ChunkStore::new();
156:         let payload = ChunkPayload {
157:             root: 0,
158:             nodes: vec![],
159:             world_size: 10.0,
160:             collision: vec![],
161:         };
162:         store.insert(
163:             chunk_key(0.0, 0.0),
164:             LoadedChunk {
165:                 origin: (0.0, 0.0),
166:                 payload: payload.clone(),
167:             },
168:         );
169:         store.insert(
170:             chunk_key(10.0, 0.0),
171:             LoadedChunk {
172:                 origin: (10.0, 0.0),
173:                 payload,
174:             },
175:         );
176:         assert_eq!(store.len(), 2);
177:         assert!(store.retain_keys(&[chunk_key(0.0, 0.0)]));
178:         assert_eq!(store.len(), 1);
179:         assert!(!store.retain_keys(&[chunk_key(0.0, 0.0)]));
180:     }
181: }

