 1: /// Represents a dense 3D grid of voxels.
 2: /// This is the foundation for our "smaller voxels" requirement.
 3: pub struct VoxelGrid {
 4:     width: usize,
 5:     height: usize,
 6:     depth: usize,
 7:     data: Vec<u8>,
 8:     light_data: Vec<u8>,
 9:     face_occlusion: Vec<u8>,
10: }
11: 
12: pub const VOXEL_AIR: u8 = 0;
13: pub const VOXEL_WALL: u8 = 1;
14: pub const VOXEL_FLOOR: u8 = 2;
15: pub const VOXEL_CEILING: u8 = 3;
16: pub const VOXEL_LIGHT: u8 = 4;
17: pub const VOXEL_RED_WALL: u8 = 5;
18: /// Walkable ground cover (grassland level). Visual-only, like FLOOR.
19: pub const VOXEL_GRASS: u8 = 6;
20: /// Walkable shallow water (grassland lakes). Visual-only, like FLOOR.
21: pub const VOXEL_WATER: u8 = 7;
22: /// Tree trunk (grassland). Solid: blocks the player like WALL.
23: pub const VOXEL_TREE: u8 = 8;
24: pub const VOXEL_RED_LIGHT: u8 = 9;
25: 
26: impl VoxelGrid {
27:     pub fn new(width: usize, height: usize, depth: usize) -> Self {
28:         let size = width * height * depth;
29:         Self {
30:             width,
31:             height,
32:             depth,
33:             data: vec![VOXEL_AIR; size],
34:             light_data: vec![0; size],
35:             face_occlusion: vec![0; size],
36:         }
37:     }
38: 
39:     pub fn width(&self) -> usize {
40:         self.width
41:     }
42:     pub fn height(&self) -> usize {
43:         self.height
44:     }
45:     pub fn depth(&self) -> usize {
46:         self.depth
47:     }
48: 
49:     fn index(&self, x: usize, y: usize, z: usize) -> Option<usize> {
50:         if x < self.width && y < self.height && z < self.depth {
51:             Some(y * (self.width * self.depth) + z * self.width + x)
52:         } else {
53:             None
54:         }
55:     }
56: 
57:     pub fn set(&mut self, x: usize, y: usize, z: usize, voxel_type: u8) {
58:         if let Some(idx) = self.index(x, y, z) {
59:             self.data[idx] = voxel_type;
60:         }
61:     }
62: 
63:     pub fn get(&self, x: usize, y: usize, z: usize) -> u8 {
64:         if let Some(idx) = self.index(x, y, z) {
65:             self.data[idx]
66:         } else {
67:             VOXEL_AIR
68:         }
69:     }
70: 
71:     pub fn set_light(&mut self, x: usize, y: usize, z: usize, level: u8) {
72:         if let Some(idx) = self.index(x, y, z) {
73:             self.light_data[idx] = level;
74:         }
75:     }
76: 
77:     pub fn get_light(&self, x: usize, y: usize, z: usize) -> u8 {
78:         if let Some(idx) = self.index(x, y, z) {
79:             self.light_data[idx]
80:         } else {
81:             0
82:         }
83:     }
84: 
85:     pub fn set_face_occlusion(&mut self, x: usize, y: usize, z: usize, mask: u8) {
86:         if let Some(idx) = self.index(x, y, z) {
87:             self.face_occlusion[idx] = mask;
88:         }
89:     }
90: 
91:     pub fn get_face_occlusion(&self, x: usize, y: usize, z: usize) -> u8 {
92:         if let Some(idx) = self.index(x, y, z) {
93:             self.face_occlusion[idx]
94:         } else {
95:             0
96:         }
97:     }
98: }

files.src/domain/use_cases/build_octree.rs:
  1: use crate::domain::entities::sparse_voxel_octree::{SparseVoxelOctree, SvoNode};
  2: use crate::domain::entities::voxel_grid::{
  3:     VOXEL_AIR, VOXEL_CEILING, VOXEL_FLOOR, VOXEL_GRASS, VOXEL_LIGHT, VOXEL_RED_WALL, VOXEL_TREE,
  4:     VOXEL_WALL, VOXEL_WATER, VOXEL_RED_LIGHT, VoxelGrid,
  5: };
  6: 
  7: /// Use Case to convert a dense VoxelGrid into a collapsed Sparse Voxel Octree.
  8: pub struct BuildOctreeUseCase;
  9: 
 10: impl BuildOctreeUseCase {
 11:     pub fn new() -> Self {
 12:         Self
 13:     }
 14: 
 15:     /// Converts a dense VoxelGrid into an SVO of the specified depth.
 16:     pub fn execute(&self, grid: &VoxelGrid, depth: u32, world_size: f32) -> SparseVoxelOctree {
 17:         let mut nodes = Vec::new();
 18:         let size = 1 << depth;
 19: 
 20:         // Recursive build from root
 21:         let root_node = self.build_recursive(grid, &mut nodes, 0, 0, 0, size, depth);
 22: 
 23:         // Push the root node to the end of the nodes array
 24:         let root_idx = nodes.len();
 25:         nodes.push(root_node);
 26: 
 27:         SparseVoxelOctree {
 28:             root: root_idx,
 29:             nodes,
 30:             depth,
 31:             world_size,
 32:         }
 33:     }
 34: 
 35:     fn build_recursive(
 36:         &self,
 37:         grid: &VoxelGrid,
 38:         nodes: &mut Vec<SvoNode>,
 39:         x: u32,
 40:         y: u32,
 41:         z: u32,
 42:         size: u32,
 43:         depth: u32,
 44:     ) -> SvoNode {
 45:         if depth == 0 {
 46:             let (v_type, color, ll, fo) = self.get_voxel_attrs(grid, x, y, z);
 47:             return SvoNode::Leaf {
 48:                 voxel_type: v_type,
 49:                 color,
 50:                 light_level: ll,
 51:                 face_occlusion: fo,
 52:             };
 53:         }
 54: 
 55:         let child_size = size / 2;
 56:         let mut children = [SvoNode::Leaf {
 57:             voxel_type: 0,
 58:             color: 0,
 59:             light_level: 0,
 60:             face_occlusion: 0,
 61:         }; 8];
 62: 
 63:         for octant_idx in 0..8 {
 64:             let dx = (octant_idx & 1) * child_size;
 65:             let dy = ((octant_idx >> 1) & 1) * child_size;
 66:             let dz = ((octant_idx >> 2) & 1) * child_size;
 67: 
 68:             children[octant_idx as usize] =
 69:                 self.build_recursive(grid, nodes, x + dx, y + dy, z + dz, child_size, depth - 1);
 70:         }
 71: 
 72:         // Check if all 8 children are uniform leaves
 73:         let mut uniform = true;
 74:         let mut first_val = None;
 75:         for child in &children {
 76:             match child {
 77:                 SvoNode::Internal { .. } => {
 78:                     uniform = false;
 79:                     break;
 80:                 }
 81:                 SvoNode::Leaf {
 82:                     voxel_type,
 83:                     color,
 84:                     light_level,
 85:                     face_occlusion,
 86:                 } => {
 87:                     if let Some((vt, col, ll, fo)) = first_val {
 88:                         if vt != *voxel_type
 89:                             || col != *color
 90:                             || ll != *light_level
 91:                             || fo != *face_occlusion
 92:                         {
 93:                             uniform = false;
 94:                             break;
 95:                         }
 96:                     } else {
 97:                         first_val = Some((*voxel_type, *color, *light_level, *face_occlusion));
 98:                     }
 99:                 }
100:             }
101:         }
102: 
103:         if uniform {
104:             if let Some((vt, col, ll, fo)) = first_val {
105:                 return SvoNode::Leaf {
106:                     voxel_type: vt,
107:                     color: col,
108:                     light_level: ll,
109:                     face_occlusion: fo,
110:                 };
111:             }
112:         }
113: 
114:         // Push 8 children contiguously to arena
115:         let child_base_index = nodes.len() as u32;
116:         let mut child_mask = 0;
117: 
118:         for octant_idx in 0..8 {
119:             let child = children[octant_idx as usize];
120:             match child {
121:                 SvoNode::Leaf { voxel_type, .. } => {
122:                     if voxel_type != 0 {
123:                         child_mask |= 1 << octant_idx;
124:                     }
125:                 }
126:                 SvoNode::Internal { .. } => {
127:                     child_mask |= 1 << octant_idx;
128:                 }
129:             }
130:             nodes.push(child);
131:         }
132: 
133:         SvoNode::Internal {
134:             child_base_index,
135:             child_mask,
136:         }
137:     }
138: 
139:     fn get_voxel_attrs(&self, grid: &VoxelGrid, x: u32, y: u32, z: u32) -> (u8, u32, u8, u8) {
140:         if x >= grid.width() as u32 || y >= grid.height() as u32 || z >= grid.depth() as u32 {
141:             return (0, 0, 0, 0); // Out of bounds is air
142:         }
143: 
144:         let v_id = grid.get(x as usize, y as usize, z as usize);
145:         if v_id == VOXEL_AIR {
146:             return (0, 0, 0, 0);
147:         }
148: 
149:         let ll = grid.get_light(x as usize, y as usize, z as usize);
150:         let fo = grid.get_face_occlusion(x as usize, y as usize, z as usize);
151:         let base_color = match v_id {
152:             VOXEL_WALL => 0xddcc66,
153:             VOXEL_FLOOR => 0x998811,
154:             VOXEL_CEILING => 0xcccccc,
155:             VOXEL_LIGHT => 0xffffff,
156:             VOXEL_RED_LIGHT => 0xff4444,
157:             VOXEL_RED_WALL => 0x880000,
158:             VOXEL_GRASS => 0x4f9a3d,
159:             VOXEL_WATER => 0x3a6fb8,
160:             VOXEL_TREE => 0x6b4a2f,
161:             _ => 0x000000,
162:         };
163: 
164:         (v_id, base_color, ll, fo)
165:     }
166: }
167: 
168: #[cfg(test)]
169: mod tests {
170:     use super::*;
171: 
172:     #[test]
173:     fn test_empty_grid_collapses_to_single_root_leaf() {
174:         let grid = VoxelGrid::new(4, 4, 4);
175:         let builder = BuildOctreeUseCase::new();
176:         let svo = builder.execute(&grid, 2, 4.0);
177: 
178:         // An entirely empty grid should collapse into a single root node (Leaf containing air)
179:         assert_eq!(svo.nodes.len(), 1);
180:         match svo.nodes[svo.root] {
181:             SvoNode::Leaf { voxel_type, .. } => assert_eq!(voxel_type, 0),
182:             _ => panic!("Expected root to be a collapsed leaf node"),
183:         }
184:     }
185: 
186:     #[test]
187:     fn test_single_voxel_splits_octree() {
188:         let mut grid = VoxelGrid::new(4, 4, 4);
189:         grid.set(0, 0, 0, VOXEL_WALL); // Set wall at origin
190: 
191:         let builder = BuildOctreeUseCase::new();
192:         let svo = builder.execute(&grid, 2, 4.0); // depth 2
193: 
194:         // Since there is a single wall voxel, the tree must split and cannot be collapsed completely
195:         assert!(svo.nodes.len() > 1);
196: 
197:         // The root should be an internal node
198:         match svo.nodes[svo.root] {
199:             SvoNode::Internal { child_mask, .. } => {
200:                 assert!(child_mask > 0);
201:             }
202:             _ => panic!("Expected root to be an internal parent node"),
203:         }
204: 
205:         // Let's verify we can query the wall voxel at (0,0,0)
206:         let val = svo.get(0, 0, 0);
207:         assert!(val.is_some());
208:         let (v_type, color, _, _) = val.unwrap();
209:         assert_eq!(v_type, VOXEL_WALL);
210:         assert_eq!(color, 0xddcc66);
211:     }
212: }

files.src/domain/use_cases/generate_maze.rs:
  1: use crate::domain::entities::grid::Grid;
  2: use rand::Rng;
  3: #[allow(unused_imports)]
  4: use rand::RngExt;
  5: 
  6: /// Design Pattern: Strategy
  7: /// We use the Strategy pattern here to encapsulate the maze generation algorithm.
  8: /// This is the superior choice because different Backrooms levels (or even different regions of Level 0)
  9: /// might require different procedural generation rules. By decoupling the generation logic from the Grid entity,
 10: /// we ensure the Open/Closed Principle (workable iʃɛ́) — we can add new generators without modifying the Grid.
 11: pub trait MazeGenerator {
 12:     /// Generates the maze on the provided grid using the given random number generator.
 13:     fn generate<R: Rng + ?Sized>(&self, grid: &mut Grid, rng: &mut R);
 14: }
 15: 
 16: /// A concrete strategy for generating a maze using the Growing Tree algorithm.
 17: /// This algorithm produces non-linear, organic layouts suitable for the Backrooms,
 18: /// unlike standard depth-first search which produces long winding paths.
 19: pub struct GrowingTreeGenerator {
 20:     pub junction_density: f32,
 21: }
 22: 
 23: impl MazeGenerator for GrowingTreeGenerator {
 24:     fn generate<R: Rng + ?Sized>(&self, grid: &mut Grid, rng: &mut R) {
 25:         let width = grid.width();
 26:         let depth = grid.depth();
 27:         if width == 0 || depth == 0 {
 28:             return;
 29:         }
 30: 
 31:         // Starting point
 32:         let start_x = rng.random_range(0..width);
 33:         let start_y = rng.random_range(0..depth);
 34: 
 35:         if let Some(cell) = grid.get_mut(start_x, start_y) {
 36:             cell.visited = true;
 37:         }
 38: 
 39:         let mut frontier = vec![(start_x, start_y)];
 40: 
 41:         while !frontier.is_empty() {
 42:             // Pick a random cell from the frontier (this randomness defines the Growing Tree behavior)
 43:             let idx = rng.random_range(0..frontier.len());
 44:             let (cx, cy) = frontier[idx];
 45: 
 46:             // Define neighbors: (x, y, wall_here_idx, wall_there_idx)
 47:             // 0: North, 1: East, 2: South, 3: West
 48:             let neighbors: [(isize, isize, usize, usize); 4] = [
 49:                 (cx as isize, (cy as isize) - 1, 0, 2), // North
 50:                 ((cx as isize) + 1, cy as isize, 1, 3), // East
 51:                 (cx as isize, (cy as isize) + 1, 2, 0), // South
 52:                 ((cx as isize) - 1, cy as isize, 3, 1), // West
 53:             ];
 54: 
 55:             let mut unvisited = Vec::new();
 56:             for &(nx, ny, wall_here, wall_there) in &neighbors {
 57:                 if nx >= 0 && nx < width as isize && ny >= 0 && ny < depth as isize {
 58:                     let (nx_u, ny_u) = (nx as usize, ny as usize);
 59:                     if let Some(cell) = grid.get(nx_u, ny_u) {
 60:                         if !cell.visited {
 61:                             unvisited.push((nx_u, ny_u, wall_here, wall_there));
 62:                         }
 63:                     }
 64:                 }
 65:             }
 66: 
 67:             if unvisited.is_empty() {
 68:                 frontier.swap_remove(idx);
 69:             } else {
 70:                 let unvisited_idx = rng.random_range(0..unvisited.len());
 71:                 let (nx, ny, wall_here, wall_there) = unvisited[unvisited_idx];
 72: 
 73:                 // Knock down walls
 74:                 if let Some(cell) = grid.get_mut(cx, cy) {
 75:                     cell.walls[wall_here] = false;
 76:                 }
 77:                 if let Some(cell) = grid.get_mut(nx, ny) {
 78:                     cell.walls[wall_there] = false;
 79:                     cell.visited = true;
 80:                 }
 81: 
 82:                 frontier.push((nx, ny));
 83:             }
 84:         }
 85: 
 86:         // Add loops to break the "perfect maze" property and make it feel like the Backrooms
 87:         let base_openings = (width * depth) as f32 / 4.0;
 88:         let extra_openings = (base_openings * self.junction_density) as usize;
 89:         let mut actual_openings = 0;
 90:         let mut attempts = 0;
 91: 
 92:         while actual_openings < extra_openings && attempts < extra_openings * 3 {
 93:             attempts += 1;
 94:             let x = rng.random_range(0..width);
 95:             let y = rng.random_range(0..depth);
 96: 
 97:             // Blackout zones are knot-like dead-ends; suppress extra loops in them
 98:             if let Some(cell) = grid.get(x, y) {
 99:                 if cell.zone == crate::domain::entities::cell::MicrobiomeZone::Blackout {
100:                     continue;
101:                 }
102:             }
103: 
104:             let dir = rng.random_range(0..4);
105: 
106:             if let Some(cell) = grid.get_mut(x, y) {
107:                 cell.walls[dir] = false;
108:             }
109: 
110:             let (nx, ny) = match dir {
111:                 0 => (x as isize, y as isize - 1),
112:                 1 => (x as isize + 1, y as isize),
113:                 2 => (x as isize, y as isize + 1),
114:                 3 => (x as isize - 1, y as isize),
115:                 _ => unreachable!(),
116:             };
117: 
118:             if nx >= 0 && nx < width as isize && ny >= 0 && ny < depth as isize {
119:                 let (nx, ny) = (nx as usize, ny as usize);
120:                 let opposite_dir = (dir + 2) % 4;
121:                 if let Some(n_cell) = grid.get_mut(nx, ny) {
122:                     n_cell.walls[opposite_dir] = false;
123:                 }
124:             }
125: 
126:             actual_openings += 1;
127:         }
128:     }
129: }
130: 
131: #[cfg(test)]
132: mod tests {
133:     use super::*;
134:     use crate::domain::entities::grid::Grid;
135:     use rand::SeedableRng;
136:     use rand::rngs::StdRng;
137: 
138:     #[test]
139:     fn test_generate_maze_visits_all_cells() {
140:         let mut grid = Grid::new(10, 10);
141:         let mut rng = StdRng::seed_from_u64(42);
142: 
143:         let generator = GrowingTreeGenerator {
144:             junction_density: 1.0,
145:         };
146:         generator.generate(&mut grid, &mut rng);
147: 
148:         for y in 0..grid.depth() {
149:             for x in 0..grid.width() {
150:                 let cell = grid.get(x, y).unwrap();
151:                 assert!(cell.visited, "Cell at ({}, {}) was not visited", x, y);
152:             }
153:         }
154:     }
155: }

