  1: //! CPU microvoxel splatting renderer — a software implementation of
  2: //! [`RendererPort`] for machines with no usable GPU (or `?renderer=cpu`).
  3: //!
  4: //! Instead of marching a ray per pixel (Family 2/3), the CPU path inverts
  5: //! the loop: it walks the SVO front-to-back and *splats* nodes onto a
  6: //! z-buffered framebuffer, sized by their projected footprint:
  7: //!
  8: //! * **Coarse-to-fine LOD** — an interior node whose bounding sphere projects
  9: //!   to under ~a pixel is drawn as a single splat using MIP-filtered
 10: //!   attributes (average child color, max light, occupancy), computed once
 11: //!   per atlas upload by [`build_mips`]. Distant geometry costs O(pixels),
 12: //!   not O(voxels).
 13: //! * **Virtual subdivision** — a *large* solid leaf (the SVO collapses
 14: //!   uniform regions) is recursively split into eight virtual sub-boxes
 15: //!   until each splat is a few pixels wide, so nearby walls stay crisp.
 16: //! * **Front-to-back traversal** — children are visited nearest-octant-first
 17: //!   so the z-buffer rejects most occluded splats before shading.
 18: //!
 19: //! Lighting is *richer* than the GPU path precisely because it runs per
 20: //! splat, not per pixel:
 21: //! * BFS-propagated light level (same data as the GPU path),
 22: //! * per-face directional shading (tops bright, bottoms dark),
 23: //! * contact AO from how crowded the parent octant is,
 24: //! * a player-held torch with quadratic falloff,
 25: //! * exponential distance fog.
 26: //!
 27: //! This module is platform-free (no web-sys): the browser driver only blits
 28: //! the RGBA buffer. All geometry/shading logic is natively unit-tested.
 29: 
 30: use crate::application::ports::{ChunkDraw, FrameParams, RendererPort};
 31: 
 32: /// Half field of view tangent; identical to the GPU shader's `0.767`
 33: /// (tan of 75 deg FOV / 2).
 34: const HALF_FOV_TAN: f32 = 0.767;
 35: /// Interior nodes projecting smaller than this many pixels (radius) are
 36: /// drawn as one MIP splat instead of being descended into.
 37: const LOD_CUTOFF_PX: f32 = 1.0;
 38: /// Solid leaves are virtually subdivided until their projected half-extent
 39: /// is at most this many pixels.
 40: const MAX_SPLAT_HALF_PX: f32 = 3.0;
 41: /// Don't subdivide below this world size (guards runaway recursion).
 42: const MIN_SPLIT_SIZE: f32 = 0.02;
 43: /// Ignore MIP splats of nodes that are mostly air.
 44: const MIN_SPLAT_OCCUPANCY: f32 = 0.25;
 45: /// Same fog density as the GPU shader.
 46: const FOG_DENSITY: f32 = 0.015;
 47: 
 48: const VOXEL_AIR: u32 = 0;
 49: const VOXEL_LIGHT: u32 = 4;
 50: 
 51: /// Per-node MIP-filtered attributes, rebuilt on every atlas upload.
 52: #[derive(Debug, Clone, Copy, Default)]
 53: struct MipNode {
 54:     /// Occupancy-weighted average RGB of the subtree, 0..255 per channel.
 55:     color: [f32; 3],
 56:     /// Max BFS light level in the subtree (0..15).
 57:     light: f32,
 58:     /// Fraction of the subtree volume that is solid, 0..1.
 59:     occupancy: f32,
 60: }
 61: 
 62: /// Camera basis matching the GPU shader's yaw/pitch rotation exactly.
 63: struct Camera {
 64:     pos: [f32; 3],
 65:     right: [f32; 3],
 66:     up: [f32; 3],
 67:     forward: [f32; 3],
 68:     /// Focal length in pixels: h / (2 * tan(fov/2)).
 69:     focal_px: f32,
 70:     half_w: f32,
 71:     half_h: f32,
 72: }
 73: 
 74: impl Camera {
 75:     fn new(frame: &FrameParams, width: usize, height: usize) -> Self {
 76:         let (sy, cy) = frame.yaw.sin_cos();
 77:         let (sp, cp) = frame.pitch.sin_cos();
 78:         Self {
 79:             pos: frame.camera_pos,
 80:             right: [cy, 0.0, -sy],
 81:             up: [sp * sy, cp, sp * cy],
 82:             forward: [-cp * sy, sp, -cp * cy],
 83:             focal_px: height as f32 / (2.0 * HALF_FOV_TAN),
 84:             half_w: width as f32 / 2.0,
 85:             half_h: height as f32 / 2.0,
 86:         }
 87:     }
 88: }
 89: 
 90: fn dot(a: [f32; 3], b: [f32; 3]) -> f32 {
 91:     a[0] * b[0] + a[1] * b[1] + a[2] * b[2]
 92: }
 93: 
 94: pub struct SoftwareRasterizer {
 95:     width: usize,
 96:     height: usize,
 97:     /// RGBA8 framebuffer, ready for ImageData blit.
 98:     rgba: Vec<u8>,
 99:     depth: Vec<f32>,
100:     /// SVO atlas texels: 4 u32 per node (see OctreeGpuSerializer).
101:     atlas: Vec<u32>,
102:     mips: Vec<MipNode>,
103: }
104: 
105: impl SoftwareRasterizer {
106:     pub fn new(width: usize, height: usize) -> Self {
107:         let mut r = Self {
108:             width: 0,
109:             height: 0,
110:             rgba: Vec::new(),
111:             depth: Vec::new(),
112:             atlas: Vec::new(),
113:             mips: Vec::new(),
114:         };
115:         r.resize(width, height);
116:         r
117:     }
118: 
119:     pub fn resize(&mut self, width: usize, height: usize) {
120:         self.width = width.max(1);
121:         self.height = height.max(1);
122:         self.rgba = vec![0; self.width * self.height * 4];
123:         self.depth = vec![f32::INFINITY; self.width * self.height];
124:     }
125: 
126:     pub fn width(&self) -> usize {
127:         self.width
128:     }
129: 
130:     pub fn height(&self) -> usize {
131:         self.height
132:     }
133: 
134:     /// The finished frame as RGBA8 rows, top-down.
135:     pub fn framebuffer(&self) -> &[u8] {
136:         &self.rgba
137:     }
138: 
139:     fn clear(&mut self) {
140:         for px in self.rgba.chunks_exact_mut(4) {
141:             px[0] = 0;
142:             px[1] = 0;
143:             px[2] = 0;
144:             px[3] = 255;
145:         }
146:         self.depth.fill(f32::INFINITY);
147:     }
148: 
149:     /// Fills a depth-tested square splat. `half` is the half-extent in px.
150:     #[allow(clippy::too_many_arguments)]
151:     fn splat(&mut self, cx: f32, cy: f32, half: f32, z: f32, r: u8, g: u8, b: u8) {
152:         let x0 = (cx - half).floor().max(0.0) as usize;
153:         let x1 = ((cx + half).ceil() as usize).min(self.width);
154:         let y0 = (cy - half).floor().max(0.0) as usize;
155:         let y1 = ((cy + half).ceil() as usize).min(self.height);
156: 
157:         for y in y0..y1 {
158:             let row = y * self.width;
159:             for x in x0..x1 {
160:                 let idx = row + x;
161:                 if z < self.depth[idx] {
162:                     self.depth[idx] = z;
163:                     let p = idx * 4;
164:                     self.rgba[p] = r;
165:                     self.rgba[p + 1] = g;
166:                     self.rgba[p + 2] = b;
167:                 }
168:             }
169:         }
170:     }
171: 
172:     /// Shades and splats one solid box (leaf, virtual sub-leaf, or MIP node).
173:     ///
174:     /// Literate Documentation:
175:     /// This function applies directional shading, contact ambient occlusion,
176:     /// player torchlight falloff, and distance fog.
177:     /// To resolve the visual checkerboard popping artifacts and moving bands
178:     /// on floor/ceiling surfaces, we use a continuous face shading interpolation.
179:     /// Instead of checking which coordinate axis is strictly dominant and applying
180:     /// a hard step in face brightness (e.g. 0.55 vs 0.7 vs 0.8), we compute a
181:     /// weighted combination of the cardinal face values based on the normalized
182:     /// viewing vector squared. This ensures the shading coefficient varies
183:     /// smoothly with camera position, eliminating sharp seams and popping.
184:     #[allow(clippy::too_many_arguments)]
185:     fn shade_and_splat(
186:         &mut self,
187:         cam: &Camera,
188:         center: [f32; 3],
189:         px: f32,
190:         py: f32,
191:         half_px: f32,
192:         dist: f32,
193:         base_color: [f32; 3],
194:         light_level: f32,
195:         is_emissive: bool,
196:         crowded_siblings: u32,
197:     ) {
198:         // Per-face directional shading from the face we actually see:
199:         // We project the view vector onto the three axes. Instead of taking
200:         // the max (discontinuous step), we blend the face shading factors
201:         // continuously using the normalized squared vector components as weights.
202:         let to_cam = [
203:             center[0] - cam.pos[0],
204:             center[1] - cam.pos[1],
205:             center[2] - cam.pos[2],
206:         ];
207: 
208:         let dx_sq = to_cam[0] * to_cam[0];
209:         let dy_sq = to_cam[1] * to_cam[1];
210:         let dz_sq = to_cam[2] * to_cam[2];
211:         let sum = dx_sq + dy_sq + dz_sq;
212: 
213:         let face = if sum > 1e-6 {
214:             // Y-face: bottom face (0.55) if looking up, top face (1.0) if looking down.
215:             let y_val = if to_cam[1] > 0.0 { 0.55 } else { 1.0 };
216:             let x_val = 0.8;
217:             let dz_val = 0.7;
218:             (dx_sq * x_val + dy_sq * y_val + dz_sq * dz_val) / sum
219:         } else {
220:             1.0
221:         };
222: 
223:         // Contact AO: leaves packed tightly among solid siblings darken,
224:         // approximating corner occlusion for free from the child mask.
225:         let ao = 1.0 - 0.04 * crowded_siblings.saturating_sub(1) as f32;
226: 
227:         // BFS light + player torch (quadratic falloff) + fog.
228:         let bfs = 0.25 + 0.75 * (light_level / 15.0);
229:         let torch = (1.2 / (1.0 + 0.35 * dist + 0.10 * dist * dist)).min(1.0);
230:         let lum = if is_emissive {
231:             1.0
232:         } else {
233:             (bfs.max(torch * 0.9) * face * ao).min(1.0)
234:         };
235:         let fog = (-FOG_DENSITY * dist).exp();
236: 
237:         let scale = lum * fog * if is_emissive { 1.0 } else { 1.0 };
238:         let r = (base_color[0] * scale).min(255.0) as u8;
239:         let g = (base_color[1] * scale).min(255.0) as u8;
240:         let b = (base_color[2] * scale).min(255.0) as u8;
241: 
242:         self.splat(px, py, half_px, dist, r, g, b);
243:     }
244: 
245:     /// Recursive front-to-back node renderer.
246:     ///
247:     /// `node_idx == usize::MAX` marks a *virtual* node: a subdivision of a
248:     /// large collapsed leaf, which reuses `leaf_attrs` instead of the atlas.
249:     #[allow(clippy::too_many_arguments)]
250:     fn render_node(
251:         &mut self,
252:         cam: &Camera,
253:         node_idx: usize,
254:         min: [f32; 3],
255:         size: f32,
256:         crowded_siblings: u32,
257:         leaf_attrs: Option<(u32, [f32; 3], f32)>, // (voxel_type, color, light)
258:     ) {
259:         let half_size = size * 0.5;
260:         let center = [min[0] + half_size, min[1] + half_size, min[2] + half_size];
261:         let radius = size * 0.866; // bounding sphere
262: 
263:         let rel = [
264:             center[0] - cam.pos[0],
265:             center[1] - cam.pos[1],
266:             center[2] - cam.pos[2],
267:         ];
268:         let z = dot(rel, cam.forward);
269:         // Entirely behind the camera.
270:         if z + radius <= 0.01 {
271:             return;
272:         }
273: 
274:         let inside = z - radius <= 0.0; // camera inside the bounding sphere
275:         let (px, py, proj_half, proj_radius) = if inside {
276:             (0.0, 0.0, f32::INFINITY, f32::INFINITY)
277:         } else {
278:             let inv_z = 1.0 / z;
279:             let px = cam.half_w + dot(rel, cam.right) * inv_z * cam.focal_px;
280:             let py = cam.half_h - dot(rel, cam.up) * inv_z * cam.focal_px;
281:             let proj_radius = radius * cam.focal_px / (z - radius).max(0.001);
282:             // Conservative screen-bounds cull.
283:             if px + proj_radius < 0.0
284:                 || px - proj_radius >= self.width as f32
285:                 || py + proj_radius < 0.0
286:                 || py - proj_radius >= self.height as f32
287:             {
288:                 return;
289:             }
290:             (px, py, half_size * cam.focal_px * inv_z, proj_radius)
291:         };
292: 
293:         // Resolve node attributes (real atlas node or virtual sub-leaf).
294:         let (is_leaf, payload) = if let Some(attrs) = leaf_attrs {
295:             (true, attrs)
296:         } else {
297:             let t = node_idx * 4;
298:             if t + 3 >= self.atlas.len() {
299:                 return;
300:             }
301:             if self.atlas[t] == 1 {
302:                 let vt = self.atlas[t + 1];
303:                 let c = self.atlas[t + 2];
304:                 let color = [
305:                     ((c >> 16) & 0xFF) as f32,
306:                     ((c >> 8) & 0xFF) as f32,
307:                     (c & 0xFF) as f32,
308:                 ];
309:                 (true, (vt, color, self.atlas[t + 3] as f32))
310:             } else {
311:                 (false, (0, [0.0; 3], 0.0))
312:             }
313:         };
314: 
315:         if is_leaf {
316:             let (voxel_type, color, light) = payload;
317:             if voxel_type == VOXEL_AIR {
318:                 return;
319:             }
320:             // Large collapsed leaf: virtually subdivide until splats are small.
321:             if proj_half > MAX_SPLAT_HALF_PX && size > MIN_SPLIT_SIZE {
322:                 self.recurse_children_front_to_back(
323:                     cam,
324:                     usize::MAX,
325:                     min,
326:                     half_size,
327:                     0xFF,
328:                     crowded_siblings,
329:                     Some((voxel_type, color, light)),
330:                 );
331:             } else {
332:                 // Inflate the splat size slightly (scale by 1.15, clamp to min 0.85 pixels)
333:                 // to create a tiny overlap between adjacent splats under perspective projection.
334:                 // This closes sub-pixel/pixel gaps (black lines) that occur where squares fail
335:                 // to tile perfectly due to depth differences and pixel-grid rounding.
336:                 self.shade_and_splat(
337:                     cam,
338:                     center,
339:                     px,
340:                     py,
341:                     (proj_half * 1.15).max(0.85),
342:                     z,
343:                     color,
344:                     light,
345:                     voxel_type == VOXEL_LIGHT,
346:                     crowded_siblings,
347:                 );
348:             }
349:             return;
350:         }
351: 
352:         // Interior node.
353:         let t = node_idx * 4;
354:         let child_base = self.atlas[t + 1] as usize;
355:         let child_mask = self.atlas[t + 2];
356: 
357:         // LOD cutoff: subtree fits in ~a pixel -> one MIP splat.
358:         if proj_radius < LOD_CUTOFF_PX {
359:             let mip = self.mips.get(node_idx).copied().unwrap_or_default();
360:             if mip.occupancy >= MIN_SPLAT_OCCUPANCY {
361:                 self.shade_and_splat(
362:                     cam,
363:                     center,
364:                     px,
365:                     py,
366:                     1.0,
367:                     z,
368:                     mip.color,
369:                     mip.light,
370:                     false,
371:                     crowded_siblings,
372:                 );
373:             }
374:             return;
375:         }
376: 
377:         self.recurse_children_front_to_back(
378:             cam,
379:             child_base,
380:             min,
381:             half_size,
382:             child_mask,
383:             child_mask.count_ones(),
384:             None,
385:         );
386:     }
387: 
388:     /// Visits the eight octants nearest-first (camera octant XOR popcount
389:     /// order) so the z-buffer culls occluded splats early.
390:     #[allow(clippy::too_many_arguments)]
391:     fn recurse_children_front_to_back(
392:         &mut self,
393:         cam: &Camera,
394:         child_base: usize, // usize::MAX -> virtual subdivision
395:         min: [f32; 3],
396:         half_size: f32,
397:         child_mask: u32,
398:         crowding: u32,
399:         leaf_attrs: Option<(u32, [f32; 3], f32)>,
400:     ) {
401:         let cx = min[0] + half_size;
402:         let cy = min[1] + half_size;
403:         let cz = min[2] + half_size;
404:         let near_octant = (cam.pos[0] >= cx) as u32
405:             | (((cam.pos[1] >= cy) as u32) << 1)
406:             | (((cam.pos[2] >= cz) as u32) << 2);
407: 
408:         // XOR distances grouped by popcount: near octant first, far last.
409:         const ORDER: [u32; 8] = [0, 1, 2, 4, 3, 5, 6, 7];
410:         for &flip in &ORDER {
411:             let child = near_octant ^ flip;
412:             if child_mask & (1 << child) == 0 {
413:                 continue;
414:             }
415:             let child_min = [
416:                 min[0] + (child & 1) as f32 * half_size,
417:                 min[1] + ((child >> 1) & 1) as f32 * half_size,
418:                 min[2] + ((child >> 2) & 1) as f32 * half_size,
419:             ];
420:             let child_idx = if child_base == usize::MAX {
421:                 usize::MAX
422:             } else {
423:                 child_base + child as usize
424:             };
425:             self.render_node(cam, child_idx, child_min, half_size, crowding, leaf_attrs);
426:         }
427:     }
428: }
429: 
430: /// Bottom-up MIP filtering over the whole atlas. Node order in the arena is
431: /// not guaranteed (`SparseVoxelOctree::set` appends children after parents,
432: /// `BuildOctreeUseCase` pushes the root last), so each subtree is resolved by
433: /// memoized recursion instead of a single directional sweep. Still O(n): every
434: /// node is computed exactly once.
435: fn build_mips(atlas: &[u32]) -> Vec<MipNode> {
436:     let node_count = atlas.len() / 4;
437:     let mut mips = vec![MipNode::default(); node_count];
438:     let mut done = vec![false; node_count];
439:     for i in 0..node_count {
440:         compute_mip(atlas, i, &mut mips, &mut done);
441:     }
442:     mips
443: }
444: 
445: fn compute_mip(atlas: &[u32], i: usize, mips: &mut [MipNode], done: &mut [bool]) {
446:     if done[i] {
447:         return;
448:     }
449:     // Marked before descending: a malformed cycle degrades to a zero mip
450:     // instead of infinite recursion.
451:     done[i] = true;
452: 
453:     let t = i * 4;
454:     if atlas[t] == 1 {
455:         // Leaf.
456:         let voxel_type = atlas[t + 1];
457:         if voxel_type != VOXEL_AIR {
458:             let c = atlas[t + 2];
459:             mips[i] = MipNode {
460:                 color: [
461:                     ((c >> 16) & 0xFF) as f32,
462:                     ((c >> 8) & 0xFF) as f32,
463:                     (c & 0xFF) as f32,
464:                 ],
465:                 light: atlas[t + 3] as f32,
466:                 occupancy: 1.0,
467:             };
468:         }
469:     } else {
470:         let child_base = atlas[t + 1] as usize;
471:         let child_mask = atlas[t + 2];
472:         let mut acc = MipNode::default();
473:         for child in 0..8usize {
474:             if child_mask & (1 << child) == 0 {
475:                 continue;
476:             }
477:             let idx = child_base + child;
478:             if idx >= mips.len() {
479:                 continue;
480:             }
481:             compute_mip(atlas, idx, mips, done);
482:             let m = mips[idx];
483:             let w = m.occupancy / 8.0;
484:             acc.color[0] += m.color[0] * w;
485:             acc.color[1] += m.color[1] * w;
486:             acc.color[2] += m.color[2] * w;
487:             acc.light = acc.light.max(m.light);
488:             acc.occupancy += w;
489:         }
490:         if acc.occupancy > 0.0 {
491:             let inv = 1.0 / acc.occupancy;
492:             acc.color[0] *= inv;
493:             acc.color[1] *= inv;
494:             acc.color[2] *= inv;
495:         }
496:         mips[i] = acc;
497:     }
498: }
499: 
500: impl RendererPort for SoftwareRasterizer {
501:     fn upload_atlas(&mut self, texels: &[u32]) {
502:         self.atlas = texels.to_vec();
503:         self.mips = build_mips(&self.atlas);
504:     }
505: 
506:     fn draw(&mut self, frame: &FrameParams, chunks: &[ChunkDraw]) {
507:         self.clear();
508:         if self.atlas.is_empty() {
509:             return;
510:         }
511:         let cam = Camera::new(frame, self.width, self.height);
512: 
513:         // Nearest chunk first: maximizes early z-rejection across chunks.
514:         let mut order: Vec<&ChunkDraw> = chunks.iter().collect();
515:         order.sort_by(|a, b| {
516:             let da = chunk_distance_sq(a, frame.camera_pos);
517:             let db = chunk_distance_sq(b, frame.camera_pos);
518:             da.total_cmp(&db)
519:         });
520: 
521:         for chunk in order {
522:             self.render_node(
523:                 &cam,
524:                 chunk.root_index as usize,
525:                 chunk.origin,
526:                 chunk.world_size,
527:                 1,
528:                 None,
529:             );
530:         }
531:     }
532: }
533: 
534: fn chunk_distance_sq(chunk: &ChunkDraw, pos: [f32; 3]) -> f32 {
535:     let half = chunk.world_size * 0.5;
536:     let dx = chunk.origin[0] + half - pos[0];
537:     let dz = chunk.origin[2] + half - pos[2];
538:     dx * dx + dz * dz
539: }
