799: 
800:         // Voxel 2 center: [2.5, 0.0, 0.5]
801:         // dist = sqrt(1.5^2 + 5.0^2 + 0.5^2) = sqrt(27.5) = 5.2440
802:         r.clear();
803:         r.shade_and_splat(
804:             &cam,
805:             [2.5, 0.0, 0.5],
806:             8.0,
807:             8.0,
808:             1.0,
809:             5.2440,
810:             [100.0, 100.0, 100.0],
811:             15.0,
812:             false,
813:             1,
814:         );
815:         let color_2 = center_pixel(&r);
816: 
817:         // Verify that the two adjacent voxels differ in color/shading.
818:         // This diagnostic test proves that rendering flat surfaces voxel-by-voxel
819:         // without quad-merging causes individual tiles to have slightly different
820:         // shading, creating a visible grid pattern.
821:         assert_ne!(
822:             color_1[0], color_2[0],
823:             "Expected adjacent voxels to have slightly different shading due to center-based lighting calculations"
824:         );
825:     }
826: 
827:     #[test]
828:     fn test_splat_flat_shading_limitation() {
829:         let mut r = SoftwareRasterizer::new(16, 16);
830:         let frame = FrameParams {
831:             camera_pos: [1.0, 5.0, 1.0],
832:             yaw: 0.0,
833:             pitch: 0.0,
834:         };
835:         let cam = Camera::new(&frame, 16, 16);
836: 
837:         // Draw a single large splat (half_px = 4.0) centered at [8.0, 8.0]
838:         r.clear();
839:         r.shade_and_splat(
840:             &cam,
841:             [0.5, 0.0, 0.5],
842:             8.0,
843:             8.0,
844:             4.0, // large size
845:             5.0,
846:             [100.0, 100.0, 100.0],
847:             15.0,
848:             false,
849:             1,
850:         );
851: 
852:         // Read pixels at different parts of the splat (left inside vs right inside)
853:         let idx_left = (8 * r.width() + 5) * 4;
854:         let idx_right = (8 * r.width() + 10) * 4;
855:         let fb = r.framebuffer();
856:         let color_left = [fb[idx_left], fb[idx_left + 1], fb[idx_left + 2]];
857:         let color_right = [fb[idx_right], fb[idx_right + 1], fb[idx_right + 2]];
858: 
859:         // Confirm they are identical, which proves that the entire projected area
860:         // of a single splat is displayed with one flat color, causing lighting to look
861:         // like big blocks/squares on screen.
862:         assert_eq!(
863:             color_left, color_right,
864:             "Expected a single splat to be flat-shaded (all its pixels have identical color)"
865:         );
866:     }
867: }

files.wasm_frontend/src/adapters/local_chunk_s:
  1: //! In-wasm chunk source: implements the application's [`ChunkSourcePort`] by
  2: //! driving the core engine use cases directly. There is no server round-trip;
  3: //! the entire pipeline — procedural generation, BFS lighting, SVO build, GPU
  4: //! serialization, collision extraction — runs inside the wasm module.
  5: //!
  6: //! Pipeline per chunk:
  7: //!   GenerateChunkArchitectureUseCase  (VoxelGrid, lighting included)
  8: //!     -> BuildOctreeUseCase           (SparseVoxelOctree)
  9: //!     -> OctreeGpuSerializer          (row-padded RGBA32UI texel stream)
 10: //!     -> collision walk               (solid leaves -> world-space AABBs)
 11: 
 12: use vackrooms::adapters::octree_gpu_serializer::OctreeGpuSerializer;
 13: use vackrooms::domain::entities::sparse_voxel_octree::{SparseVoxelOctree, SvoNode};
 14: use vackrooms::domain::use_cases::build_octree::BuildOctreeUseCase;
 15: use vackrooms::entities::models::Position;
 16: use vackrooms::use_cases::generate_chunk::{GenerateChunkArchitectureUseCase, GeneratorConfig};
 17: use vackrooms::use_cases::ports::{NULL_TELEMETRY, NoiseProvider, TelemetryPort};
 18: 
 19: use crate::application::collision::Aabb;
 20: use crate::application::ports::{ChunkPayload, ChunkSourcePort};
 21: 
 22: /// Voxel types that block the player. FLOOR/CEILING/LIGHT/GRASS/WATER are
 23: /// visual-only: including them would make the player collide with the floor
 24: /// they stand on.
 25: const SOLID_TYPES: [u8; 3] = [
 26:     vackrooms::domain::entities::voxel_grid::VOXEL_WALL,
 27:     vackrooms::domain::entities::voxel_grid::VOXEL_RED_WALL,
 28:     vackrooms::domain::entities::voxel_grid::VOXEL_TREE,
 29: ];
 30: 
 31: pub struct LocalChunkSource<N: NoiseProvider> {
 32:     noise: N,
 33:     telemetry: &'static dyn TelemetryPort,
 34:     seed: u32,
 35:     config: GeneratorConfig,
 36: }
 37: 
 38: impl<N: NoiseProvider> LocalChunkSource<N> {
 39:     pub fn new(noise: N, seed: u32, config: GeneratorConfig) -> Self {
 40:         Self {
 41:             noise,
 42:             telemetry: &NULL_TELEMETRY,
 43:             seed,
 44:             config,
 45:         }
 46:     }
 47: 
 48:     pub fn with_telemetry(
 49:         noise: N,
 50:         seed: u32,
 51:         config: GeneratorConfig,
 52:         telemetry: &'static dyn TelemetryPort,
 53:     ) -> Self {
 54:         Self {
 55:             noise,
 56:             telemetry,
 57:             seed,
 58:             config,
 59:         }
 60:     }
 61: }
 62: 
 63: impl<N: NoiseProvider> ChunkSourcePort for LocalChunkSource<N> {
 64:     fn load(&self, origin_x: f32, origin_z: f32, level: u32) -> ChunkPayload {
 65:         let generator =
 66:             GenerateChunkArchitectureUseCase::with_telemetry(&self.noise, self.telemetry);
 67:         let grid = generator.execute(
 68:             Position::new(origin_x, origin_z),
 69:             self.seed,
 70:             self.config.with_level(level),
 71:         );
 72: 
 73:         let svo = BuildOctreeUseCase::new().execute(
 74:             &grid,
 75:             self.config.svo_depth(),
 76:             self.config.svo_world_size(),
 77:         );
 78: 
 79:         let gpu = OctreeGpuSerializer::serialize_to_gpu_data(&svo);
 80:         let collision = extract_collision_boxes(&svo, origin_x, origin_z, self.config.voxel_scale);
 81: 
 82:         ChunkPayload {
 83:             root: svo.root as u32,
 84:             nodes: gpu.texel_data,
 85:             world_size: self.config.svo_world_size(),
 86:             collision,
 87:         }
 88:     }
 89: }
 90: 
 91: /// Walks the SVO and emits one world-space AABB per solid leaf region.
 92: /// Uniform subtrees collapsed by the SVO become single large boxes for free,
 93: /// which keeps the collision set small.
 94: pub fn extract_collision_boxes(
 95:     svo: &SparseVoxelOctree,
 96:     origin_x: f32,
 97:     origin_z: f32,
 98:     voxel_scale: f32,
 99: ) -> Vec<Aabb> {
100:     let mut boxes = Vec::new();
101:     let size = 1u32 << svo.depth;
102:     walk(
103:         svo,
104:         svo.root,
105:         0,
106:         0,
107:         0,
108:         size,
109:         origin_x,
110:         origin_z,
111:         voxel_scale,
112:         &mut boxes,
113:     );
114:     boxes
115: }
116: 
117: #[allow(clippy::too_many_arguments)]
118: fn walk(
119:     svo: &SparseVoxelOctree,
120:     node_idx: usize,
121:     x: u32,
122:     y: u32,
123:     z: u32,
124:     size: u32,
125:     origin_x: f32,
126:     origin_z: f32,
127:     voxel_scale: f32,
128:     out: &mut Vec<Aabb>,
129: ) {
130:     match svo.nodes[node_idx] {
131:         SvoNode::Leaf { voxel_type, .. } => {
132:             if SOLID_TYPES.contains(&voxel_type) {
133:                 let min = [
134:                     origin_x + x as f32 * voxel_scale,
135:                     y as f32 * voxel_scale,
136:                     origin_z + z as f32 * voxel_scale,
137:                 ];
138:                 let extent = size as f32 * voxel_scale;
139:                 out.push(Aabb::new(
140:                     min,
141:                     [min[0] + extent, min[1] + extent, min[2] + extent],
142:                 ));
143:             }
144:         }
145:         SvoNode::Internal {
146:             child_base_index,
147:             child_mask,
148:         } => {
149:             let half = size / 2;
150:             for child in 0..8u32 {
151:                 if child_mask & (1 << child) != 0 {
152:                     walk(
153:                         svo,
154:                         child_base_index as usize + child as usize,
155:                         x + (child & 1) * half,
156:                         y + ((child >> 1) & 1) * half,
157:                         z + ((child >> 2) & 1) * half,
158:                         half,
159:                         origin_x,
160:                         origin_z,
161:                         voxel_scale,
162:                         out,
163:                     );
164:                 }
165:             }
166:         }
167:     }
168: }
169: 
170: #[cfg(test)]
171: mod tests {
172:     use super::*;
173:     use vackrooms::domain::entities::voxel_grid::{VOXEL_FLOOR, VOXEL_WALL, VoxelGrid};
174:     use vackrooms::frameworks_drivers::simple_noise::SimpleNoiseProvider;
175: 
176:     #[test]
177:     fn wall_leaf_becomes_world_space_box_and_floor_does_not() {
178:         let mut grid = VoxelGrid::new(4, 4, 4);
179:         grid.set(1, 0, 2, VOXEL_WALL);
180:         grid.set(0, 0, 0, VOXEL_FLOOR);
181:         let svo = BuildOctreeUseCase::new().execute(&grid, 2, 2.0);
182: 
183:         let boxes = extract_collision_boxes(&svo, 10.0, 20.0, 0.5);
184:         assert_eq!(boxes.len(), 1);
185:         let b = &boxes[0];
186:         assert_eq!(b.min, [10.5, 0.0, 21.0]);
187:         assert_eq!(b.max, [11.0, 0.5, 21.5]);
188:     }
189: 
190:     #[test]
191:     fn generated_chunk_produces_row_padded_nodes_and_some_collision() {
192:         let source =
193:             LocalChunkSource::new(SimpleNoiseProvider::new(), 42, GeneratorConfig::low_spec());
194:         let payload = source.load(10.0, 10.0, 0);
195:         // Row padding: node stream is a whole number of 1024-texel rows.
196:         assert_eq!(payload.nodes.len() % (1024 * 4), 0);
197:         assert!(payload.world_size > 0.0);
198:         assert!(
199:             !payload.collision.is_empty(),
200:             "a maze chunk must have walls"
201:         );
202:     }
203: }

files.wasm_frontend/src/application/atlas.rs:
  1: //! Merges the per-chunk GPU node arrays into one atlas texel stream.
  2: //!
  3: //! Every chunk's node array is already row-padded to whole 1024-texel rows by
  4: //! the core `OctreeGpuSerializer`, so simple concatenation keeps every chunk
  5: //! row-aligned inside the shared RGBA32UI texture. Each chunk's root index is
  6: //! rebased by its node offset within the merged stream.
  7: 
  8: use crate::application::ports::ChunkDraw;
  9: use crate::application::streaming::LoadedChunk;
 10: 
 11: /// The shader's fixed per-frame chunk table size (uniform array length).
 12: pub const MAX_CHUNKS: usize = 25;
 13: 
 14: pub struct AtlasBuild {
 15:     /// Merged RGBA32UI texel stream (4 u32 per SVO node).
 16:     pub texels: Vec<u32>,
 17:     /// Per-chunk draw table with atlas-rebased root indices.
 18:     pub draws: Vec<ChunkDraw>,
 19: }
 20: 
 21: pub fn build_atlas<'a, I: IntoIterator<Item = &'a LoadedChunk>>(chunks: I) -> AtlasBuild {
 22:     let mut texels: Vec<u32> = Vec::new();
 23:     let mut draws = Vec::new();
 24: 
 25:     for chunk in chunks {
 26:         let node_offset = (texels.len() / 4) as u32;
 27:         draws.push(ChunkDraw {
 28:             origin: [chunk.origin.0, 0.0, chunk.origin.1],
 29:             root_index: (node_offset + chunk.payload.root) as i32,
 30:             world_size: chunk.payload.world_size,
 31:         });
 32: 
 33:         // Literate Documentation:
 34:         // Each chunk's SVO contains local child indices stored as relative pointers in `child_base_index`.
 35:         // Since we are concatenating all chunks into a single large flat texture atlas, we must rebase
 36:         // these pointers by adding the chunk's node_offset within the shared texture.
 37:         // We identify internal nodes by checking if the type flag (first u32, channel R) is 0.
 38:         // If so, we offset the child base index (second u32, channel G) by node_offset.
 39:         let mut chunk_texels = chunk.payload.nodes.clone();
 40:         for i in 0..(chunk_texels.len() / 4) {
 41:             let t = i * 4;
 42:             if chunk_texels[t] == 0 {
 43:                 chunk_texels[t + 1] += node_offset;
 44:             }
 45:         }
 46:         texels.extend_from_slice(&chunk_texels);
 47:     }
 48: 
 49:     debug_assert!(
 50:         draws.len() <= MAX_CHUNKS,
 51:         "chunk table overflows the shader's uniform array ({} > {MAX_CHUNKS})",
 52:         draws.len()
 53:     );
 54: 
 55:     AtlasBuild { texels, draws }
 56: }
 57: 
 58: #[cfg(test)]
 59: mod tests {
 60:     use super::*;
 61:     use crate::application::ports::ChunkPayload;
 62: 
 63:     fn chunk(origin: (f32, f32), root: u32, node_count: usize) -> LoadedChunk {
 64:         LoadedChunk {
 65:             origin,
 66:             payload: ChunkPayload {
 67:                 root,
 68:                 nodes: vec![0; node_count * 4],
 69:                 world_size: 12.8,
 70:                 collision: vec![],
 71:             },
 72:         }
 73:     }
 74: 
 75:     #[test]
 76:     fn atlas_rebases_roots_by_cumulative_node_count() {
 77:         let chunks = [chunk((0.0, 0.0), 0, 1024), chunk((10.0, 0.0), 3, 2048)];
 78:         let build = build_atlas(chunks.iter());
 79:         assert_eq!(build.draws[0].root_index, 0);
 80:         // Second chunk starts after 1024 nodes; its local root 3 shifts along.
 81:         assert_eq!(build.draws[1].root_index, 1027);
 82:         assert_eq!(build.texels.len(), (1024 + 2048) * 4);
 83:     }
 84: 
 85:     #[test]
 86:     fn atlas_rebases_internal_nodes_child_base_indices() {
 87:         // Create chunk 0 with 256 nodes, all internal.
 88:         let mut chunk_0_nodes = vec![0; 256 * 4];
 89:         // chunk 0 node 0: internal, child_base = 0
 90:         chunk_0_nodes[0] = 0;
 91:         chunk_0_nodes[1] = 0;
 92: 
 93:         let mut chunk_1_nodes = vec![0; 512 * 4];
 94:         // chunk 1 node 0: internal, child_base = 8
 95:         chunk_1_nodes[0] = 0;
 96:         chunk_1_nodes[1] = 8;
 97:         // chunk 1 node 1: leaf (type 1)
 98:         chunk_1_nodes[4] = 1;
 99:         chunk_1_nodes[5] = 42; // voxel_type
100: 
101:         let chunks = [
102:             LoadedChunk {
103:                 origin: (0.0, 0.0),
104:                 payload: ChunkPayload {
105:                     root: 0,
106:                     nodes: chunk_0_nodes,
107:                     world_size: 10.0,
108:                     collision: vec![],
109:                 },
110:             },
111:             LoadedChunk {
112:                 origin: (10.0, 0.0),
113:                 payload: ChunkPayload {
114:                     root: 0,
115:                     nodes: chunk_1_nodes,
116:                     world_size: 10.0,
117:                     collision: vec![],
118:                 },
119:             },
120:         ];
121: 
122:         let build = build_atlas(chunks.iter());
123: 
124:         // Chunk 0 node 0: child_base should still be 0 (since offset is 0)
125:         assert_eq!(build.texels[1], 0);
126: 
127:         // Chunk 1 node 0 (starts at texel index 256):
128:         // child_base was 8, should be shifted by chunk 0 size (256) -> 264
129:         assert_eq!(build.texels[256 * 4 + 1], 264);
130: 
131:         // Chunk 1 node 1 (leaf): should NOT be shifted since R == 1
132:         assert_eq!(build.texels[257 * 4], 1); // R
133:         assert_eq!(build.texels[257 * 4 + 1], 42); // G (voxel_type)
134:     }
135: }

files.wasm_frontend/src/application/engine.rs:
  1: //! The frame-loop orchestrator: the application's central use case.
  2: //!
  3: //! `Engine::tick` is called once per animation frame by the browser driver
  4: //! with plain data in (`InputFrame`, dt) and drives everything else through
  5: //! ports: chunk loading via [`ChunkSourcePort`], drawing via [`RendererPort`].
  6: //! No browser types appear anywhere in this file, so the whole game loop is
  7: //! natively unit-testable.
  8: 
  9: use crate::application::atlas::{MAX_CHUNKS, build_atlas};
 10: use crate::application::collision::CollisionWorld;
 11: use crate::application::player::{MoveIntent, Player};
 12: use crate::application::ports::{ChunkDraw, ChunkSourcePort, FrameParams, RendererPort};
 13: use crate::application::streaming::{ChunkStore, LoadedChunk, StreamingPolicy, chunk_key};
 14: 
 15: /// Static configuration chosen by the composition root.
 16: #[derive(Debug, Clone, Copy)]
 17: pub struct EngineConfig {
 18:     pub seed: u32,
 19:     /// World-space chunk side length (must match the generator config).
 20:     pub chunk_size: f32,
 21:     /// Streaming radius in chunks (1 = 3x3, 2 = 5x5).
 22:     pub chunk_radius: i32,
 23:     /// Player spawn (eye position).
 24:     pub spawn: [f32; 3],
 25:     /// Chunks generated per tick. 2 balances streaming latency against
 26:     /// frame hitches: one chunk costs ~15 ms native (more in wasm), so
 27:     /// higher budgets stall the frame visibly.
 28:     pub max_loads_per_tick: usize,
 29: }
 30: 
 31: impl Default for EngineConfig {
 32:     fn default() -> Self {
 33:         Self {
 34:             seed: 42,
 35:             chunk_size: 10.0,
 36:             chunk_radius: 1,
 37:             spawn: [5.0, 1.7, 5.0],
 38:             max_loads_per_tick: 2,
 39:         }
 40:     }
 41: }
 42: 
 43: /// One frame's worth of user input, already translated to domain terms by
 44: /// the input adapter.
 45: #[derive(Debug, Clone, Copy, Default)]
 46: pub struct InputFrame {
 47:     pub intent: MoveIntent,
 48:     pub look_dx: f32,
 49:     pub look_dy: f32,
 50:     /// Whether pointer lock is engaged; movement is frozen otherwise.
 51:     pub locked: bool,
 52:     pub flashlight: bool,
 53: }
 54: 
 55: /// Snapshot for the HUD presenter.
 56: #[derive(Debug, Clone, Copy, PartialEq)]
 57: pub struct HudStats {
 58:     pub resident_chunks: usize,
 59:     pub atlas_nodes: usize,
 60:     pub collision_boxes: usize,
 61:     pub resolution_scale: f32,
 62:     /// True once the spawn chunk is resident (drives the loading overlay).
 63:     pub ready: bool,
 64: }
 65: 
 66: /// Adaptive internal-resolution governor. Low-spec machines get fewer rays
 67: /// per frame by rendering at a reduced backing-store resolution; the driver
 68: /// applies the scale to the canvas. Hysteresis + cooldown prevent flapping.
 69: #[derive(Debug, Clone, Copy)]
 70: pub struct PerfGovernor {
 71:     ema_frame_ms: f32,
 72:     scale: f32,
 73:     cooldown_frames: u32,
 74: }
 75: 
 76: impl PerfGovernor {
 77:     const SCALES: [f32; 4] = [0.5, 0.65, 0.8, 1.0];
 78: 
 79:     pub fn new() -> Self {
 80:         Self {
 81:             ema_frame_ms: 16.0,
 82:             scale: 0.8,
 83:             cooldown_frames: 0,
 84:         }
 85:     }
 86: 
 87:     pub fn scale(&self) -> f32 {
 88:         self.scale
 89:     }
 90: 
 91:     pub fn update(&mut self, frame_ms: f32) {
 92:         self.ema_frame_ms = self.ema_frame_ms * 0.95 + frame_ms.clamp(0.0, 100.0) * 0.05;
 93:         if self.cooldown_frames > 0 {
 94:             self.cooldown_frames -= 1;
 95:             return;
 96:         }
 97:         let idx = Self::SCALES
 98:             .iter()
 99:             .position(|&s| s == self.scale)
100:             .unwrap_or(2);
101:         if self.ema_frame_ms > 33.0 && idx > 0 {
102:             // Sustained under ~30 fps: drop one resolution step.
103:             self.scale = Self::SCALES[idx - 1];
104:             self.cooldown_frames = 120;
105:         } else if self.ema_frame_ms < 15.0 && idx + 1 < Self::SCALES.len() {
106:             // Sustained over ~66 fps: try one step up.
107:             self.scale = Self::SCALES[idx + 1];
108:             self.cooldown_frames = 240;
109:         }
110:     }
111: }
112: 
113: /// Backrooms level ids the engine can noclip between.
114: const LEVEL_BACKROOMS: u32 = 0;
115: const LEVEL_GRASSLAND: u32 = 34;
116: /// Keep pushing into a wall this long before a noclip roll happens...
117: const NOCLIP_PUSH_SECONDS: f32 = 1.2;
118: /// ...then one roll per second of continued pushing, at this probability.
119: const NOCLIP_CHANCE: f32 = 0.2;
120: 
121: pub struct Engine {
122:     config: EngineConfig,
123:     player: Player,
124:     policy: StreamingPolicy,
125:     store: ChunkStore,
126:     world: CollisionWorld,
127:     draws: Vec<ChunkDraw>,
128:     atlas_nodes: usize,
129:     governor: PerfGovernor,
130:     renderer: Box<dyn RendererPort>,
131:     source: Box<dyn ChunkSourcePort>,
132:     /// Active Backrooms level; chunks are requested for this level.
133:     level: u32,
134:     /// How long the player has been pushing into a wall without moving.
135:     push_seconds: f32,
136:     /// Seconds until the next noclip roll is allowed.
137:     noclip_cooldown: f32,
138:     /// xorshift state for the noclip dice.
139:     rng: u64,
140: }
141: 
142: impl Engine {
143:     pub fn new(
144:         config: EngineConfig,
145:         renderer: Box<dyn RendererPort>,
146:         source: Box<dyn ChunkSourcePort>,
147:     ) -> Self {
148:         let radius = config.chunk_radius.clamp(0, 2); // 5x5 max = shader table size
149:         Self {
150:             player: Player::new(config.spawn),
151:             policy: StreamingPolicy {
152:                 chunk_size: config.chunk_size,
153:                 radius,
154:             },
155:             store: ChunkStore::new(),
156:             world: CollisionWorld::new(),
157:             draws: Vec::new(),
158:             atlas_nodes: 0,
159:             governor: PerfGovernor::new(),
160:             renderer,
161:             source,
162:             level: LEVEL_BACKROOMS,
163:             push_seconds: 0.0,
164:             noclip_cooldown: 0.0,
165:             rng: (config.seed as u64).wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1,
166:             config,
167:         }
168:     }
169: 
170:     fn rng_next01(&mut self) -> f32 {
171:         self.rng ^= self.rng << 13;
172:         self.rng ^= self.rng >> 7;
173:         self.rng ^= self.rng << 17;
174:         (self.rng >> 40) as f32 / (1u64 << 24) as f32
175:     }
176: 
177:     /// Backrooms lore made mechanical: holding a walk into solid wall long
178:     /// enough occasionally phases the player through reality.
179:     fn update_noclip(&mut self, dt: f32, input: &InputFrame, old_pos: [f32; 3]) {
180:         self.noclip_cooldown = (self.noclip_cooldown - dt).max(0.0);
181: 
182:         let i = input.intent;
183:         let pushing = input.locked && (i.forward || i.backward || i.left || i.right);
184:         let dx = self.player.position[0] - old_pos[0];
185:         let dz = self.player.position[2] - old_pos[2];
186:         let pinned = pushing && (dx * dx + dz * dz) < 0.002 * 0.002;
187: 
188:         if !pinned {
189:             self.push_seconds = 0.0;
190:             return;
191:         }
192:         self.push_seconds += dt;
193:         if self.push_seconds < NOCLIP_PUSH_SECONDS || self.noclip_cooldown > 0.0 {
194:             return;
195:         }
196:         self.noclip_cooldown = 1.0;
197:         if self.rng_next01() < NOCLIP_CHANCE {
198:             self.noclip();
199:         }
200:     }
201: 
202:     /// Phase between Level 0 and the grassland: drop every resident chunk so
203:     /// the streamer rebuilds the world from the new level's generator.
204:     fn noclip(&mut self) {
205:         self.level = if self.level == LEVEL_BACKROOMS {
206:             LEVEL_GRASSLAND
207:         } else {
208:             LEVEL_BACKROOMS
209:         };
210:         self.store.retain_keys(&[]);
211:         self.world.rebuild([].iter());
212:         self.draws.clear();
213:         self.push_seconds = 0.0;
214:         // Into the grassland you phase in place; the way back drops you at
215:         // the spawn clearing so you can't rematerialize inside a wall.
216:         if self.level == LEVEL_BACKROOMS {
217:             self.player.position = self.config.spawn;
218:         }
219:     }
220: 
221:     /// The active Backrooms level id.
222:     pub fn level(&self) -> u32 {
223:         self.level
224:     }
225: 
226:     /// Advances the simulation one frame and issues the draw.
227:     pub fn tick(&mut self, dt_seconds: f32, input: &InputFrame) {
228:         // Clamp dt so a background-tab hitch can't teleport the player.
229:         let dt = dt_seconds.clamp(0.0, 0.1);
230:         self.governor.update(dt_seconds * 1000.0);
231: 
232:         let old_pos = self.player.position;
233:         if input.locked {
234:             self.player.apply_look(input.look_dx, input.look_dy);
235:             self.player.step(dt, &input.intent, &self.world);
236:         }
237:         self.update_noclip(dt, input, old_pos);
238: 
239:         self.stream_chunks();
240: 
241:         let frame = FrameParams {
242:             camera_pos: self.player.position,
243:             yaw: self.player.yaw,
244:             pitch: self.player.pitch,
245:             flashlight: input.flashlight,
246:         };
247:         self.renderer.draw(&frame, &self.draws);
248:     }
249: 
250:     /// Loads at most `max_loads_per_tick` missing chunks (nearest first),
251:     /// evicts out-of-range ones, and rebuilds the atlas + collision world
252:     /// only when the resident set actually changed.
253:     fn stream_chunks(&mut self) {
254:         let desired = self
255:             .policy
256:             .desired_origins(self.player.position[0], self.player.position[2]);
257:         let keep: Vec<_> = desired.iter().map(|&(x, z)| chunk_key(x, z)).collect();
258: 
259:         let mut changed = self.store.retain_keys(&keep);
260: 
261:         let mut loads = 0;
262:         for &(ox, oz) in &desired {
263:             if loads >= self.config.max_loads_per_tick {
264:                 break;
265:             }
266:             let key = chunk_key(ox, oz);
267:             if !self.store.contains(key) {
268:                 let payload = self.source.load(ox, oz, self.level);
269:                 self.store.insert(
270:                     key,
271:                     LoadedChunk {
272:                         origin: (ox, oz),
273:                         payload,
274:                     },
275:                 );
276:                 loads += 1;
277:                 changed = true;
278:             }
279:         }
280: 
281:         if changed {
282:             let build = build_atlas(self.store.iter_ordered());
283:             self.atlas_nodes = build.texels.len() / 4;
284:             self.draws = build.draws;
285:             self.draws.truncate(MAX_CHUNKS);
286:             self.renderer.upload_atlas(&build.texels);
287: 
288:             let boxes: Vec<_> = self.store.all_collision_boxes().copied().collect();
289:             self.world.rebuild(boxes.iter());
290:         }
291:     }
292: 
293:     pub fn player(&self) -> &Player {
294:         &self.player
295:     }
296: 
297:     pub fn collision_world(&self) -> &CollisionWorld {
298:         &self.world
299:     }
300: 
301:     pub fn stats(&self) -> HudStats {
302:         let spawn_key = chunk_key(
303:             (self.config.spawn[0] / self.config.chunk_size).floor() * self.config.chunk_size,
304:             (self.config.spawn[2] / self.config.chunk_size).floor() * self.config.chunk_size,
305:         );
306:         HudStats {
307:             resident_chunks: self.store.len(),
308:             atlas_nodes: self.atlas_nodes,
309:             collision_boxes: self.world.len(),
310:             resolution_scale: self.governor.scale(),
311:             ready: self.store.contains(spawn_key),
312:         }
313:     }
314: }
