  1: //! First-person player controller: mouse look, WASD movement with friction,
  2: //! and axis-separated sliding collision against the [`CollisionWorld`].
  3: //!
  4: //! The tuning constants are carried over 1:1 from the original JS client so
  5: //! the wasm port feels identical.
  6: 
  7: use crate::application::collision::CollisionWorld;
  8: 
  9: /// Acceleration applied while a movement key is held (units/s^2 toward the
 10: /// wish direction). Terminal speed = ACCELERATION / FRICTION = 2.5 u/s (increased from 0.5 u/s).
 11: const ACCELERATION: f32 = 20.0;
 12: /// Exponential velocity damping factor (1/s).
 13: const FRICTION: f32 = 8.0;
 14: /// Radians of yaw/pitch per pixel of mouse movement.
 15: const MOUSE_SENSITIVITY: f32 = 0.002;
 16: /// Pitch is clamped just short of straight up/down to avoid gimbal flip.
 17: const PITCH_LIMIT: f32 = std::f32::consts::FRAC_PI_2 - 0.05;
 18: 
 19: /// Which movement keys are currently held.
 20: #[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
 21: pub struct MoveIntent {
 22:     pub forward: bool,
 23:     pub backward: bool,
 24:     pub left: bool,
 25:     pub right: bool,
 26:     pub turn_left: bool,
 27:     pub turn_right: bool,
 28: }
 29: 
 30: /// Player state. Position is the *eye* position in world space.
 31: #[derive(Debug, Clone)]
 32: pub struct Player {
 33:     pub position: [f32; 3],
 34:     pub yaw: f32,
 35:     pub pitch: f32,
 36:     /// Velocity in camera-local space: x = strafe, z = forward.
 37:     vel_strafe: f32,
 38:     vel_forward: f32,
 39: }
 40: 
 41: impl Player {
 42:     pub fn new(position: [f32; 3]) -> Self {
 43:         Self {
 44:             position,
 45:             yaw: 0.0,
 46:             pitch: 0.0,
 47:             vel_strafe: 0.0,
 48:             vel_forward: 0.0,
 49:         }
 50:     }
 51: 
 52:     /// Applies a mouse movement delta (in pixels) to yaw/pitch.
 53:     pub fn apply_look(&mut self, dx: f32, dy: f32) {
 54:         self.yaw -= dx * MOUSE_SENSITIVITY;
 55:         self.pitch = (self.pitch - dy * MOUSE_SENSITIVITY).clamp(-PITCH_LIMIT, PITCH_LIMIT);
 56:     }
 57: 
 58:     /// World-space unit forward vector projected on the ground plane.
 59:     pub fn forward(&self) -> [f32; 3] {
 60:         [-self.yaw.sin(), 0.0, -self.yaw.cos()]
 61:     }
 62: 
 63:     /// World-space unit right vector on the ground plane.
 64:     pub fn right(&self) -> [f32; 3] {
 65:         [self.yaw.cos(), 0.0, -self.yaw.sin()]
 66:     }
 67: 
 68:     /// Integrates one physics step and resolves collision by sliding:
 69:     /// the X and Z axes are moved and tested independently, so hitting a
 70:     /// wall diagonally slides the player along it instead of stopping dead.
 71:     pub fn step(&mut self, dt: f32, intent: &MoveIntent, world: &CollisionWorld) {
 72:         // Friction: exponential-style decay, matching `v -= v * 8 * dt`.
 73:         self.vel_strafe -= self.vel_strafe * FRICTION * dt;
 74:         self.vel_forward -= self.vel_forward * FRICTION * dt;
 75: 
 76:         // Turn via keyboard (Doom controls)
 77:         let turn_speed = 3.0; // radians per second
 78:         if intent.turn_left {
 79:             self.yaw += turn_speed * dt;
 80:         }
 81:         if intent.turn_right {
 82:             self.yaw -= turn_speed * dt;
 83:         }
 84: 
 85:         let mut wish_forward = (intent.forward as i32 - intent.backward as i32) as f32;
 86:         let mut wish_strafe = (intent.right as i32 - intent.left as i32) as f32;
 87:         let len = (wish_forward * wish_forward + wish_strafe * wish_strafe).sqrt();
 88:         if len > 0.0 {
 89:             wish_forward /= len;
 90:             wish_strafe /= len;
 91:         }
 92: 
 93:         self.vel_forward += wish_forward * ACCELERATION * dt;
 94:         self.vel_strafe += wish_strafe * ACCELERATION * dt;
 95: 
 96:         let fwd = self.forward();
 97:         let rgt = self.right();
 98:         let step_x = (fwd[0] * self.vel_forward + rgt[0] * self.vel_strafe) * dt;
 99:         let step_z = (fwd[2] * self.vel_forward + rgt[2] * self.vel_strafe) * dt;
100: 
101:         let old = self.position;
102: 
103:         self.position[0] = old[0] + step_x;
104:         if world.collides(self.position) {
105:             self.position[0] = old[0];
106:         }
107: 
108:         self.position[2] = old[2] + step_z;
109:         if world.collides(self.position) {
110:             self.position[2] = old[2];
111:         }
112:     }
113: }
114: 
