116: mod tests {
117:     use super::*;
118:     use crate::application::collision::Aabb;
119: 
120:     fn walk(player: &mut Player, world: &CollisionWorld, intent: MoveIntent, seconds: f32) {
121:         let dt = 1.0 / 60.0;
122:         let steps = (seconds / dt) as usize;
123:         for _ in 0..steps {
124:             player.step(dt, &intent, world);
125:         }
126:     }
