128:     #[test]
129:     fn forward_intent_moves_along_negative_z_at_zero_yaw() {
130:         let world = CollisionWorld::new();
131:         let mut p = Player::new([0.0, 1.7, 0.0]);
132:         walk(
133:             &mut p,
134:             &world,
135:             MoveIntent {
136:                 forward: true,
137:                 ..Default::default()
138:             },
139:             2.0,
140:         );
141:         assert!(
142:             p.position[2] < -0.5,
143:             "expected forward motion, z = {}",
144:             p.position[2]
145:         );
146:         assert!(p.position[0].abs() < 1e-3);
147:     }
148: 
149:     #[test]
150:     fn speed_converges_to_terminal_velocity() {
151:         let world = CollisionWorld::new();
152:         let mut p = Player::new([0.0, 1.7, 0.0]);
153:         walk(
154:             &mut p,
155:             &world,
156:             MoveIntent {
157:                 forward: true,
158:                 ..Default::default()
159:             },
160:             5.0,
161:         );
162:         let before = p.position[2];
163:         walk(
164:             &mut p,
165:             &world,
166:             MoveIntent {
167:                 forward: true,
168:                 ..Default::default()
169:             },
170:             1.0,
171:         );
172:         let speed = (before - p.position[2]).abs();
173:         // Terminal speed = ACCELERATION / FRICTION = 2.5 u/s (was 0.5 u/s).
174:         assert!((speed - 2.5).abs() < 0.05, "speed was {speed}");
175:     }
176: 
177:     #[test]
178:     fn diagonal_wall_hit_slides_along_wall() {
179:         let mut world = CollisionWorld::new();
180:         // Wall blocking motion in -z ahead of the player.
181:         world.rebuild(&[Aabb::new([-10.0, 0.0, -2.0], [10.0, 3.0, -1.8])]);
182:         let mut p = Player::new([0.0, 1.7, 0.0]);
183:         // Move forward-right: z blocked by the wall, x should still advance.
184:         walk(
185:             &mut p,
186:             &world,
187:             MoveIntent {
188:                 forward: true,
189:                 right: true,
190:                 ..Default::default()
191:             },
192:             4.0,
193:         );
194:         assert!(p.position[2] > -1.5, "should be stopped by wall");
195:         assert!(
196:             p.position[0] > 0.5,
197:             "should have slid along the wall, x = {}",
198:             p.position[0]
199:         );
200:     }
201: }

