files.wasm_frontend/src/drivers/shaders.rs:
  1: //! GLSL ES 3.00 shaders for the fullscreen SVO raymarcher.
  2: //!
  3: //! Ported 1:1 from the proven raw-WebGL2 path of the original JS client.
  4: //! Pipeline per fragment:
  5: //!   1. Reconstruct the camera ray from NDC + yaw/pitch.
  6: //!   2. Slab-test every resident chunk AABB, insertion-sorting hits by entry
  7: //!      distance so the nearest chunk is marched first (early out on hit).
  8: //!   3. March the chunk's SVO with stack-based descent + empty-space skipping:
  9: //!      an empty leaf/octant is exited in a single step via its AABB exit
 10: //!      plane instead of voxel-by-voxel DDA.
 11: //!   4. Shade from the leaf's packed RGB color, BFS light level, face normal
 12: //!      and exponential distance fog.
 13: //!
 14: //! The SVO node atlas lives in a 1024-texel-wide RGBA32UI texture; the texel
 15: //! encoding is documented in the core's `OctreeGpuSerializer`.
 16: 
 17: /// Fullscreen-triangle-pair vertex shader.
 18: pub const VERTEX_SHADER: &str = r#"#version 300 es
 19: in vec2 position;
 20: out vec2 vUv;
 21: void main() {
 22:     vUv = position * 0.5 + 0.5;
 23:     gl_Position = vec4(position, 0.0, 1.0);
 24: }
 25: "#;
 26: 
 27: pub const FRAGMENT_SHADER: &str = r#"#version 300 es
 28: precision highp float;
 29: precision highp usampler2D;
 30: 
 31: in vec2 vUv;
 32: out vec4 fragColor;
 33: 
 34: uniform vec3 uCameraPosition;
 35: uniform float uYaw;
 36: uniform float uPitch;
 37: uniform float uAspect;
 38: 
 39: uniform float uFaceWeightTop;
 40: uniform float uFaceWeightBottom;
 41: uniform float uFaceWeightX;
 42: uniform float uFaceWeightZ;
 43: 
 44: uniform int uFlashlightEnabled;
 45: 
 46: uniform usampler2D uNodeTexture;
 47: uniform int uNumChunks;
 48: uniform vec3 uChunkOrigins[25];
 49: uniform int uChunkRootIndices[25];
 50: uniform float uChunkWorldSizes[25];
 51: 
 52: struct StackFrame {
 53:     int node_idx;
 54:     vec3 b_min;
 55:     vec3 b_max;
 56: };
 57: 
 58: struct ChunkHit {
 59:     int idx;
 60:     float t_min;
 61:     float t_max;
 62: };
 63: 
 64: struct DecodedNode {
 65:     bool isLeaf;
 66:     uint voxelType;
 67:     uint color;
 68:     uint lightLevel;
 69:     uint childBaseIndex;
 70:     uint childMask;
 71: };
 72: 
 73: ivec2 nodeIndexToTexel(int nodeIndex, int textureWidth) {
 74:     return ivec2(nodeIndex % textureWidth, nodeIndex / textureWidth);
 75: }
 76: 
 77: DecodedNode decodeNode(usampler2D octreeTex, int nodeIndex, int textureWidth) {
 78:     ivec2 texCoord = nodeIndexToTexel(nodeIndex, textureWidth);
 79:     uvec4 node = texelFetch(octreeTex, texCoord, 0);
 80: 
 81:     DecodedNode decoded;
 82:     decoded.isLeaf = (node.x == 1u);
 83: 
 84:     if (decoded.isLeaf) {
 85:         decoded.voxelType = node.y;
 86:         decoded.color = node.z;
 87:         decoded.lightLevel = node.w;
 88:         decoded.childBaseIndex = 0u;
 89:         decoded.childMask = 0u;
 90:     } else {
 91:         decoded.voxelType = 0u;
 92:         decoded.color = 0u;
 93:         decoded.lightLevel = 0u;
 94:         decoded.childBaseIndex = node.y;
 95:         decoded.childMask = node.z;
 96:     }
 97:     return decoded;
 98: }
 99: 
100: bool raymarchSVO(
101:     vec3 ro, vec3 rd,
102:     int chunk_root_idx,
103:     float t_entry, float t_exit,
104:     float world_size,
105:     out vec4 hitColor, out vec3 hitNormal, out bool isLight, out uint hitVoxelType, out float hit_t, out uint hitOcclusion
106: ) {
107:     float t = t_entry;
108:     vec3 p = ro + t * rd;
109: 
110:     StackFrame stack[9];
111:     int stack_ptr = 0;
112: 
113:     int current_node = chunk_root_idx;
114:     vec3 current_min = vec3(0.0);
115:     vec3 current_max = vec3(world_size);
116: 
117:     int steps = 0;
118:     const int MAX_STEPS = 160;
119: 
120:     while (steps < MAX_STEPS) {
121:         steps++;
122: 
123:         DecodedNode node = decodeNode(uNodeTexture, current_node, 1024);
124: 
125:         if (node.isLeaf) {
126:             if (node.voxelType != 0u) {
127:                 float r = float((node.color >> 16) & 0xFFu) / 255.0;
128:                 float g = float((node.color >> 8) & 0xFFu) / 255.0;
129:                 float b = float(node.color & 0xFFu) / 255.0;
130:                 float light = float(node.lightLevel & 0xFFu) / 15.0;
131:                 uint occlusionBits = (node.lightLevel >> 8u) & 0xFFu;
132: 
133:                 hitColor = vec4(r, g, b, light);
134:                 isLight = (node.voxelType == 4u || node.voxelType == 9u);
135:                 hitVoxelType = node.voxelType;
136:                 hitOcclusion = occlusionBits;
137: 
138:                 vec3 hit_p = ro + t * rd;
139:                 vec3 center = (current_min + current_max) * 0.5;
140:                 vec3 size = (current_max - current_min) * 0.5;
141:                 vec3 local_p = (hit_p - center) / size;
142:                 vec3 abs_p = abs(local_p);
143: 
144:                 if (abs_p.x > abs_p.y && abs_p.x > abs_p.z) {
145:                     hitNormal = vec3(sign(local_p.x), 0.0, 0.0);
146:                 } else if (abs_p.y > abs_p.x && abs_p.y > abs_p.z) {
147:                     hitNormal = vec3(0.0, sign(local_p.y), 0.0);
148:                 } else {
149:                     hitNormal = vec3(0.0, 0.0, sign(local_p.z));
150:                 }
151:                 hit_t = t;
152:                 return true;
153:             } else {
154:                 // Empty-space skip: jump straight to this leaf's exit plane.
155:                 vec3 t_max_planes = (vec3(
156:                     rd.x > 0.0 ? current_max.x : current_min.x,
157:                     rd.y > 0.0 ? current_max.y : current_min.y,
158:                     rd.z > 0.0 ? current_max.z : current_min.z
159:                 ) - ro) / rd;
160: 
161:                 float t_exit_box = min(t_max_planes.x, min(t_max_planes.y, t_max_planes.z));
162:                 t = t_exit_box;
163:                 p = ro + t * rd;
164:                 // Snap every tied axis past its exit plane: leaving an axis
165:                 // exactly ON its plane stalls the march (t stops advancing).
166:                 if (abs(t_exit_box - t_max_planes.x) < 0.0001) p.x = (rd.x > 0.0 ? current_max.x : current_min.x) + (rd.x > 0.0 ? 0.001 : -0.001);
167:                 if (abs(t_exit_box - t_max_planes.y) < 0.0001) p.y = (rd.y > 0.0 ? current_max.y : current_min.y) + (rd.y > 0.0 ? 0.001 : -0.001);
168:                 if (abs(t_exit_box - t_max_planes.z) < 0.0001) p.z = (rd.z > 0.0 ? current_max.z : current_min.z) + (rd.z > 0.0 ? 0.001 : -0.001);
169: 
170:                 // Pop EVERY level the ray exited: a skip through a plane
171:                 // shared by several ancestor boxes leaves p outside more
172:                 // than one of them, and descending from a box that no
173:                 // longer contains p corrupts the traversal (wall cracks).
174:                 while (p.x < current_min.x || p.x > current_max.x ||
175:                        p.y < current_min.y || p.y > current_max.y ||
176:                        p.z < current_min.z || p.z > current_max.z) {
177: 
178:                     if (stack_ptr == 0) return false;
179:                     stack_ptr--;
180:                     current_node = stack[stack_ptr].node_idx;
181:                     current_min = stack[stack_ptr].b_min;
182:                     current_max = stack[stack_ptr].b_max;
183:                 }
184:             }
185:         } else {
186:             vec3 center = (current_min + current_max) * 0.5;
187:             int ox = p.x >= center.x ? 1 : 0;
188:             int oy = p.y >= center.y ? 1 : 0;
189:             int oz = p.z >= center.z ? 1 : 0;
190:             int child_idx = (oz << 2) | (oy << 1) | ox;
191: 
192:             if ((node.childMask & (1u << uint(child_idx))) != 0u) {
193:                 // Descend into the occupied octant.
194:                 if (stack_ptr < 8) {
195:                     stack[stack_ptr] = StackFrame(current_node, current_min, current_max);
196:                     stack_ptr++;
197:                 }
198:                 current_min.x = ox == 1 ? center.x : current_min.x;
199:                 current_max.x = ox == 1 ? current_max.x : center.x;
200:                 current_min.y = oy == 1 ? center.y : current_min.y;
201:                 current_max.y = oy == 1 ? current_max.y : center.y;
202:                 current_min.z = oz == 1 ? center.z : current_min.z;
203:                 current_max.z = oz == 1 ? current_max.z : center.z;
204:                 current_node = int(node.childBaseIndex) + child_idx;
205:             } else {
206:                 // Masked-out (air) octant: skip it in one step.
207:                 vec3 oct_max = vec3(
208:                     ox == 1 ? current_max.x : center.x,
209:                     oy == 1 ? current_max.y : center.y,
210:                     oz == 1 ? current_max.z : center.z
211:                 );
212:                 vec3 oct_min = vec3(
213:                     ox == 1 ? center.x : current_min.x,
214:                     oy == 1 ? center.y : current_min.y,
215:                     oz == 1 ? center.z : current_min.z
216:                 );
217:                  vec3 t_max_planes = (vec3(
218:                     rd.x > 0.0 ? oct_max.x : oct_min.x,
219:                     rd.y > 0.0 ? oct_max.y : oct_min.y,
220:                     rd.z > 0.0 ? oct_max.z : oct_min.z
221:                 ) - ro) / rd;
222: 
223:                 float t_exit_oct = min(t_max_planes.x, min(t_max_planes.y, t_max_planes.z));
224:                 t = t_exit_oct;
225:                 p = ro + t * rd;
226:                 if (abs(t_exit_oct - t_max_planes.x) < 0.0001) p.x = (rd.x > 0.0 ? oct_max.x : oct_min.x) + (rd.x > 0.0 ? 0.001 : -0.001);
227:                 if (abs(t_exit_oct - t_max_planes.y) < 0.0001) p.y = (rd.y > 0.0 ? oct_max.y : oct_min.y) + (rd.y > 0.0 ? 0.001 : -0.001);
228:                 if (abs(t_exit_oct - t_max_planes.z) < 0.0001) p.z = (rd.z > 0.0 ? oct_max.z : oct_min.z) + (rd.z > 0.0 ? 0.001 : -0.001);
229: 
230:                 // Same multi-level pop as the empty-leaf skip above.
231:                 while (p.x < current_min.x || p.x > current_max.x ||
232:                        p.y < current_min.y || p.y > current_max.y ||
233:                        p.z < current_min.z || p.z > current_max.z) {
234: 
235:                     if (stack_ptr == 0) return false;
236:                     stack_ptr--;
237:                     current_node = stack[stack_ptr].node_idx;
238:                     current_min = stack[stack_ptr].b_min;
239:                     current_max = stack[stack_ptr].b_max;
240:                 }
241:             }
242:         }
243:     }
244:     return false;
245: }
246: 
247: void main() {
248:     vec2 ndc = vUv * 2.0 - 1.0;
249:     // 0.767 = tan(75deg FOV / 2)
250:     vec3 rd_local = normalize(vec3(ndc.x * uAspect * 0.767, ndc.y * 0.767, -1.0));
251: 
252:     float cp = cos(uPitch);
253:     float sp = sin(uPitch);
254:     vec3 rd_pitched = vec3(
255:         rd_local.x,
256:         rd_local.y * cp - rd_local.z * sp,
257:         rd_local.y * sp + rd_local.z * cp
258:     );
259: 
260:     float cy = cos(uYaw);
261:     float sy = sin(uYaw);
262:     vec3 rd = vec3(
263:         rd_pitched.x * cy + rd_pitched.z * sy,
264:         rd_pitched.y,
265:         -rd_pitched.x * sy + rd_pitched.z * cy
266:     );
267: 
268:     vec3 ro = uCameraPosition;
269: 
270:     ChunkHit hits[25];
271:     int numHits = 0;
272: 
273:     vec3 safe_rd = vec3(
274:         abs(rd.x) < 1e-4 ? sign(rd.x) * 1e-4 : rd.x,
275:         abs(rd.y) < 1e-4 ? sign(rd.y) * 1e-4 : rd.y,
276:         abs(rd.z) < 1e-4 ? sign(rd.z) * 1e-4 : rd.z
277:     );
278:     vec3 invRd = 1.0 / safe_rd;
279: 
280:     // Chunk-level "coarse geometry" pass: slab-test each chunk AABB and
281:     // insertion-sort by entry distance so we march nearest-first.
282:     for (int i = 0; i < uNumChunks; i++) {
283:         vec3 local_ro = ro - uChunkOrigins[i];
284: 
285:         vec3 box_min = vec3(0.0);
286:         vec3 box_max = vec3(uChunkWorldSizes[i]);
287: 
288:         vec3 t1 = (box_min - local_ro) * invRd;
289:         vec3 t2 = (box_max - local_ro) * invRd;
290:         vec3 t_min_p = min(t1, t2);
291:         vec3 t_max_p = max(t1, t2);
292: 
293:         float t_entry = max(t_min_p.x, max(t_min_p.y, t_min_p.z));
294:         float t_exit = min(t_max_p.x, min(t_max_p.y, t_max_p.z));
295: 
296:         if (t_entry < t_exit && t_exit > 0.0) {
297:             float real_entry = max(t_entry, 0.0);
298:             int insert_pos = numHits;
299:             while (insert_pos > 0 && hits[insert_pos - 1].t_min > real_entry) {
300:                 hits[insert_pos] = hits[insert_pos - 1];
301:                 insert_pos--;
302:             }
303:             hits[insert_pos] = ChunkHit(i, real_entry, t_exit);
304:             numHits++;
305:         }
306:     }
307: 
308:     vec4 finalColor = vec4(0.0);
309:     vec3 finalNormal = vec3(0.0);
310:     bool hitSolid = false;
311:     bool hitIsLight = false;
312:     uint finalVoxelType = 0u;
313:     uint finalOcclusion = 0u;
314:     float closest_t = 1e6;
315:     int hit_chunk_idx = -1;
316: 
317:     for (int k = 0; k < numHits; k++) {
318:         int i = hits[k].idx;
319:         vec3 local_ro = ro - uChunkOrigins[i];
320: 
321:         vec4 col;
322:         vec3 norm;
323:         bool isL;
324:         uint h_voxel_type;
325:         float h_t;
326:         uint h_occlusion;
327:         // Literate Documentation:
328:         // Pass safe_rd instead of the raw direction vector rd to prevent division-by-zero and
329:         // resulting NaN states in SVO traversal when the view direction aligns with any coordinate axis.
330:         if (raymarchSVO(local_ro, safe_rd, uChunkRootIndices[i], hits[k].t_min, hits[k].t_max,
331:                         uChunkWorldSizes[i], col, norm, isL, h_voxel_type, h_t, h_occlusion)) {
332:             finalColor = col;
333:             finalNormal = norm;
334:             hitSolid = true;
335:             hitIsLight = isL;
336:             finalVoxelType = h_voxel_type;
337:             finalOcclusion = h_occlusion;
338:             closest_t = h_t;
339:             hit_chunk_idx = i;
340:             break;
341:         }
342:     }
343: 
344:     if (hitSolid) {
345:         vec3 albedo = hitIsLight ? vec3(1.0) : finalColor.rgb;
346:         float staticLight = finalColor.a;
347:         
348:         vec3 N = finalNormal;
349:         vec3 V = -rd; // View direction pointing back to camera
350:         
351:         if (hitIsLight) {
352:             fragColor = vec4(finalColor.rgb * 1.5, 1.0);
353:             return;
354:         }
355:         
356:         // 1. Natural Ambient & Better Shadows
357:         float voxel_scale = uChunkWorldSizes[hit_chunk_idx] > 20.0 ? 0.1 : 0.2;
358:         vec3 local_hit_p = (ro - uChunkOrigins[hit_chunk_idx]) + closest_t * rd;
359:         
360:         float distToFloor = local_hit_p.y - voxel_scale;
361:         float distToCeiling = (3.0 - voxel_scale) - local_hit_p.y;
362:         
363:         // Soft contact shadow AO in corners where walls meet floor/ceiling
364:         float edgeAO = 1.0;
365:         if (abs(N.y) < 0.5) { // Only apply to vertical walls
366:             edgeAO = smoothstep(0.0, 0.4, distToFloor) * smoothstep(0.0, 0.4, distToCeiling);
367:             edgeAO = mix(0.55, 1.0, edgeAO);
368:         }
369:         
370:         // Brighter and warmer ambient colors for a natural Backrooms look
371:         float bfs_term = 0.4 + 0.8 * staticLight; // Boosted base brightness
372:         vec3 vSq = V * V;
373:         float y_val = V.y > 0.0 ? uFaceWeightTop : uFaceWeightBottom;
374:         float face_shading_scalar = vSq.x * uFaceWeightX + vSq.y * y_val + vSq.z * uFaceWeightZ;
375: 
376:         // Decode per-face occlusion from the 6-bit mask
377:         bool isOccluded = false;
378:         if (N.x > 0.5) { isOccluded = ((finalOcclusion & 1u) != 0u); }
379:         else if (N.x < -0.5) { isOccluded = ((finalOcclusion & 2u) != 0u); }
380:         else if (N.y > 0.5) { isOccluded = ((finalOcclusion & 4u) != 0u); }
381:         else if (N.y < -0.5) { isOccluded = ((finalOcclusion & 8u) != 0u); }
382:         else if (N.z > 0.5) { isOccluded = ((finalOcclusion & 16u) != 0u); }
383:         else if (N.z < -0.5) { isOccluded = ((finalOcclusion & 32u) != 0u); }
384:         
385:         bool isRedLight = ((finalOcclusion & 64u) != 0u);
386:         vec3 lightTint = isRedLight ? vec3(1.0, 0.4, 0.4) : vec3(1.0, 0.98, 0.90);
387:         
388:         float face_occlusion_factor = isOccluded ? 0.35 : 1.0;
389:         
390:         vec3 groundColor = vec3(0.24, 0.21, 0.16);
391:         vec3 skyColor = vec3(0.52, 0.48, 0.40);
392:         vec3 ambient = mix(groundColor, skyColor, N.y * 0.5 + 0.5) * (bfs_term * face_shading_scalar * face_occlusion_factor) * edgeAO;
393:         ambient *= isRedLight ? vec3(1.0, 0.7, 0.7) : vec3(1.0);
394:         
395:         // 2. Beautiful Faux-Directional Room/Ceiling Lights
396:         // Assume a point light is roughly at the center of the nearest 10x10 cell (3 world units)
397:         vec2 cell_center = floor(local_hit_p.xz / 3.0) * 3.0 + 1.5;
398:         vec3 light_pos = vec3(cell_center.x, 3.6, cell_center.y);
399:         vec3 auto_L = normalize(light_pos - local_hit_p);
400:         
401:         // Wrapped diffuse allows vertical walls to catch ambient overhead light realistically
402:         float wrappedNdotL = dot(N, auto_L) * 0.5 + 0.5;
403:         float staticDiffuse = wrappedNdotL * staticLight * 0.9;
404:         vec3 staticDiffuseContrib = staticDiffuse * albedo * lightTint;
405:         
406:         // Per-voxel material lookup (Fixed mappings)
407:         float roughness = 0.9;
408:         float specularStrength = 0.0;
409:         if (finalVoxelType == 1u) { // VOXEL_WALL
410:             roughness = 0.85;
411:             specularStrength = 0.02;
412:         } else if (finalVoxelType == 2u) { // VOXEL_FLOOR (carpet)
413:             roughness = 1.0;
414:             specularStrength = 0.0; // Completely diffuse
415:         } else if (finalVoxelType == 3u) { // VOXEL_CEILING
416:             roughness = 0.5;
417:             specularStrength = 0.15;
418:         } else if (finalVoxelType == 5u) { // VOXEL_RED_WALL
419:             roughness = 0.7;
420:             specularStrength = 0.08;
421:         } else if (finalVoxelType == 8u) { // VOXEL_TREE / PILLAR
422:             roughness = 0.4;
423:             specularStrength = 0.25;
424:         }
425: 
426:         // Blinn-Phong specular term modulated by per-voxel roughness
427:         float shininess = mix(256.0, 4.0, roughness);
428:         vec3 staticH = normalize(auto_L + V);
429:         float staticSpecular = pow(max(dot(N, staticH), 0.0), shininess) * staticLight * specularStrength;
430:         vec3 staticSpecularContrib = staticSpecular * lightTint;
431:         
432:         vec3 staticContrib = (staticDiffuseContrib + staticSpecularContrib) * edgeAO;
433:         
434:         // Total Lighting
435:         vec3 litColor = albedo * ambient + staticContrib;
436:         
437:         if (uFlashlightEnabled == 1) {
438:             // Flashlight points forward from the camera (in world space, the view direction is roughly V = -rd).
439:             // L is the vector from the surface point to the light.
440:             // Since the flashlight is attached to the camera, L is essentially V.
441:             vec3 flashL = V;
442:             
443:             // Attenuation based on distance (closest_t is ray length)
444:             float dist = closest_t;
445:             float atten = 1.0 / (1.0 + 0.1 * dist + 0.05 * dist * dist);
446:             
447:             // Spotlight effect: how close is the fragment to the center of the screen?
448:             // The camera forward vector in world space is roughly the center ray, but we don't have it directly.
449:             // However, we can approximate the spotlight falloff by comparing 'rd' to the center ray...
450:             // Actually, a simpler headlamp effect is just to use N dot V.
451:             float flashNdotL = max(dot(N, flashL), 0.0);
452:             vec3 flashDiffuse = albedo * flashNdotL * atten * 1.5;
453:             
454:             // Specular for flashlight
455:             vec3 flashH = normalize(flashL + V);
456:             float flashSpecular = pow(max(dot(N, flashH), 0.0), shininess) * atten * specularStrength * 1.5;
457:             
458:             litColor += (flashDiffuse + flashSpecular) * vec3(1.0, 0.95, 0.9);
459:         }
460:         
461:         // 3. Fog and Vignette
462:         float dist = closest_t;
463:         float fogFactor = exp(-0.02 * dist);
464:         
465:         float vignette = vUv.x * vUv.y * (1.0 - vUv.x) * (1.0 - vUv.y);
466:         vignette = clamp(pow(16.0 * vignette, 0.25), 0.0, 1.0);
467:         
468:         fragColor = vec4(mix(vec3(0.0), litColor, fogFactor * vignette), 1.0);
469:     } else {
470:         fragColor = vec4(0.0, 0.0, 0.0, 1.0);
471:     }
472: }
