 253: pub struct GenerateChunkArchitectureUseCase<'a> {
 254:     noise_provider: &'a dyn NoiseProvider,
 255:     telemetry: &'a dyn TelemetryPort,
 256: }
 257: 
 258: impl<'a> GenerateChunkArchitectureUseCase<'a> {
 259:     /// Constructs the use case with silent telemetry (tests, wasm default).
 260:     pub fn new(noise_provider: &'a dyn NoiseProvider) -> Self {
 261:         Self {
 262:             noise_provider,
 263:             telemetry: &NULL_TELEMETRY,
 264:         }
 265:     }
 266: 
 267:     /// Constructs the use case with an injected telemetry sink (native server,
 268:     /// browser console, ...). Keeps the Dependency Rule intact: the use case
 269:     /// only knows the TelemetryPort trait.
 270:     pub fn with_telemetry(
 271:         noise_provider: &'a dyn NoiseProvider,
 272:         telemetry: &'a dyn TelemetryPort,
 273:     ) -> Self {
 274:         Self {
 275:             noise_provider,
 276:             telemetry,
 277:         }
 278:     }
 279: 
 280:     pub fn execute(&self, chunk_pos: Position, seed: u32, config: GeneratorConfig) -> VoxelGrid {
 281:         // Pluggable levels: everything except the legacy office blueprint
 282:         // (level 1, kept inline below) goes through the LevelGenerator port.
 283:         if config.level == 34 {
 284:             // Grassland
 285:             use crate::use_cases::grassland_level::GrasslandLevel;
 286:             use crate::use_cases::level_generator::{LEVEL_GRASSLAND, LevelGenerator};
 287: 
 288:             let start_micros = self.telemetry.now_micros();
 289:             let generator: &dyn LevelGenerator = &GrasslandLevel;
 290:             let mut grid = generator.generate(chunk_pos, seed, config, self.noise_provider);
 291:             crate::domain::use_cases::calculate_lighting::calculate_voxel_lighting(&mut grid);
 292:             crate::domain::use_cases::path_tracer::bake_face_occlusion(&mut grid);
 293: 
 294:             let elapsed_micros = self.telemetry.now_micros().saturating_sub(start_micros);
 295:             self.telemetry.log(&format!(
 296:                 "[TELEMETRY] level {} chunk generated. Duration={}us, Grid={}x{}x{}",
 297:                 config.level,
 298:                 elapsed_micros,
 299:                 grid.width(),
 300:                 grid.height(),
 301:                 grid.depth()
 302:             ));
 303:             return grid;
 304:         }
 305: 
 306:         let start_micros = self.telemetry.now_micros();
 307: 
 308:         let width = (config.chunk_size / config.voxel_scale) as usize;
 309:         let depth = (config.chunk_size / config.voxel_scale) as usize;
 310: 
 311:         let cell_vw = (5.0 / config.voxel_scale) as usize;
 312:         let cell_vd = (5.0 / config.voxel_scale) as usize;
 313:         let cell_w = width / cell_vw;
 314:         let cell_d = depth / cell_vd;
 315: 
 316:         let mut abstract_grid = Grid::new(cell_w, cell_d);
 317: 
 318:         // --- ZONE ASSIGNMENT PASS ---
 319:         let mut max_chunk_height_units = 3.0_f32;
 320:         for cz in 0..cell_d {
 321:             for cx in 0..cell_w {
 322:                 let wx = chunk_pos.x * config.chunk_size + (cx as f32) * 5.0;
 323:                 let wz = chunk_pos.z * config.chunk_size + (cz as f32) * 5.0;
 324: 
 325:                 // Low frequency noise for zone clustering
 326:                 let n = self.noise_provider.evaluate_2d(
 327:                     seed ^ 0x2b8f_a43c,
 328:                     crate::entities::models::Position::new(wx * 0.05, wz * 0.05),
 329:                 ); // n is in [-1, 1]
 330: 
 331:                 use crate::domain::entities::cell::MicrobiomeZone;
 332:                 let mut zone = MicrobiomeZone::Standard;
 333: 
 334:                 if n < -0.7 {
 335:                     zone = MicrobiomeZone::Blackout;
 336:                 } else if n < -0.4 {
 337:                     zone = MicrobiomeZone::Holes;
 338:                 } else if n > 0.85 - (config.tuning.atria as f32 * 0.1) {
 339:                     zone = MicrobiomeZone::Atrium;
 340:                 } else if n > 0.6 {
 341:                     zone = MicrobiomeZone::PillarField;
 342:                 } else if n > 0.4 {
 343:                     zone = MicrobiomeZone::Arch;
 344:                 } else if n > 0.2 && n < 0.25 {
 345:                     zone = MicrobiomeZone::RedRoom;
 346:                 }
 347: 
 348:                 if let Some(cell) = abstract_grid.get_mut(cx, cz) {
 349:                     cell.zone = zone;
 350:                 }
 351: 
 352:                 let cell_h = match zone {
 353:                     MicrobiomeZone::Atrium => 12.0,  // 4.0 * 3.0x
 354:                     MicrobiomeZone::Blackout => 3.2, // 4.0 * 0.8x
 355:                     _ => 4.0,
 356:                 };
 357:                 if cell_h > max_chunk_height_units {
 358:                     max_chunk_height_units = cell_h;
 359:                 }
 360:             }
 361:         }
 362: 
 363:         let height = (max_chunk_height_units / config.voxel_scale).ceil() as usize + 2; // +2 for floor and ceiling bounds
 364: 
 365:         self.telemetry.log(&format!(
 366:             "[INFO] Entering GenerateChunkArchitectureUseCase::execute. Args: chunk_pos={:?}, seed={}, chunk_size={} (Voxel dimensions: {}x{}x{})",
 367:             chunk_pos, seed, config.chunk_size, width, height, depth
 368:         ));
 369: 
 370:         let mut grid = VoxelGrid::new(width, height, depth);
 371: 
 372:         // STARTING HUB OVERRIDE: Chunk (0,0) is a massive open plaza that feeds seamlessly into the maze
 373:         if chunk_pos.x.abs() < 1.0 && chunk_pos.z.abs() < 1.0 {
 374:             for z in 0..depth {
 375:                 for x in 0..width {
 376:                     grid.set(x, 0, z, VOXEL_FLOOR);
 377:                     grid.set(x, height - 1, z, VOXEL_CEILING);
 378: 
 379:                     // Add some scattered lights to the ceiling and floor so it's bright
 380:                     if x > 0 && z > 0 && x % 20 == 0 && z % 20 == 0 {
 381:                         grid.set(x, height - 1, z, VOXEL_LIGHT);
 382:                         grid.set(x, 0, z, VOXEL_LIGHT);
 383:                     }
 384:                 }
 385:             }
 386:             crate::domain::use_cases::calculate_lighting::calculate_voxel_lighting(&mut grid);
 387:             return grid;
 388:         }
 389: 
 390:         // ==========================================
 391:         // DYNAMIC GENERATION (Growing Tree & BSP)
 392:         // ==========================================
 393:         let mut rng = StdRng::seed_from_u64(
 394:             (seed as u64) ^ (chunk_pos.x.to_bits() as u64) ^ (chunk_pos.z.to_bits() as u64),
 395:         );
 396: 
 397:         let maze_gen = GrowingTreeGenerator {
 398:             junction_density: config.tuning.junction_density,
 399:         };
 400:         maze_gen.generate(&mut abstract_grid, &mut rng);
 401: 
 402:         // Organic room segmentation
 403:         let mut rooms = Vec::new();
 404:         let mut room_grid = vec![None; cell_w * cell_d];
 405: 
 406:         // Tunable parameters
 407:         let num_room_attempts = 15;
 408:         for _ in 0..num_room_attempts {
 409:             let cx = rng.random_range(0..cell_w);
 410:             let cz = rng.random_range(0..cell_d);
 411:             let rw = rng.random_range(1..=3);
 412:             let rd = rng.random_range(1..=3);
 413: 
 414:             if cx + rw <= cell_w && cz + rd <= cell_d {
 415:                 let mut overlap = false;
 416:                 for i in 0..rw {
 417:                     for j in 0..rd {
 418:                         if room_grid[(cz + j) * cell_w + cx + i].is_some() {
 419:                             overlap = true;
 420:                         }
 421:                     }
 422:                 }
 423:                 if !overlap {
 424:                     let room_id = rooms.len();
 425:                     for i in 0..rw {
 426:                         for j in 0..rd {
 427:                             room_grid[(cz + j) * cell_w + cx + i] = Some(room_id);
 428:                             if let Some(cell) = abstract_grid.get_mut(cx + i, cz + j) {
 429:                                 if j > 0 {
 430:                                     cell.walls[0] = false;
 431:                                 }
 432:                                 if i < rw - 1 {
 433:                                     cell.walls[1] = false;
 434:                                 }
 435:                                 if j < rd - 1 {
 436:                                     cell.walls[2] = false;
 437:                                 }
 438:                                 if i > 0 {
 439:                                     cell.walls[3] = false;
 440:                                 }
 441:                             }
 442:                         }
 443:                     }
 444:                     rooms.push(Room {
 445:                         name: "Organic",
 446:                         x0: cx * cell_vw,
 447:                         x1: (cx + rw) * cell_vw - 1,
 448:                         z0: cz * cell_vd,
 449:                         z1: (cz + rd) * cell_vd - 1,
 450:                     });
 451:                 }
 452:             }
 453:         }
 454: 
 455:         // Hallway reservation (Part 1)
 456:         let mut non_room_indices = Vec::new();
 457:         for i in 0..(cell_w * cell_d) {
 458:             if room_grid[i].is_none() {
 459:                 non_room_indices.push(i);
 460:             }
 461:         }
 462: 
 463:         let target_corridors = (non_room_indices.len() as f32 * 0.20) as usize;
 464:         let mut corridor_count = 0;
 465: 
 466:         use rand::seq::SliceRandom;
 467:         non_room_indices.shuffle(&mut rng);
 468: 
 469:         for &idx in &non_room_indices {
 470:             if corridor_count >= target_corridors {
 471:                 break;
 472:             }
 473:             let cx = idx % cell_w;
 474:             let cz = idx / cell_w;
 475:             if abstract_grid.get(cx, cz).unwrap().is_corridor {
 476:                 continue;
 477:             }
 478: 
 479:             abstract_grid.get_mut(cx, cz).unwrap().is_corridor = true;
 480:             corridor_count += 1;
 481: 
 482:             // Extend North
 483:             let mut current_cz = cz;
 484:             while current_cz > 0 && !abstract_grid.get(cx, current_cz).unwrap().walls[0] {
 485:                 current_cz -= 1;
 486:                 if room_grid[current_cz * cell_w + cx].is_some()
 487:                     || abstract_grid.get(cx, current_cz).unwrap().is_corridor
 488:                 {
 489:                     break;
 490:                 }
 491:                 abstract_grid.get_mut(cx, current_cz).unwrap().is_corridor = true;
 492:                 corridor_count += 1;
 493:             }
 494:             // Extend South
 495:             let mut current_cz = cz;
 496:             while current_cz < cell_d - 1 && !abstract_grid.get(cx, current_cz).unwrap().walls[2] {
 497:                 current_cz += 1;
 498:                 if room_grid[current_cz * cell_w + cx].is_some()
 499:                     || abstract_grid.get(cx, current_cz).unwrap().is_corridor
 500:                 {
 501:                     break;
 502:                 }
 503:                 abstract_grid.get_mut(cx, current_cz).unwrap().is_corridor = true;
 504:                 corridor_count += 1;
 505:             }
 506:             // Extend West
 507:             let mut current_cx = cx;
 508:             while current_cx > 0 && !abstract_grid.get(current_cx, cz).unwrap().walls[3] {
 509:                 current_cx -= 1;
 510:                 if room_grid[cz * cell_w + current_cx].is_some()
 511:                     || abstract_grid.get(current_cx, cz).unwrap().is_corridor
 512:                 {
 513:                     break;
 514:                 }
 515:                 abstract_grid.get_mut(current_cx, cz).unwrap().is_corridor = true;
 516:                 corridor_count += 1;
 517:             }
 518:             // Extend East
 519:             let mut current_cx = cx;
 520:             while current_cx < cell_w - 1 && !abstract_grid.get(current_cx, cz).unwrap().walls[1] {
 521:                 current_cx += 1;
 522:                 if room_grid[cz * cell_w + current_cx].is_some()
 523:                     || abstract_grid.get(current_cx, cz).unwrap().is_corridor
 524:                 {
 525:                     break;
 526:                 }
 527:                 abstract_grid.get_mut(current_cx, cz).unwrap().is_corridor = true;
 528:                 corridor_count += 1;
 529:             }
 530:         }
 531: 
 532:         // Draw abstract grid to VoxelGrid
 533:         for cz in 0..cell_d {
 534:             for cx in 0..cell_w {
 535:                 let cell = abstract_grid.get(cx, cz).unwrap();
 536:                 let v_x0 = cx * cell_vw;
 537:                 let v_z0 = cz * cell_vd;
 538:                 let v_x1 = v_x0 + cell_vw - 1;
 539:                 let v_z1 = v_z0 + cell_vd - 1;
 540: 
 541:                 use crate::domain::entities::cell::MicrobiomeZone;
 542:                 let cell_h_units = match cell.zone {
 543:                     MicrobiomeZone::Atrium => 12.0,
 544:                     MicrobiomeZone::Blackout => 3.2,
 545:                     _ => 4.0,
 546:                 };
 547:                 let wall_max_y = (cell_h_units / config.voxel_scale).ceil() as usize;
 548:                 let door_max_y = (2.5 / config.voxel_scale).ceil() as usize; // Doorways are 2.5 units tall
 549: 
 550:                 let wall_type = VOXEL_WALL;
 551: 
 552:                 // Floors and Ceilings
 553:                 for vx in v_x0..=v_x1 {
 554:                     for vz in v_z0..=v_z1 {
 555:                         grid.set(vx, 0, vz, VOXEL_FLOOR);
 556: 
 557:                         if cell.zone == MicrobiomeZone::Holes {
 558:                             if vx > v_x0 + 5 && vx < v_x1 - 5 && vz > v_z0 + 5 && vz < v_z1 - 5 {
 559:                                 if rng.random_bool(0.05) {
 560:                                     grid.set(vx, 0, vz, VOXEL_AIR);
 561:                                 }
 562:                             }
 563:                         }
 564: 
 565:                         if cell.zone != MicrobiomeZone::Atrium {
 566:                             // Normal ceilings with optional light
 567:                             if cell.zone != MicrobiomeZone::Blackout && (vx % 10 == 0 && vz % 10 == 0) {
 568:                                 if cell.zone == MicrobiomeZone::RedRoom {
 569:                                     grid.set(vx, wall_max_y, vz, crate::domain::entities::voxel_grid::VOXEL_RED_LIGHT);
 570:                                 } else {
 571:                                     grid.set(vx, wall_max_y, vz, VOXEL_LIGHT);
 572:                                 }
 573:                             } else {
 574:                                 grid.set(vx, wall_max_y, vz, VOXEL_CEILING);
 575:                             }
 576:                             for y in (wall_max_y + 1)..height {
 577:                                 grid.set(vx, y, vz, VOXEL_CEILING);
 578:                             }
 579:                         } else {
 580:                             // Atrium ceiling and bright skylight effect
 581:                             if (vx % 10 == 0 && vz % 10 == 0) {
 582:                                 grid.set(vx, wall_max_y, vz, VOXEL_LIGHT);
 583:                             } else {
 584:                                 grid.set(vx, wall_max_y, vz, VOXEL_CEILING);
 585:                             }
 586:                         }
 587:                     }
 588:                 }
 589: 
 590:                 if cell.zone == MicrobiomeZone::PillarField {
 591:                     for y in 1..=wall_max_y {
 592:                         grid.set(v_x0, y, v_z0, wall_type);
 593:                         grid.set(v_x1, y, v_z0, wall_type);
 594:                         grid.set(v_x0, y, v_z1, wall_type);
 595:                         grid.set(v_x1, y, v_z1, wall_type);
 596:                         if rng.random_bool(0.3) {
 597:                             grid.set(v_x0 + cell_vw / 2, y, v_z0 + cell_vd / 2, wall_type);
 598:                         }
 599:                     }
 600:                     continue;
 601:                 }
 602: 
 603:                 // South Wall (z1)
 604:                 if cz < cell_d - 1 {
 605:                     let same_room = room_grid[cz * cell_w + cx]
 606:                         == room_grid[(cz + 1) * cell_w + cx]
 607:                         && room_grid[cz * cell_w + cx].is_some();
 608: 
 609:                     if !same_room {
 610:                         let width_choice = rng.random_range(0..100);
 611:                         let hole_units = if width_choice < 15 {
 612:                             1.2
 613:                         } else if width_choice < 85 {
 614:                             2.0
 615:                         } else {
 616:                             3.5
 617:                         };
 618:                         let hole_w = (hole_units / config.voxel_scale) as usize;
 619:                         let min_offset = (0.5 / config.voxel_scale) as usize;
 620:                         let max_offset = cell_vw.saturating_sub(hole_w + min_offset);
 621:                         let offset = if max_offset > min_offset {
 622:                             rng.random_range(min_offset..max_offset)
 623:                         } else {
 624:                             min_offset
 625:                         };
 626:                         let hole_x0 = v_x0 + offset;
 627:                         let hole_x1 = hole_x0 + hole_w;
 628: 
 629:                         for vx in v_x0..=v_x1 {
 630:                             let in_hole = vx >= hole_x0 && vx < hole_x1;
 631:                             if cell.walls[2] || !in_hole {
 632:                                 for y in 1..=wall_max_y {
 633:                                     grid.set(vx, y, v_z1, wall_type);
 634:                                 }
 635:                             } else if cell.zone == MicrobiomeZone::Arch {
 636:                                 let dx =
 637:                                     (vx as isize - (hole_x0 + hole_w / 2) as isize).abs() as usize;
 638:                                 let arch_top = door_max_y;
 639:                                 let block_y = arch_top.saturating_sub(dx);
 640:                                 for y in block_y..=wall_max_y {
 641:                                     grid.set(vx, y, v_z1, wall_type);
 642:                                 }
 643:                             } else {
 644:                                 for y in door_max_y..=wall_max_y {
 645:                                     grid.set(vx, y, v_z1, wall_type);
 646:                                 }
 647:                             }
 648:                         }
 649:                     }
 650:                 } else if cz == cell_d - 1 {
 651:                     // Chunk boundary (force holes for connectivity)
 652:                     let hole_w = (2.0 / config.voxel_scale) as usize;
 653:                     let hole_x0 = v_x0 + cell_vw / 2 - hole_w / 2;
 654:                     for vx in v_x0..=v_x1 {
 655:                         let is_hole = vx >= hole_x0 && vx < hole_x0 + hole_w;
 656:                         if !is_hole {
 657:                             for y in 1..=wall_max_y {
 658:                                 grid.set(vx, y, v_z1, wall_type);
 659:                             }
 660:                         } else if cell.zone == MicrobiomeZone::Arch {
 661:                             let dx = (vx as isize - (hole_x0 + hole_w / 2) as isize).abs() as usize;
 662:                             let arch_top = door_max_y;
 663:                             let block_y = arch_top.saturating_sub(dx);
 664:                             for y in block_y..=wall_max_y {
 665:                                 grid.set(vx, y, v_z1, wall_type);
 666:                             }
 667:                         } else {
 668:                             for y in door_max_y..=wall_max_y {
 669:                                 grid.set(vx, y, v_z1, wall_type);
 670:                             }
 671:                         }
 672:                     }
 673:                 }
 674: 
 675:                 // East Wall (x1)
 676:                 if cx < cell_w - 1 {
 677:                     let same_room = room_grid[cz * cell_w + cx] == room_grid[cz * cell_w + cx + 1]
 678:                         && room_grid[cz * cell_w + cx].is_some();
 679: 
 680:                     if !same_room {
 681:                         let width_choice = rng.random_range(0..100);
 682:                         let hole_units = if width_choice < 15 {
 683:                             1.2
 684:                         } else if width_choice < 85 {
 685:                             2.0
 686:                         } else {
 687:                             3.5
 688:                         };
 689:                         let hole_w = (hole_units / config.voxel_scale) as usize;
 690:                         let min_offset = (0.5 / config.voxel_scale) as usize;
 691:                         let max_offset = cell_vd.saturating_sub(hole_w + min_offset);
 692:                         let offset = if max_offset > min_offset {
 693:                             rng.random_range(min_offset..max_offset)
 694:                         } else {
 695:                             min_offset
 696:                         };
 697:                         let hole_z0 = v_z0 + offset;
 698:                         let hole_z1 = hole_z0 + hole_w;
 699: 
 700:                         for vz in v_z0..=v_z1 {
 701:                             let in_hole = vz >= hole_z0 && vz < hole_z1;
 702:                             if cell.walls[1] || !in_hole {
 703:                                 for y in 1..=wall_max_y {
 704:                                     grid.set(v_x1, y, vz, wall_type);
 705:                                 }
 706:                             } else if cell.zone == MicrobiomeZone::Arch {
 707:                                 let dz =
 708:                                     (vz as isize - (hole_z0 + hole_w / 2) as isize).abs() as usize;
 709:                                 let arch_top = door_max_y;
 710:                                 let block_y = arch_top.saturating_sub(dz);
 711:                                 for y in block_y..=wall_max_y {
 712:                                     grid.set(v_x1, y, vz, wall_type);
 713:                                 }
 714:                             } else {
 715:                                 for y in door_max_y..=wall_max_y {
 716:                                     grid.set(v_x1, y, vz, wall_type);
 717:                                 }
 718:                             }
 719:                         }
 720:                     }
 721:                 } else if cx == cell_w - 1 {
 722:                     let hole_w = (2.0 / config.voxel_scale) as usize;
 723:                     let hole_z0 = v_z0 + cell_vd / 2 - hole_w / 2;
 724:                     for vz in v_z0..=v_z1 {
 725:                         let is_hole = vz >= hole_z0 && vz < hole_z0 + hole_w;
 726:                         if !is_hole {
 727:                             for y in 1..=wall_max_y {
 728:                                 grid.set(v_x1, y, vz, wall_type);
 729:                             }
 730:                         } else if cell.zone == MicrobiomeZone::Arch {
 731:                             let dz = (vz as isize - (hole_z0 + hole_w / 2) as isize).abs() as usize;
 732:                             let arch_top = door_max_y;
 733:                             let block_y = arch_top.saturating_sub(dz);
 734:                             for y in block_y..=wall_max_y {
 735:                                 grid.set(v_x1, y, vz, wall_type);
 736:                             }
 737:                         } else {
 738:                             for y in door_max_y..=wall_max_y {
 739:                                 grid.set(v_x1, y, vz, wall_type);
 740:                             }
 741:                         }
 742:                     }
 743:                 }
 744: 
 745:                 // Draw narrower corridors for 2+ consecutive runs
 746:                 let mut is_ns_hall = false;
 747:                 let mut is_ew_hall = false;
 748:                 if cell.is_corridor {
 749:                     let mut ns_run = 1;
 750:                     if !cell.walls[0]
 751:                         && cz > 0
 752:                         && abstract_grid.get(cx, cz - 1).unwrap().is_corridor
 753:                     {
 754:                         ns_run += 1;
 755:                     }
 756:                     if !cell.walls[2]
 757:                         && cz < cell_d - 1
 758:                         && abstract_grid.get(cx, cz + 1).unwrap().is_corridor
 759:                     {
 760:                         ns_run += 1;
 761:                     }
 762: 
 763:                     let mut ew_run = 1;
 764:                     if !cell.walls[1]
 765:                         && cx < cell_w - 1
 766:                         && abstract_grid.get(cx + 1, cz).unwrap().is_corridor
 767:                     {
 768:                         ew_run += 1;
 769:                     }
 770:                     if !cell.walls[3]
 771:                         && cx > 0
 772:                         && abstract_grid.get(cx - 1, cz).unwrap().is_corridor
 773:                     {
 774:                         ew_run += 1;
 775:                     }
 776: 
 777:                     if ns_run >= 2 {
 778:                         is_ns_hall = true;
 779:                     }
 780:                     if ew_run >= 2 {
 781:                         is_ew_hall = true;
 782:                     }
 783:                 }
 784: 
 785:                 if is_ns_hall && !is_ew_hall {
 786:                     let inset_x = (cell_vw.saturating_sub(26)) / 2;
 787:                     for vx in v_x0..=(v_x0 + inset_x) {
 788:                         for vz in v_z0..=v_z1 {
 789:                             for y in 1..=wall_max_y {
 790:                                 grid.set(vx, y, vz, wall_type);
 791:                             }
 792:                         }
 793:                     }
 794:                     for vx in (v_x1 - inset_x)..=v_x1 {
 795:                         for vz in v_z0..=v_z1 {
 796:                             for y in 1..=wall_max_y {
 797:                                 grid.set(vx, y, vz, wall_type);
 798:                             }
 799:                         }
 800:                     }
 801:                 } else if is_ew_hall && !is_ns_hall {
 802:                     let inset_z = (cell_vd.saturating_sub(26)) / 2;
 803:                     for vz in v_z0..=(v_z0 + inset_z) {
 804:                         for vx in v_x0..=v_x1 {
 805:                             for y in 1..=wall_max_y {
 806:                                 grid.set(vx, y, vz, wall_type);
 807:                             }
 808:                         }
 809:                     }
 810:                     for vz in (v_z1 - inset_z)..=v_z1 {
 811:                         for vx in v_x0..=v_x1 {
 812:                             for y in 1..=wall_max_y {
 813:                                 grid.set(vx, y, vz, wall_type);
 814:                             }
 815:                         }
 816:                     }
 817:                 } else if is_ns_hall && is_ew_hall {
 818:                     let inset_x = (cell_vw.saturating_sub(26)) / 2;
 819:                     let inset_z = (cell_vd.saturating_sub(26)) / 2;
 820:                     for y in 1..=wall_max_y {
 821:                         for vx in v_x0..=(v_x0 + inset_x) {
 822:                             for vz in v_z0..=(v_z0 + inset_z) {
 823:                                 grid.set(vx, y, vz, wall_type);
 824:                             }
 825:                         }
 826:                         for vx in (v_x1 - inset_x)..=v_x1 {
 827:                             for vz in v_z0..=(v_z0 + inset_z) {
 828:                                 grid.set(vx, y, vz, wall_type);
 829:                             }
 830:                         }
 831:                         for vx in v_x0..=(v_x0 + inset_x) {
 832:                             for vz in (v_z1 - inset_z)..=v_z1 {
 833:                                 grid.set(vx, y, vz, wall_type);
 834:                             }
 835:                         }
 836:                         for vx in (v_x1 - inset_x)..=v_x1 {
 837:                             for vz in (v_z1 - inset_z)..=v_z1 {
 838:                                 grid.set(vx, y, vz, wall_type);
 839:                             }
 840:                         }
 841:                     }
 842:                 }
 843:             }
 844:         }
 845: 
 846:         // Chunk Boundaries (North and West)
 847:         for cz in 0..cell_d {
 848:             let cell = abstract_grid.get(0, cz).unwrap();
 849:             use crate::domain::entities::cell::MicrobiomeZone;
 850:             let cell_h_units = match cell.zone {
 851:                 MicrobiomeZone::Atrium => 12.0,
 852:                 MicrobiomeZone::Blackout => 3.2,
 853:                 _ => 4.0,
 854:             };
 855:             let wall_max_y = (cell_h_units / config.voxel_scale).ceil() as usize;
 856:             let door_max_y = (2.5 / config.voxel_scale).ceil() as usize;
 857:             let wall_type = if cell.zone == MicrobiomeZone::RedRoom {
 858:                 VOXEL_RED_WALL
 859:             } else {
 860:                 VOXEL_WALL
 861:             };
 862: 
 863:             if cell.zone == MicrobiomeZone::PillarField {
 864:                 continue;
 865:             }
 866: 
 867:             let v_z0 = cz * cell_vd;
 868:             let v_z1 = v_z0 + cell_vd - 1;
 869:             let hole_w = (2.0 / config.voxel_scale) as usize;
 870:             let hole_z0 = v_z0 + cell_vd / 2 - hole_w / 2;
 871:             for vz in v_z0..=v_z1 {
 872:                 let is_hole = vz >= hole_z0 && vz < hole_z0 + hole_w;
 873:                 if !is_hole {
 874:                     for y in 1..=wall_max_y {
 875:                         grid.set(0, y, vz, wall_type);
 876:                     }
 877:                 } else if cell.zone == MicrobiomeZone::Arch {
 878:                     let dz = (vz as isize - (hole_z0 + hole_w / 2) as isize).abs() as usize;
 879:                     let arch_top = door_max_y;
 880:                     let block_y = arch_top.saturating_sub(dz);
 881:                     for y in block_y..=wall_max_y {
 882:                         grid.set(0, y, vz, wall_type);
 883:                     }
 884:                 } else {
 885:                     for y in door_max_y..=wall_max_y {
 886:                         grid.set(0, y, vz, wall_type);
 887:                     }
 888:                 }
 889:             }
 890:         }
 891:         for cx in 0..cell_w {
 892:             let cell = abstract_grid.get(cx, 0).unwrap();
 893:             use crate::domain::entities::cell::MicrobiomeZone;
 894:             let cell_h_units = match cell.zone {
 895:                 MicrobiomeZone::Atrium => 12.0,
 896:                 MicrobiomeZone::Blackout => 3.2,
 897:                 _ => 4.0,
 898:             };
 899:             let wall_max_y = (cell_h_units / config.voxel_scale).ceil() as usize;
 900:             let door_max_y = (2.5 / config.voxel_scale).ceil() as usize;
 901:             let wall_type = if cell.zone == MicrobiomeZone::RedRoom {
 902:                 VOXEL_RED_WALL
 903:             } else {
 904:                 VOXEL_WALL
 905:             };
 906: 
 907:             if cell.zone == MicrobiomeZone::PillarField {
 908:                 continue;
 909:             }
 910: 
 911:             let v_x0 = cx * cell_vw;
 912:             let v_x1 = v_x0 + cell_vw - 1;
 913:             let hole_w = (2.0 / config.voxel_scale) as usize;
 914:             let hole_x0 = v_x0 + cell_vw / 2 - hole_w / 2;
 915:             for vx in v_x0..=v_x1 {
 916:                 let is_hole = vx >= hole_x0 && vx < hole_x0 + hole_w;
 917:                 if !is_hole {
 918:                     for y in 1..=wall_max_y {
 919:                         grid.set(vx, y, 0, wall_type);
 920:                     }
 921:                 } else if cell.zone == MicrobiomeZone::Arch {
 922:                     let dx = (vx as isize - (hole_x0 + hole_w / 2) as isize).abs() as usize;
 923:                     let arch_top = door_max_y;
 924:                     let block_y = arch_top.saturating_sub(dx);
 925:                     for y in block_y..=wall_max_y {
 926:                         grid.set(vx, y, 0, wall_type);
 927:                     }
 928:                 } else {
 929:                     for y in door_max_y..=wall_max_y {
 930:                         grid.set(vx, y, 0, wall_type);
 931:                     }
 932:                 }
 933:             }
 934:         }
 935: 
 936:         // Apply Room Stamps to generated rooms
 937:         let stamps = vec![
 938:             RoomStamp::cubicles(),
 939:             RoomStamp::showroom(),
 940:             RoomStamp::waiting(),
 941:             RoomStamp::storage(),
 942:             RoomStamp::lounge(),
 943:             RoomStamp::server_room(),
 944:             RoomStamp::cafeteria(),
 945:             RoomStamp::maintenance(),
 946:         ];
 947: 
 948:         for room in &rooms {
 949:             let mut possible_stamps = Vec::new();
 950:             for stamp in &stamps {
 951:                 let max_stamps_w = (room.x1 - room.x0) / stamp.width.max(1);
 952:                 let max_stamps_d = (room.z1 - room.z0) / stamp.depth.max(1);
 953:                 if max_stamps_w > 0 && max_stamps_d > 0 {
 954:                     possible_stamps.push(stamp);
 955:                 }
 956:             }
 957:             if !possible_stamps.is_empty() {
 958:                 let mut stamp = possible_stamps[rng.random_range(0..possible_stamps.len())];
 959: 
 960:                 // Low-frequency stairs chance override
 961:                 let stairway = RoomStamp::stairway();
 962:                 if rng.random_bool(0.15 * (config.tuning.stairs_density as f64)) {
 963:                     stamp = &stairway;
 964:                 }
 965: 
 966:                 let spacing = (6.0 * (config.voxel_scale / 0.1)) as usize;
 967:                 let mut start_x = room.x0 + spacing;
 968:                 while start_x + stamp.width <= room.x1.saturating_sub(spacing) {
 969:                     let mut start_z = room.z0 + spacing;
 970:                     while start_z + stamp.depth <= room.z1.saturating_sub(spacing) {
 971:                         if self.validate_stamp_placement(&grid, room, stamp, start_x, start_z) {
 972:                             self.place_stamp(&mut grid, stamp, start_x, start_z);
 973:                         }
 974:                         start_z += stamp.depth + spacing;
 975:                     }
 976:                     start_x += stamp.width + spacing;
 977:                 }
 978:             }
 979: 
 980:             // Basic room lighting
 981:             let cx = (room.x0 + room.x1) / 2;
 982:             let is_strip = rng.random_bool(0.3); // 30% chance for strip lights
 983:             let mut z = room.z0 + 8;
 984: 
 985:             while z <= room.z1.saturating_sub(8) {
 986:                 if is_strip {
 987:                     for offset in 0..4 {
 988:                         if z + offset <= room.z1 {
 989:                             grid.set(cx, height - 1, z + offset, VOXEL_LIGHT);
 990:                         }
 991:                     }
 992:                 } else {
 993:                     grid.set(cx, height - 1, z, VOXEL_LIGHT);
 994:                 }
 995:                 z += 12;
 996:             }
 997:         }
 998: 
 999:         // Basic corridor lighting
1000:         for cz in (8..depth).step_by(16) {
1001:             for cx in (8..width).step_by(16) {
1002:                 if grid.get(cx, height - 1, cz) == VOXEL_CEILING && grid.get(cx, 1, cz) == VOXEL_AIR
1003:                 {
1004:                     grid.set(cx, height - 1, cz, VOXEL_LIGHT);
1005:                 }
1006:             }
1007:         }
1008: 
1009:         // ==========================================
1010:         // LIGHTING PROPAGATION (BFS Flood fill only)
1011:         // ==========================================
1012:         crate::domain::use_cases::calculate_lighting::calculate_voxel_lighting(&mut grid);
1013: 
1014:         // Bake directional face occlusion
1015:         crate::domain::use_cases::path_tracer::bake_face_occlusion(&mut grid);
1016: 
1017:         let elapsed_micros = self.telemetry.now_micros().saturating_sub(start_micros);
1018:         self.telemetry.log(&format!(
1019:             "[TELEMETRY] execute completed. Duration={}us, OutputVoxelGridSize={}x{}x{}",
1020:             elapsed_micros,
1021:             grid.width(),
1022:             grid.height(),
1023:             grid.depth()
1024:         ));
1025: 
1026:         grid
1027:     }
