1029:     fn validate_stamp_placement(
1030:         &self,
1031:         grid: &VoxelGrid,
1032:         room: &Room,
1033:         stamp: &RoomStamp,
1034:         start_x: usize,
1035:         start_z: usize,
1036:     ) -> bool {
1037:         if start_x < room.x0
1038:             || start_x + stamp.width > room.x1
1039:             || start_z < room.z0
1040:             || start_z + stamp.depth > room.z1
1041:         {
1042:             return false;
1043:         }
1044: 
1045:         for lz in 0..stamp.depth {
1046:             for lx in 0..stamp.width {
1047:                 let vx = start_x + lx;
1048:                 let vz = start_z + lz;
1049:                 if stamp.data[lz * stamp.width + lx] > 0 {
1050:                     if grid.get(vx, 1, vz) != VOXEL_AIR && grid.get(vx, 1, vz) != VOXEL_FLOOR {
1051:                         return false;
1052:                     }
1053:                 }
1054:             }
1055:         }
1056: 
1057:         true
1058:     }
1059: 
1060:     fn place_stamp(&self, grid: &mut VoxelGrid, stamp: &RoomStamp, start_x: usize, start_z: usize) {
1061:         let max_y = grid.height() - 2;
1062:         for sz in 0..stamp.depth {
1063:             for sx in 0..stamp.width {
1064:                 let val = stamp.data[sz * stamp.width + sx];
1065:                 let vx = start_x + sx;
1066:                 let vz = start_z + sz;
1067:                 if val == 1 {
1068:                     for y in 1..=3 {
1069:                         grid.set(vx, y, vz, VOXEL_WALL);
1070:                     }
1071:                 } else if val == 2 {
1072:                     for y in 1..=max_y {
1073:                         grid.set(vx, y, vz, VOXEL_WALL);
1074:                     }
1075:                 } else if val == 3 {
1076:                     for y in 1..=1 {
1077:                         grid.set(vx, y, vz, VOXEL_WALL);
1078:                     }
1079:                 } else if val == 4 {
1080:                     // Raised floor
1081:                     grid.set(vx, 1, vz, VOXEL_FLOOR);
1082:                     grid.set(vx, 2, vz, VOXEL_FLOOR);
1083:                 } else if val == 5 {
1084:                     // Step 1
1085:                     grid.set(vx, 1, vz, VOXEL_FLOOR);
1086:                 } else if val == 6 { // Step 2
1087:                     // Just floor, already set
1088:                 }
1089:             }
1090:         }
1091:     }
1092: }
