1234:     #[test]
1235:     fn test_microbiome_zones_generation_and_contiguous() {
1236:         use crate::domain::entities::cell::MicrobiomeZone;
1237:         use crate::frameworks_drivers::simple_noise::SimpleNoiseProvider;
1238: 
1239:         let noise = SimpleNoiseProvider::new();
1240:         let config = GeneratorConfig::high_spec();
1241:         let chunk_size = config.chunk_size;
1242:         let mut zones = std::collections::HashSet::new();
1243: 
1244:         let seed = 42;
1245:         let mut grid_zones = vec![MicrobiomeZone::Standard; 100];
1246: 
1247:         for cz in 0..10 {
1248:             for cx in 0..10 {
1249:                 let wx = 10.0 * chunk_size + (cx as f32) * 5.0;
1250:                 let wz = 10.0 * chunk_size + (cz as f32) * 5.0;
1251:                 let n = noise.evaluate_2d(
1252:                     seed ^ 0x2b8f_a43c,
1253:                     crate::entities::models::Position::new(wx * 0.05, wz * 0.05),
1254:                 );
1255: 
1256:                 let zone = if n < -0.7 {
1257:                     MicrobiomeZone::Blackout
1258:                 } else if n < -0.4 {
1259:                     MicrobiomeZone::Holes
1260:                 } else if n > 0.85 - (config.tuning.atria as f32 * 0.1) {
1261:                     MicrobiomeZone::Atrium
1262:                 } else if n > 0.6 {
1263:                     MicrobiomeZone::PillarField
1264:                 } else if n > 0.4 {
1265:                     MicrobiomeZone::Arch
1266:                 } else if n > 0.2 && n < 0.25 {
1267:                     MicrobiomeZone::RedRoom
1268:                 } else {
1269:                     MicrobiomeZone::Standard
1270:                 };
1271: 
1272:                 zones.insert(zone);
1273:                 grid_zones[cz * 10 + cx] = zone;
1274:             }
1275:         }
1276: 
1277:         assert!(zones.len() >= 2, "Expected at least 2 distinct zones");
1278: 
1279:         let mut same_neighbor_count = 0;
1280:         let mut total_neighbors = 0;
1281:         for cz in 1..9 {
1282:             for cx in 1..9 {
1283:                 let z = grid_zones[cz * 10 + cx];
1284:                 total_neighbors += 4;
1285:                 if grid_zones[(cz - 1) * 10 + cx] == z {
1286:                     same_neighbor_count += 1;
1287:                 }
1288:                 if grid_zones[(cz + 1) * 10 + cx] == z {
1289:                     same_neighbor_count += 1;
1290:                 }
1291:                 if grid_zones[cz * 10 + cx - 1] == z {
1292:                     same_neighbor_count += 1;
1293:                 }
1294:                 if grid_zones[cz * 10 + cx + 1] == z {
1295:                     same_neighbor_count += 1;
1296:                 }
1297:             }
1298:         }
1299: 
1300:         assert!(
1301:             same_neighbor_count as f32 / total_neighbors as f32 > 0.6,
1302:             "Expected zones to be highly contiguous"
1303:         );
1304:     }
