  1: //! Browser runtime driver: DOM/event plumbing, the requestAnimationFrame
  2: //! loop, pointer lock, the HUD and the 2D minimap.
  3: //!
  4: //! This module is the composition root's workhorse: it instantiates the
  5: //! concrete adapters/drivers, hands them to `application::engine::Engine`,
  6: //! and from then on only shuttles plain data across the port boundaries.
  7: 
  8: use std::cell::{Cell, RefCell};
  9: use std::rc::Rc;
 10: 
 11: use wasm_bindgen::JsCast;
 12: use wasm_bindgen::prelude::*;
 13: use web_sys::{
 14:     CanvasRenderingContext2d, Document, HtmlCanvasElement, HtmlElement, KeyboardEvent, MouseEvent,
 15:     Window,
 16: };
 17: 
 18: use vackrooms::frameworks_drivers::simple_noise::SimpleNoiseProvider;
 19: use vackrooms::use_cases::generate_chunk::GeneratorConfig;
 20: 
 21: use crate::adapters::input::InputCollector;
 22: use crate::adapters::local_chunk_source::LocalChunkSource;
 23: use crate::adapters::query_config::parse_generation_params;
 24: use crate::application::engine::{Engine, EngineConfig};
 25: use crate::application::ports::{ChunkDraw, FrameParams, RendererPort};
 26: use crate::drivers::console_telemetry::CONSOLE_TELEMETRY;
 27: use crate::drivers::cpu_canvas::CpuCanvasRenderer;
 28: use crate::drivers::webgl::WebGl2Renderer;
 29: 
 30: /// World seed shared with the native server so both render the same world.
 31: const WORLD_SEED: u32 = 42;
 32: /// HUD refresh cadence in frames.
 33: const HUD_INTERVAL: u32 = 30;
 34: /// Minimap pixels per world unit.
 35: const MINIMAP_SCALE: f64 = 12.0;
 36: 
 37: /// The two available renderer back ends. GPU raymarching is the default;
 38: /// the CPU microvoxel splatter is selected by `?renderer=cpu` or used as an
 39: /// automatic fallback when WebGL2 is unavailable.
 40: enum DriverRenderer {
 41:     Gpu(WebGl2Renderer),
 42:     Cpu(CpuCanvasRenderer),
 43: }
 44: 
 45: impl DriverRenderer {
 46:     fn resize(&mut self, width: u32, height: u32) {
 47:         match self {
 48:             DriverRenderer::Gpu(r) => r.resize(width, height),
 49:             DriverRenderer::Cpu(r) => r.resize(width, height),
 50:         }
 51:     }
 52: 
 53:     /// Base internal-resolution multiplier (further scaled by the adaptive
 54:     /// governor). Splatting every pixel on the CPU is far more expensive
 55:     /// than rasterizing a quad, so the CPU path renders much smaller and
 56:     /// lets CSS upscale with `image-rendering: pixelated`.
 57:     fn resolution_factor(&self) -> f64 {
 58:         match self {
 59:             DriverRenderer::Gpu(_) => 1.0,
 60:             DriverRenderer::Cpu(_) => 0.25,
 61:         }
 62:     }
 63: 
 64:     fn label(&self) -> &'static str {
 65:         match self {
 66:             DriverRenderer::Gpu(_) => "GPU raymarch",
 67:             DriverRenderer::Cpu(_) => "CPU splat",
 68:         }
 69:     }
 70: }
 71: 
 72: impl RendererPort for DriverRenderer {
 73:     fn upload_atlas(&mut self, texels: &[u32]) {
 74:         match self {
 75:             DriverRenderer::Gpu(r) => r.upload_atlas(texels),
 76:             DriverRenderer::Cpu(r) => r.upload_atlas(texels),
 77:         }
 78:     }
 79:     fn draw(&mut self, frame: &FrameParams, chunks: &[ChunkDraw]) {
 80:         match self {
 81:             DriverRenderer::Gpu(r) => r.draw(frame, chunks),
 82:             DriverRenderer::Cpu(r) => r.draw(frame, chunks),
 83:         }
 84:     }
 85: }
 86: 
 87: /// Engine owns its renderer behind the port; the driver also needs to call
 88: /// `resize` on the concrete type. This thin adapter shares one renderer
 89: /// between both without widening the port.
 90: struct SharedRenderer(Rc<RefCell<DriverRenderer>>);
 91: 
 92: impl RendererPort for SharedRenderer {
 93:     fn upload_atlas(&mut self, texels: &[u32]) {
 94:         self.0.borrow_mut().upload_atlas(texels);
 95:     }
 96:     fn draw(&mut self, frame: &FrameParams, chunks: &[ChunkDraw]) {
 97:         self.0.borrow_mut().draw(frame, chunks);
 98:     }
 99: }
100: 
101: /// Renderer selection: explicit `?renderer=cpu`, otherwise WebGL2 with a
102: /// logged fallback to the CPU splatter if context creation fails.
103: fn create_renderer(canvas: &HtmlCanvasElement, query: &str) -> Result<DriverRenderer, JsValue> {
104:     if query.contains("renderer=cpu") {
105:         return Ok(DriverRenderer::Cpu(CpuCanvasRenderer::new(canvas)?));
106:     }
107:     match WebGl2Renderer::new(canvas) {
108:         Ok(gpu) => Ok(DriverRenderer::Gpu(gpu)),
109:         Err(err) => {
110:             web_sys::console::warn_2(
111:                 &JsValue::from_str("WebGL2 unavailable, falling back to CPU splatting:"),
112:                 &err,
113:             );
114:             Ok(DriverRenderer::Cpu(CpuCanvasRenderer::new(canvas)?))
115:         }
116:     }
117: }
118: 
119: pub fn boot() -> Result<(), JsValue> {
120:     let window = web_sys::window().ok_or_else(|| JsValue::from_str("no window"))?;
121:     let document = window
122:         .document()
123:         .ok_or_else(|| JsValue::from_str("no document"))?;
124: 
125:     let canvas: HtmlCanvasElement = element(&document, "view")?;
126:     let minimap: HtmlCanvasElement = element(&document, "minimap")?;
127:     let overlay: HtmlElement = element(&document, "overlay")?;
128:     let status_msg: HtmlElement = element(&document, "status-msg")?;
129:     let play_msg: HtmlElement = element(&document, "play-msg")?;
130: 
131:     // ?spec=high -> 20u chunks, 5x5 streaming radius, 0.1u voxels.
132:     // Default is the low-spec profile: 10u chunks, 3x3 radius, 0.2u voxels.
133:     // Generation controls: ?seed=… (number or any text) plus the density
134:     // knobs ?pillars= ?walls= ?atria= ?lights= (multipliers, default 1).
135:     let query = window.location().search().unwrap_or_default();
136:     let gen_params = parse_generation_params(&query, WORLD_SEED);
137:     let high_spec = query.contains("spec=high");
138:     let (generator_config, engine_config) = if high_spec {
139:         (
140:             GeneratorConfig::high_spec().with_tuning(gen_params.tuning),
141:             EngineConfig {
142:                 chunk_size: 20.0,
143:                 chunk_radius: 2,
144:                 seed: gen_params.seed,
145:                 ..EngineConfig::default()
146:             },
147:         )
148:     } else {
149:         (
150:             GeneratorConfig::low_spec().with_tuning(gen_params.tuning),
151:             EngineConfig {
152:                 seed: gen_params.seed,
153:                 ..EngineConfig::default()
154:             },
155:         )
156:     };
157: 
158:     let renderer = Rc::new(RefCell::new(create_renderer(&canvas, &query)?));
159:     if let Ok(hud_renderer) = element::<HtmlElement>(&document, "hud-renderer") {
160:         hud_renderer.set_text_content(Some(renderer.borrow().label()));
161:     }
162:     let source = LocalChunkSource::with_telemetry(
163:         SimpleNoiseProvider::new(),
164:         gen_params.seed,
165:         generator_config,
166:         &CONSOLE_TELEMETRY,
167:     );
168:     let engine = Rc::new(RefCell::new(Engine::new(
169:         engine_config,
170:         Box::new(SharedRenderer(renderer.clone())),
171:         Box::new(source),
172:     )));
173:     let input = Rc::new(RefCell::new(InputCollector::new()));
174: 
175:     attach_input_listeners(&document, &canvas, &overlay, &input)?;
176:     run_frame_loop(
177:         window, document, canvas, minimap, overlay, status_msg, play_msg, renderer, engine, input,
178:     )
179: }
180: 
181: fn element<T: JsCast>(document: &Document, id: &str) -> Result<T, JsValue> {
182:     document
183:         .get_element_by_id(id)
184:         .ok_or_else(|| JsValue::from_str(&format!("missing #{id} element")))?
185:         .dyn_into::<T>()
186:         .map_err(|_| JsValue::from_str(&format!("#{id} has unexpected element type")))
187: }
188: 
189: fn attach_input_listeners(
190:     document: &Document,
191:     canvas: &HtmlCanvasElement,
192:     overlay: &HtmlElement,
193:     input: &Rc<RefCell<InputCollector>>,
194: ) -> Result<(), JsValue> {
195:     // Keyboard: KeyboardEvent.code -> MoveIntent, mapped by the input adapter.
196:     for (event, pressed) in [("keydown", true), ("keyup", false)] {
197:         let input = input.clone();
198:         let closure = Closure::<dyn FnMut(KeyboardEvent)>::new(move |e: KeyboardEvent| {
199:             if !e.repeat() {
200:                 input.borrow_mut().key_event(&e.code(), pressed);
201:             }
202:         });
203:         document.add_event_listener_with_callback(event, closure.as_ref().unchecked_ref())?;
204:         closure.forget();
205:     }
206: 
207:     // Mouse look (deltas are ignored by the adapter unless pointer-locked).
208:     {
209:         let input = input.clone();
210:         let closure = Closure::<dyn FnMut(MouseEvent)>::new(move |e: MouseEvent| {
211:             input
212:                 .borrow_mut()
213:                 .mouse_delta(e.movement_x() as f32, e.movement_y() as f32);
214:         });
215:         document.add_event_listener_with_callback("mousemove", closure.as_ref().unchecked_ref())?;
216:         closure.forget();
217:     }
218: 
219:     // Click-to-play: the overlay requests pointer lock on the render canvas.
220:     {
221:         let canvas = canvas.clone();
222:         let closure = Closure::<dyn FnMut()>::new(move || {
223:             canvas.request_pointer_lock();
224:         });
225:         overlay.add_event_listener_with_callback("click", closure.as_ref().unchecked_ref())?;
226:         closure.forget();
227:     }
228: 
229:     // Pointer-lock state drives both the input adapter and overlay visibility.
230:     {
231:         let input = input.clone();
232:         let doc_for_closure = document.clone();
233:         let overlay = overlay.clone();
234:         let closure = Closure::<dyn FnMut()>::new(move || {
235:             let locked = doc_for_closure.pointer_lock_element().is_some();
236:             input.borrow_mut().set_locked(locked);
237:             let _ = overlay
238:                 .style()
239:                 .set_property("display", if locked { "none" } else { "flex" });
240:         });
241:         document.add_event_listener_with_callback(
242:             "pointerlockchange",
243:             closure.as_ref().unchecked_ref(),
244:         )?;
245:         closure.forget();
246:     }
247: 
248:     Ok(())
249: }
250: 
251: #[allow(clippy::too_many_arguments)]
252: fn run_frame_loop(
253:     window: Window,
254:     _document: Document,
255:     canvas: HtmlCanvasElement,
256:     minimap: HtmlCanvasElement,
257:     _overlay: HtmlElement,
258:     status_msg: HtmlElement,
259:     play_msg: HtmlElement,
260:     renderer: Rc<RefCell<DriverRenderer>>,
261:     engine: Rc<RefCell<Engine>>,
262:     input: Rc<RefCell<InputCollector>>,
263: ) -> Result<(), JsValue> {
264:     let minimap_ctx: CanvasRenderingContext2d = minimap
265:         .get_context("2d")?
266:         .ok_or_else(|| JsValue::from_str("no 2d context for minimap"))?
267:         .dyn_into()?;
268: 
269:     let hud_fps: HtmlElement = element(window.document().as_ref().unwrap(), "hud-fps")?;
270:     let hud_chunks: HtmlElement = element(window.document().as_ref().unwrap(), "hud-chunks")?;
271:     let hud_nodes: HtmlElement = element(window.document().as_ref().unwrap(), "hud-nodes")?;
272:     let hud_scale: HtmlElement = element(window.document().as_ref().unwrap(), "hud-scale")?;
273: 
274:     let last_time = Rc::new(Cell::new(0.0f64));
275:     let frame_count = Rc::new(Cell::new(0u32));
276:     let hud_window_start = Rc::new(Cell::new(0.0f64));
277:     let was_ready = Rc::new(Cell::new(false));
278: 
279:     // Standard self-referential rAF closure pattern.
280:     let raf_handle: Rc<RefCell<Option<Closure<dyn FnMut(f64)>>>> = Rc::new(RefCell::new(None));
281:     let raf_handle_clone = raf_handle.clone();
282: 
283:     let loop_window = window.clone();
284:     *raf_handle.borrow_mut() = Some(Closure::new(move |time_ms: f64| {
285:         let dt = if last_time.get() > 0.0 {
286:             ((time_ms - last_time.get()) / 1000.0) as f32
287:         } else {
288:             1.0 / 60.0
289:         };
290:         last_time.set(time_ms);
291: 
292:         // Adaptive resolution: size the backing store to
293:         // window * governor scale * renderer base factor.
294:         {
295:             let scale = engine.borrow().stats().resolution_scale as f64
296:                 * renderer.borrow().resolution_factor();
297:             let target_w = (loop_window
298:                 .inner_width()
299:                 .ok()
300:                 .and_then(|v| v.as_f64())
301:                 .unwrap_or(800.0)
302:                 * scale)
303:                 .max(1.0) as u32;
304:             let target_h = (loop_window
305:                 .inner_height()
306:                 .ok()
307:                 .and_then(|v| v.as_f64())
308:                 .unwrap_or(600.0)
309:                 * scale)
310:                 .max(1.0) as u32;
311:             if canvas.width() != target_w || canvas.height() != target_h {
312:                 canvas.set_width(target_w);
313:                 canvas.set_height(target_h);
314:                 renderer.borrow_mut().resize(target_w, target_h);
315:             }
316:         }
317: 
318:         let frame_input = input.borrow_mut().take_frame();
319:         engine.borrow_mut().tick(dt, &frame_input);
320: 
321:         // Loading overlay: flip to "click to play" once the spawn chunk is in.
322:         let stats = engine.borrow().stats();
323:         if stats.ready && !was_ready.get() {
324:             was_ready.set(true);
325:             let _ = status_msg.style().set_property("display", "none");
326:             let _ = play_msg.style().set_property("display", "block");
327:         }
328: 
329:         draw_minimap(&minimap_ctx, &minimap, &engine.borrow());
330: 
331:         // HUD refresh at a fixed frame cadence.
332:         frame_count.set(frame_count.get() + 1);
333:         if frame_count.get() % HUD_INTERVAL == 0 {
334:             let elapsed = (time_ms - hud_window_start.get()) / 1000.0;
335:             if elapsed > 0.0 {
336:                 let fps = (HUD_INTERVAL as f64 / elapsed).round();
337:                 hud_fps.set_text_content(Some(&fps.to_string()));
338:             }
339:             hud_window_start.set(time_ms);
340:             hud_chunks.set_text_content(Some(&stats.resident_chunks.to_string()));
341:             hud_nodes.set_text_content(Some(&stats.atlas_nodes.to_string()));
342:             hud_scale.set_text_content(Some(&format!("{:.0}%", stats.resolution_scale * 100.0)));
343:         }
344: 
345:         // Schedule next frame.
346:         if let Some(closure) = raf_handle_clone.borrow().as_ref() {
347:             let _ = loop_window.request_animation_frame(closure.as_ref().unchecked_ref());
348:         }
349:     }));
350: 
351:     if let Some(closure) = raf_handle.borrow().as_ref() {
352:         window.request_animation_frame(closure.as_ref().unchecked_ref())?;
353:     }
354:     // Keep the closure (and everything it captures) alive forever.
355:     std::mem::forget(raf_handle);
356:     Ok(())
357: }
358: 
359: /// Top-down radar: solid collision boxes around the player, plus a player
360: /// dot and view direction line. Pure presentation — reads engine state only.
361: fn draw_minimap(ctx: &CanvasRenderingContext2d, canvas: &HtmlCanvasElement, engine: &Engine) {
362:     let w = canvas.width() as f64;
363:     let h = canvas.height() as f64;
364:     let cx = w / 2.0;
365:     let cy = h / 2.0;
366:     let player = engine.player();
367: 
368:     ctx.clear_rect(0.0, 0.0, w, h);
369:     ctx.set_fill_style_str("rgba(0, 0, 0, 0.5)");
370:     ctx.fill_rect(0.0, 0.0, w, h);
371: 
372:     ctx.set_fill_style_str("#ff5555");
373:     let range = (w / 2.0) / MINIMAP_SCALE + 1.0;
374:     for b in engine.collision_world().boxes() {
375:         let rel_x = (b.min[0] - player.position[0]) as f64;
376:         let rel_z = (b.min[2] - player.position[2]) as f64;
377:         if rel_x.abs() > range || rel_z.abs() > range {
378:             continue;
379:         }
380:         let size_x = (b.max[0] - b.min[0]) as f64 * MINIMAP_SCALE;
381:         let size_z = (b.max[2] - b.min[2]) as f64 * MINIMAP_SCALE;
382:         ctx.fill_rect(
383:             cx + rel_x * MINIMAP_SCALE,
384:             cy + rel_z * MINIMAP_SCALE,
385:             size_x.max(1.0),
386:             size_z.max(1.0),
387:         );
388:     }
389: 
390:     // Player dot.
391:     ctx.set_fill_style_str("#00ff00");
392:     ctx.begin_path();
393:     let _ = ctx.arc(cx, cy, 4.0, 0.0, std::f64::consts::TAU);
394:     ctx.fill();
395: 
396:     // View direction.
397:     ctx.set_stroke_style_str("#00ff00");
398:     ctx.set_line_width(2.0);
399:     ctx.begin_path();
400:     ctx.move_to(cx, cy);
401:     let yaw = player.yaw as f64;
402:     ctx.line_to(cx + yaw.sin() * -14.0, cy + yaw.cos() * -14.0);
403:     ctx.stroke();
404: }

