364: #[cfg(test)]
365: mod tests {
366:     use super::*;
367:     use crate::domain::entities::voxel_grid::VOXEL_AIR;
368:     use crate::frameworks_drivers::simple_noise::SimpleNoiseProvider;
369:     use crate::use_cases::generate_chunk::LevelTuning;
370: 
371:     fn generate(ox: f32, oz: f32) -> VoxelGrid {
372:         BackroomsLevel.generate(
373:             Position::new(ox, oz),
374:             42,
375:             GeneratorConfig::low_spec(),
376:             &SimpleNoiseProvider::new(),
377:         )
378:     }
379: 
380:     fn is_open(grid: &VoxelGrid, x: usize, z: usize) -> bool {
381:         grid.get(x, 1, z) == VOXEL_AIR
382:     }
383: 
384:     /// Walkable-plane connectivity: nearly all open floor must be mutually
385:     /// reachable (walls always leave doorways, pillars never seal a region).
386:     /// We exclude a 2-voxel border to avoid edge-of-chunk artifacts where
387:     /// walls at boundaries form isolated strips that would be connected by
388:     /// the adjacent chunk at runtime.
389:     #[test]
390:     fn walkable_plane_is_connected() {
391:         let grid = generate(0.0, 0.0);
392:         let (w, d) = (grid.width(), grid.depth());
393:         let margin = 2usize; // exclude edge voxels
394: 
395:         let open: Vec<(usize, usize)> = (margin..w - margin)
396:             .flat_map(|x| (margin..d - margin).map(move |z| (x, z)))
397:             .filter(|&(x, z)| is_open(&grid, x, z))
398:             .collect();
399:         assert!(
400:             open.len() > (w - 2 * margin) * (d - 2 * margin) / 2,
401:             "backrooms must be mostly open space"
402:         );
403: 
404:         // BFS from the spawn clearing (world 5,5 = local 25,25 in chunk 0,0).
405:         let mut visited = vec![false; w * d];
406:         let mut queue = std::collections::VecDeque::from([(w / 2, d / 2)]);
407:         visited[(w / 2) * d + d / 2] = true;
408:         let mut reached = 0usize;
409:         while let Some((x, z)) = queue.pop_front() {
410:             reached += 1;
411:             for (dx, dz) in [(1i64, 0i64), (-1, 0), (0, 1), (0, -1)] {
412:                 let (nx, nz) = (x as i64 + dx, z as i64 + dz);
413:                 if nx < margin as i64
414:                     || nz < margin as i64
415:                     || nx >= (w - margin) as i64
416:                     || nz >= (d - margin) as i64
417:                 {
418:                     continue;
419:                 }
420:                 let (nx, nz) = (nx as usize, nz as usize);
421:                 if !visited[nx * d + nz] && is_open(&grid, nx, nz) {
422:                     visited[nx * d + nz] = true;
423:                     queue.push_back((nx, nz));
424:                 }
425:             }
426:         }
427:         let ratio = reached as f32 / open.len() as f32;
428:         assert!(
429:             ratio > 0.95,
430:             "only {:.0}% of open floor is reachable from spawn",
