468:     fn ceilings_are_tall_and_varied() {
469:         let config = GeneratorConfig::low_spec();
470:         let s = config.voxel_scale;
471:         let mut tallest = 0usize;
472:         let mut lowest = usize::MAX;
473:         for oz in [-10.0, 0.0, 10.0] {
474:             for ox in [-10.0, 0.0, 10.0] {
475:                 let grid = generate(ox, oz);
476:                 for z in 0..grid.depth() {
477:                     for x in 0..grid.width() {
478:                         if !is_open(&grid, x, z) {
479:                             continue;
480:                         }
481:                         let mut y = 1;
482:                         while y < grid.height()
483:                             && grid.get(x, y, z) != VOXEL_CEILING
484:                             && grid.get(x, y, z) != VOXEL_LIGHT
485:                             && grid.get(x, y, z) != VOXEL_WALL
486:                         {
487:                             y += 1;
488:                         }
489:                         tallest = tallest.max(y);
490:                         lowest = lowest.min(y);
491:                     }
492:                 }
493:             }
494:         }
495:         assert!(
496:             tallest as f32 * s <= 3.1,
497:             "expected flat ceiling <= 3.1 u, tallest was {} u",
498:             tallest as f32 * s
499:         );
500:         assert!(
501:             lowest as f32 * s >= 2.1,
502:             "walkable headroom fell below 2.1 u: {} u",
503:             lowest as f32 * s
504:         );
505:     }
