551:     /// The generation knobs actually steer the output: zeroing pillars and
552:     /// walls empties the world of solids; cranking them fills it back up.
553:     #[test]
554:     fn tuning_knobs_control_density() {
555:         let noise = SimpleNoiseProvider::new();
556:         let count_solids = |tuning: LevelTuning| -> usize {
557:             let grid = BackroomsLevel.generate(
558:                 Position::new(10.0, 10.0),
559:                 42,
560:                 GeneratorConfig::low_spec().with_tuning(tuning),
561:                 &noise,
562:             );
563:             let mut n = 0;
564:             for z in 0..grid.depth() {
565:                 for x in 0..grid.width() {
566:                     if grid.get(x, 1, z) != VOXEL_AIR {
567:                         n += 1;
568:                     }
569:                 }
570:             }
571:             n
572:         };
573: 
574:         let none = count_solids(LevelTuning {
575:             pillars: 0.0,
576:             walls: 0.0,
577:             ..Default::default()
578:         });
579:         let sparse = count_solids(LevelTuning {
580:             pillars: 0.3,
581:             walls: 0.3,
582:             ..Default::default()
583:         });
584:         let default = count_solids(LevelTuning::default());
585:         let dense = count_solids(LevelTuning {
586:             pillars: 2.0,
587:             walls: 2.0,
588:             ..Default::default()
589:         });
590: 
591:         assert_eq!(none, 0, "pillars=0 walls=0 must produce an empty plane");
592:         assert!(
593:             sparse < default,
594:             "sparse ({sparse}) must be < default ({default})"
595:         );
596:         assert!(
597:             default < dense,
598:             "default ({default}) must be < dense ({dense})"
599:         );
600:     }
